export default "``x-api-key``, ``authorization``) under their lowercase\\n            names. Should only be set by MCP request handlers that need to\\n            propagate these values to nested MCP calls.\\n\\n    Returns:\\n        Dictionary mapping variable names to their values.\\n\\n    Example:\\n        headers = {\\\"X-LANGFLOW-GLOBAL-VAR-API-KEY\\\": \\\"secret\\\", \\\"x-api-key\\\": \\\"mykey\\\"}\\n        extract_global_variables_from_headers(headers)\\n        # Returns: {\\\"API-KEY\\\": \\\"secret\\\"}\\n        extract_global_variables_from_headers(headers, include_auth_headers=True)\\n        # Returns: {\\\"API-KEY\\\": \\\"secret\\\", \\\"x-api-key\\\": \\\"mykey\\\"}\\n    \\\"\\\"\\\"\\n    variables: dict[str, str] = {}\\n\\n    try:\\n        for header_name, header_value in headers.items():\\n            header_lower = header_name.lower()\\n            if header_lower.startswith(LANGFLOW_GLOBAL_VAR_HEADER_PREFIX):\\n                var_name = header_lower[len(LANGFLOW_GLOBAL_VAR_HEADER_PREFIX) :].upper()\\n                variables[var_name] = header_value\\n            elif include_auth_headers and header_lower in _AUTH_HEADERS_TO_PROPAGATE:\\n                variables[header_lower] = header_value\\n    except Exception as exc:  # noqa: BLE001\\n        # Log the error but don't raise - we want to continue execution\\n        logger.exception(\\\"Failed to extract global variables from headers: %s\\\", exc)\\n\\n    return variables\\n\\n\\ndef raise_error_if_astra_cloud_env():\\n    \\\"\\\"\\\"Raise an error if we're in an Astra cloud environment.\\\"\\\"\\\"\\n    try:\\n        raise_error_if_astra_cloud_disable_component(disable_endpoint_in_astra_cloud_msg)\\n    except Exception as e:\\n        raise HTTPException(status_code=403, detail=str(e)) from e\\n\\n\\n_FORBIDDEN_HEADER_CHARS = re.compile(r\\\"[\\\\x00-\\\\x1f\\\\x7f]\\\")\\n\\n\\ndef build_content_disposition(filename: str) -> str:\\n    \\\"\\\"\\\"Build a RFC 5987-compliant Content-Disposition header value.\\n\\n    Strips ASCII control chars (CR/LF/NUL/etc.) to prevent header injection,\\n    then produces a dual-param header: an ASCII fallback (with backslash and\\n    double-quote escaped per RFC 6266 \u00a74.1) and a percent-encoded UTF-8 param\\n    so both legacy and modern clients receive an unambiguous filename.\\n    \\\"\\\"\\\"\\n    safe_filename = _FORBIDDEN_HEADER_CHARS.sub(\\\"_\\\", filename)\\n    ascii_fallback = safe_filename.encode(\\\"ascii\\\", \\\"replace\\\").decode(\\\"ascii\\\").replace(\\\"\\\\\\\\\\\", \\\"\\\\\\\\\\\\\\\\\\\").replace('\\\"', '\\\\\\\\\\\"')\\n    encoded = quote(safe_filename, safe=\\\"\\\")\\n    return f\\\"attachment; filename=\\\\\\\"{ascii_fallback}\\\\\\\"; filename*=UTF-8''{encoded}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/execution_errors.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d37abddcb2b49fe11bb4be4ff057e77651e175d3418c42a05efe6c033983519e\",\"content\":\"\\\"\\\"\\\"Client-facing error policy for owner and delegated workflow execution.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\n\\nfrom fastapi import HTTPException\\n\\nSAFE_WORKFLOW_ERROR_MESSAGE = \\\"Workflow execution failed.\\\"\\nSAFE_TOOL_ERROR_MESSAGE = \\\"Tool execution failed.\\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ExecutionErrorDetails:\\n    \\\"\\\"\\\"The error fields that may cross an execution API boundary.\\\"\\\"\\\"\\n\\n    message: str\\n    stack_trace: str\\n\\n\\ndef error_details_for_client(\\n    error: Exception,\\n    *,\\n    expose_details: bool,\\n    message: str | None = None,\\n    stack_trace: str | None = None,\\n) -> ExecutionErrorDetails:\\n    \\\"\\\"\\\"Keep owner diagnostics while removing delegated/public runtime details.\\\"\\\"\\\"\\n    if expose_details:\\n        return ExecutionErrorDetails(\\n            message=message if message is not None else str(error),\\n            stack_trace=stack_trace or \\\"\\\",\\n        )\\n    return ExecutionErrorDetails(message=SAFE_WORKFLOW_ERROR_MESSAGE, stack_trace=\\\"\\\")\\n\\n\\ndef error_for_client(error: Exception, *, expose_details: bool) -> Exception:\\n    \\\"\\\"\\\"Return an exception suitable for serializers that accept an exception object.\\\"\\\"\\\"\\n    if expose_details:\\n        return error\\n    if isinstance(error, HTTPException):\\n        return HTTPException(\\n            status_code=error.status_code,\\n            detail=SAFE_WORKFLOW_ERROR_MESSAGE,\\n            headers=error.headers,\\n        )\\n    return RuntimeError(SAFE_WORKFLOW_ERROR_MESSAGE)\\n\\n\\ndef caller_owns_flow(flow: object, user: object) -> bool:\\n    \\\"\\\"\\\"Return whether the request actor and stored flow owner are the same principal.\\\"\\\"\\\"\\n    flow_user_id = getattr(flow, \\\"user_id\\\", None)\\n    user_id = getattr(user, \\\"id\\\", None)\\n    return flow_user_id is not None and user_id is not None and str(flow_user_id) == str(user_id)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/flow_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2c0eb59e2ad91dedb4b46ead8492411d120aeaa948368d5d322732e2cf466179\",\"content\":\"\\\"\\\"\\\"Flow graph building, cascade deletion, and public flow verification utilities.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nimport uuid\\nfrom typing import TYPE_CHECKING, Literal\\n\\nfrom fastapi import HTTPException\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.services.deps import session_scope\\nfrom sqlalchemy import delete\\nfrom sqlmodel import col, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.authorization.public_access import (\\n    PublicResourceAction,\\n    authorize_public_flow_access,\\n    public_execution_user,\\n)\\nfrom langflow.services.database.models.auth.authz import AuthzShare\\nfrom langflow.services.database.models.deployment.exceptions import (\\n    araise_if_deployment_guard_error_or_skip,\\n)\\nfrom langflow.services.database.models.deployment.guards import check_flow_has_deployed_versions\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.message.model import MessageTable\\nfrom langflow.services.database.models.traces.model import SpanTable, TraceTable\\nfrom langflow.services.database.models.transactions.model import TransactionTable\\nfrom langflow.services.database.models.user.model import UserRead\\nfrom langflow.services.database.models.vertex_builds.model import VertexBuildTable\\n\\nif TYPE_CHECKING:\\n    from langflow.services.chat.service import ChatService\\n\\n\\nasync def _get_flow_name(flow_id: uuid.UUID) -> str:\\n    async with session_scope() as session:\\n        flow = await session.get(Flow, flow_id)\\n        if flow is None:\\n            msg = f\\\"Flow {flow_id} not found\\\"\\n            raise ValueError(msg)\\n    return flow.name\\n\\n\\nasync def build_graph_from_data(flow_id: uuid.UUID | str, payload: dict, **kwargs):\\n    \\\"\\\"\\\"Build and cache the graph.\\\"\\\"\\\"\\n    # Get flow name\\n    if \\\"flow_name\\\" not in kwargs:\\n        flow_name = await _get_flow_name(flow_id if isinstance(flow_id, uuid.UUID) else uuid.UUID(flow_id))\\n    else:\\n        flow_name = kwargs[\\\"flow_name\\\"]\\n    str_flow_id = str(flow_id)\\n    session_id = kwargs.get(\\\"session_id\\\") or str_flow_id\\n\\n    graph = Graph.from_payload(payload, str_flow_id, flow_name, kwargs.get(\\\"user_id\\\"))\\n    for vertex_id in graph.has_session_id_vertices:\\n        vertex = graph.get_vertex(vertex_id)\\n        if vertex is None:\\n            msg = f\\\"Vertex {vertex_id} not found\\\"\\n            raise ValueError(msg)\\n        if not vertex.raw_params.get(\\\"session_id\\\"):\\n            vertex.update_raw_params({\\\"session_id\\\": session_id}, overwrite=True)\\n\\n    graph.session_id = session_id\\n    # Pin the caller's run_id before initialize_run so HITL resume reuses the pre-pause trace.\\n    if (caller_run_id := kwargs.get(\\\"run_id\\\")) is not None:\\n        graph.set_run_id(caller_run_id)\\n    await graph.initialize_run()\\n    return graph\\n\\n\\nasync def build_graph_from_db_no_cache(flow_id: uuid.UUID, session: AsyncSession, **kwargs):\\n    \\\"\\\"\\\"Build and cache the graph.\\\"\\\"\\\"\\n    flow: Flow | None = await session.get(Flow, flow_id)\\n    if not flow or not flow.data:\\n        msg = \\\"Invalid flow ID\\\"\\n        raise ValueError(msg)\\n    kwargs[\\\"user_id\\\"] = kwargs.get(\\\"user_id\\\") or str(flow.user_id)\\n    return await build_graph_from_data(flow_id, flow.data, flow_name=flow.name, **kwargs)\\n\\n\\nasync def build_graph_from_db(flow_id: uuid.UUID, session: AsyncSession, chat_service: ChatService, **kwargs):\\n    graph = await build_graph_from_db_no_cache(flow_id=flow_id, session=session, **kwargs)\\n    await chat_service.set_cache(str(flow_id), graph)\\n    return graph\\n\\n\\nasync def build_and_cache_graph_from_data(\\n    flow_id: uuid.UUID | str,\\n    chat_service: ChatService,\\n    graph_data: dict,\\n):  # -> Graph | Any:\\n    \\\"\\\"\\\"Build and cache the graph.\\\"\\\"\\\"\\n    # Convert flow_id to str if it's UUID\\n    str_flow_id = str(flow_id) if isinstance(flow_id, uuid.UUID) else flow_id\\n    graph = Graph.from_payload(graph_data, str_flow_id)\\n    await chat_service.set_cache(str_flow_id, graph)\\n    return graph\\n\\n\\nasync def cascade_delete_flow(session: AsyncSession, flow_id: uuid.UUID) -> bool:\\n    \\\"\\\"\\\"Delete a flow and its related rows, returning whether the flow was removed.\\\"\\\"\\\"\\n    try:\\n        await check_flow_has_deployed_versions(session, flow_id=flow_id)\\n        # TODO: Verify if deleting messages is safe in terms of session id relevance\\n        # If we delete messages directly, rather than setting flow_id to null,\\n        # it might cause unexpected behaviors because the session id could still be\\n        # used elsewhere to search for these messages.\\n        await session.exec(delete(MessageTable).where(MessageTable.flow_id == flow_id))\\n        await session.exec(delete(TransactionTable).where(TransactionTable.flow_id == flow_id))\\n        await session.exec(delete(VertexBuildTable).where(VertexBuildTable.flow_id == flow_id))\\n        # Explicit delete despite FK CASCADE -- SQLite doesn't enforce FK cascades\\n        # by default (requires PRAGMA foreign_keys = ON), and this function follows\\n        # the existing pattern of explicitly deleting all child records.\\n        await session.exec(delete(FlowVersion).where(FlowVersion.flow_id == flow_id))\\n        # span.trace_id FK lacks ON DELETE CASCADE in the DDL, so spans must\\n        # be removed before traces to avoid an FK violation under\\n        # PRAGMA foreign_keys=ON.\\n        trace_ids = (await session.exec(select(TraceTable.id).where(TraceTable.flow_id == flow_id))).all()\\n        if trace_ids:\\n            await session.exec(delete(SpanTable).where(col(SpanTable.trace_id).in_(trace_ids)))\\n            await session.exec(delete(TraceTable).where(col(TraceTable.id).in_(trace_ids)))\\n        # authz_share is polymorphic over resource_type/resource_id with no\\n        # FK, so DB cascades cannot remove stale share rows when the flow is\\n        # deleted. Clean them up here so a deleted flow's grants do not\\n        # silently survive \u2014 that would let an authorization plugin keep\\n        # honoring share rows that point at a tombstoned resource.\\n        await session.exec(\\n            delete(AuthzShare).where(AuthzShare.resource_type == \\\"flow\\\").where(AuthzShare.resource_id == flow_id)\\n        )\\n        result = await session.exec(delete(Flow).where(Flow.id == flow_id))\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=f\\\"op=cascade_delete_flow flow_id={flow_id}\\\",\\n        )\\n        msg = f\\\"Unable to cascade delete flow: {flow_id}\\\"\\n        raise RuntimeError(msg, e) from e\\n    return result.rowcount == 1\\n\\n\\n# Public flow file paths must be ``{source_flow_id}/{safe_basename}`` \u2014 uploads\\n# under that namespace are the only legitimate inputs for an unauthenticated\\n# build. Anything else (absolute paths, traversal, foreign flow_ids) is a\\n# probe at the arbitrary-file-read class of bug (GHSA-rcjh-r59h-gq37).\\n_PUBLIC_FILE_PATH_RE = re.compile(\\n    r\\\"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/([^/\\\\\\\\]+)$\\\"\\n)\\n_PUBLIC_FILE_REJECTED_SUBSTRINGS = (\\\"\\\\x00\\\", \\\"..\\\", \\\"\\\\\\\\\\\")\\n\\n\\ndef validate_public_files(files: list[str] | None, source_flow_id: uuid.UUID) -> None:\\n    \\\"\\\"\\\"Reject file references that aren't ``{source_flow_id}/{basename}``.\\n\\n    Mitigates GHSA-rcjh-r59h-gq37: an unauthenticated build must not be\\n    able to address files outside its own flow's storage namespace.\\n    Called from any endpoint that accepts caller-supplied file references\\n    under a public-access boundary.\\n    \\\"\\\"\\\"\\n    if not files:\\n        return\\n    expected_flow_id = str(source_flow_id).lower()\\n    for entry in files:\\n        if not isinstance(entry, str) or not entry:\\n            raise HTTPException(status_code=400, detail=\\\"Invalid file entry\\\")\\n        if any(token in entry for token in _PUBLIC_FILE_REJECTED_SUBSTRINGS):\\n            raise HTTPException(status_code=400, detail=\\\"Invalid file path\\\")\\n        match = _PUBLIC_FILE_PATH_RE.match(entry)\\n        if not match:\\n            raise HTTPException(status_code=400, detail=\\\"Invalid file path format\\\")\\n        flow_id_segment, basename = match.group(1), match.group(2)\\n        if flow_id_segment.lower() != expected_flow_id:\\n            raise HTTPException(status_code=400, detail=\\\"File not in this flow's namespace\\\")\\n        if basename in (\\\".\\\", \\\"..\\\"):\\n            raise HTTPException(status_code=400, detail=\\\"Invalid filename\\\")\\n\\n\\ndef compute_virtual_flow_id(\\n    identifier: str | uuid.UUID,\\n    flow_id: uuid.UUID,\\n    *,\\n    principal_type: Literal[\\\"user\\\", \\\"client\\\"] | None = None,\\n) -> uuid.UUID:\\n    \\\"\\\"\\\"Compute a deterministic virtual flow ID for session/message isolation.\\n\\n    Args:\\n        identifier: A unique identifier (user_id for authenticated users, client_id for anonymous).\\n        flow_id: The original flow ID.\\n        principal_type: Optional identity domain for public-flow callers. Authenticated\\n            user IDs and anonymous client IDs must never share a UUID namespace.\\n\\n    Returns:\\n        A deterministic UUID v5 derived from the identifier and flow_id.\\n    \\\"\\\"\\\"\\n    namespaced_identifier = f\\\"{principal_type}:{identifier}\\\" if principal_type else str(identifier)\\n    return uuid.uuid5(uuid.NAMESPACE_DNS, f\\\"{namespaced_identifier}_{flow_id}\\\")\\n\\n\\ndef scope_session_to_namespace(session: str | None, namespace: str) -> str | None:\\n    \\\"\\\"\\\"Wrap a caller-supplied session ID under a (client_id, flow_id) namespace.\\n\\n    Mitigates CVE-2026-33017: an unauthenticated public-flow caller cannot\\n    address a session that lives outside its own namespace through a Memory\\n    component, regardless of whether the caller supplies a non-empty,\\n    pre-prefixed, or empty string.\\n\\n    Returns ``None`` unchanged. Returns the value unchanged when it equals the\\n    namespace or already starts with ``f\\\"{namespace}:\\\"``. Otherwise prefixes\\n    it -- including the empty-string case, which becomes ``f\\\"{namespace}:\\\"``.\\n    \\\"\\\"\\\"\\n    if session is None:\\n        return session\\n    prefix = f\\\"{namespace}:\\\"\\n    if session == namespace or session.startswith(prefix):\\n        return session\\n    return f\\\"{prefix}{session}\\\"\\n\\n\\nasync def verify_public_flow_and_get_user(\\n    flow_id: uuid.UUID,\\n    client_id: str | None,\\n    authenticated_user_id: uuid.UUID | None = None,\\n    request_host: str | None = None,\\n) -> tuple[UserRead, uuid.UUID]:\\n    \\\"\\\"\\\"Verify a public flow request and generate a deterministic flow ID.\\n\\n    This utility function:\\n    1. Checks that a client_id cookie or authenticated_user_id is provided\\n    2. Verifies an explicit or compatibility-derived PUBLIC grant\\n    3. Creates a deterministic UUID based on the identifier and original flow_id\\n    4. Returns the stable non-user execution principal\\n\\n    When an authenticated_user_id is provided, it takes precedence over client_id\\n    for UUID v5 generation. This enables DB-persisted sessions for logged-in users\\n    on the shareable playground.\\n\\n    Args:\\n        flow_id: The original flow ID to verify\\n        client_id: The client ID from the request cookie\\n        authenticated_user_id: The authenticated user's ID (takes precedence over client_id)\\n        request_host: Trusted request hostname supplied to the tenant-resolution plugin seam.\\n\\n    Returns:\\n        tuple: (anonymous execution principal, deterministic flow ID for tracking)\\n\\n    Raises:\\n        HTTPException:\\n            - 400 if neither client_id nor authenticated_user_id is provided\\n            - 404 if the flow or its direct-link grant is unavailable\\n    \\\"\\\"\\\"\\n    if not client_id and not authenticated_user_id:\\n        raise HTTPException(status_code=400, detail=\\\"No client_id cookie found\\\")\\n\\n    # Load only the exact direct-link resource; this path never enumerates flows.\\n    async with session_scope() as session:\\n        flow = (await session.exec(select(Flow).where(Flow.id == flow_id))).first()\\n        if flow is None:\\n            raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n        await authorize_public_flow_access(\\n            flow=flow,\\n            action=PublicResourceAction.EXECUTE,\\n            request_host=request_host,\\n            session=session,\\n        )\\n\\n    # Use authenticated user_id for deterministic UUID when available, otherwise client_id.\\n    # Keep the branches explicit so identifier is non-optional at the UUID boundary.\\n    if authenticated_user_id is not None:\\n        identifier = str(authenticated_user_id)\\n        principal_type: Literal[\\\"user\\\", \\\"client\\\"] = \\\"user\\\"\\n    else:\\n        if client_id is None:\\n            raise HTTPException(status_code=400, detail=\\\"No client_id cookie found\\\")\\n        identifier = client_id\\n        principal_type = \\\"client\\\"\\n    new_flow_id = compute_virtual_flow_id(identifier, flow_id, principal_type=principal_type)\\n\\n    return public_execution_user(), new_flow_id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/ingestion_run_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f0125d7c93d32220aec47e0f1388674241b2dfc4b90c91e38245d60371f0164f\",\"content\":\"\\\"\\\"\\\"KB ingestion-run persistence on top of the unified ``job`` table.\\n\\nPer the unification work in #12903 / #12940, async work is tracked\\nexclusively through the ``job`` table via ``execute_with_status``. KB\\ningestion follows the same pattern: a single ``job`` row carries\\nstatus, lifecycle timestamps, and per-domain progress data on its\\n``job_metadata`` JSON column. The legacy ``ingestion_run`` table has\\nbeen dropped.\\n\\nFunction signatures here remain identifier-agnostic so callers don't\\nneed to learn the new model \u2014 what was once the ``run_id`` is now the\\n``job_id`` returned by ``create_run``. Read endpoints continue to\\nreturn the same shape (``RunRow``) so the frontend doesn't change.\\n\\nEach call opens its own ``session_scope``: an ingestion run can span\\nmany minutes, and holding one session open across the whole operation\\nwould block connection-pool slots for large background jobs.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID\\n\\nfrom lfx.base.knowledge_bases.ingestion_sources.base import (\\n    IngestionItemStatus,\\n    IngestionRunStatus,\\n    IngestionSummary,\\n)\\nfrom lfx.log.logger import logger\\nfrom sqlalchemy import func\\nfrom sqlmodel import select\\n\\nfrom langflow.services.database.models.jobs.model import Job, JobType\\nfrom langflow.services.deps import session_scope\\n\\nif TYPE_CHECKING:\\n    from lfx.base.knowledge_bases.ingestion_sources.base import KBIngestionSource\\n\\n\\n@dataclass\\nclass RunRow:\\n    \\\"\\\"\\\"Read-side projection of a KB ingestion run.\\n\\n    Built from a ``Job`` row plus its ``job_metadata`` blob. Mirrors\\n    the legacy ``IngestionRun`` attribute names so the existing\\n    serializer (``_run_row_to_info``) and the frontend response shape\\n    don't need to change.\\n    \\\"\\\"\\\"\\n\\n    id: UUID\\n    kb_name: str\\n    kb_id: UUID | None\\n    job_id: UUID\\n    user_id: UUID | None\\n    source_type: str\\n    source_config: dict[str, Any]\\n    status: str\\n    error_message: str | None\\n    total_items: int\\n    succeeded: int\\n    failed: int\\n    skipped: int\\n    total_bytes: int\\n    chunks_created: int\\n    items: list[dict[str, Any]]\\n    user_metadata: dict[str, Any]\\n    started_at: datetime\\n    finished_at: datetime | None\\n\\n\\nasync def create_run(\\n    *,\\n    kb_name: str,\\n    source: KBIngestionSource,\\n    job_id: UUID | None,\\n    user_id: UUID | None,  # noqa: ARG001 \u2014 kept for caller signature compatibility\\n    kb_id: UUID | None = None,\\n    user_metadata: dict | None = None,\\n) -> UUID | None:\\n    \\\"\\\"\\\"Initialise a KB-ingestion run on the job-metadata side.\\n\\n    The parent ``job`` row is created upstream by the API layer (see\\n    ``knowledge_bases.py::ingest_files`` and friends) before\\n    ``execute_with_status`` is invoked. This call seeds ``job_metadata``\\n    with the static config (kb_name, kb_id, source_type, source_config,\\n    user_metadata) and a PENDING status.\\n\\n    ``user_metadata`` carries the run-level tags supplied at the API\\n    boundary (already validated by ``parse_user_metadata``). Persisted\\n    onto the same ``job_metadata`` blob as the rest of the run state\\n    so the run-history UI can render the tags without decoding the\\n    per-chunk ``source_metadata`` blobs.\\n\\n    Returns the ``job_id`` so callers can use it as the legacy\\n    ``run_id`` handle. Returns ``None`` when ``job_id`` is missing \u2014\\n    no current call site should hit this path, but defensively we\\n    no-op rather than crash so a misconfigured ingestion still records\\n    its data in-memory.\\n    \\\"\\\"\\\"\\n    if job_id is None:\\n        await logger.awarning(\\\"create_run called without job_id; skipping job_metadata seed\\\")\\n        return None\\n\\n    description = source.describe()\\n    source_config = description.get(\\\"config\\\") or {}\\n\\n    await _patch_job_metadata(\\n        job_id,\\n        {\\n            \\\"kind\\\": \\\"kb_ingestion\\\",\\n            \\\"kb_name\\\": kb_name,\\n            \\\"kb_id\\\": str(kb_id) if kb_id is not None else None,\\n            \\\"source_type\\\": source.source_type.value,\\n            \\\"source_config\\\": source_config,\\n            \\\"user_metadata\\\": user_metadata or {},\\n            \\\"status\\\": IngestionRunStatus.PENDING.value,\\n            \\\"started_at\\\": datetime.now(timezone.utc).isoformat(),\\n            # Legacy alias preserved for any code path still referring\\n            # to ``ingestion_run_id``. Equal to ``job_id`` post-cutover.\\n            \\\"ingestion_run_id\\\": str(job_id),\\n        },\\n    )\\n    return job_id\\n\\n\\nasync def mark_running(run_id: UUID) -> None:\\n    \\\"\\\"\\\"Transition a run from PENDING to RUNNING.\\n\\n    ``run_id`` is the parent ``job_id``. No-ops cleanly if the row is\\n    missing.\\n    \\\"\\\"\\\"\\n    await _patch_job_metadata(run_id, {\\\"status\\\": IngestionRunStatus.RUNNING.value})\\n\\n\\nasync def finalize_run(\\n    run_id: UUID,\\n    *,\\n    summary: IngestionSummary,\\n    status: IngestionRunStatus,\\n    error_message: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Persist the final counters, items, and outcome for ``run_id``.\\n\\n    Called from ``perform_ingestion`` in its ``finally`` block \u2014 must\\n    not raise on summary inconsistencies, otherwise the ingestion\\n    itself is fine but the UI shows a missing run. Errors are logged\\n    and swallowed.\\n    \\\"\\\"\\\"\\n    serialized_items = [_serialize_item(item) for item in summary.items]\\n    finished_at = datetime.now(timezone.utc)\\n    try:\\n        await _patch_job_metadata(\\n            run_id,\\n            {\\n                \\\"status\\\": status.value,\\n                \\\"error_message\\\": error_message,\\n                \\\"total_items\\\": summary.total_items,\\n                \\\"succeeded\\\": summary.succeeded,\\n                \\\"failed\\\": summary.failed,\\n                \\\"skipped\\\": summary.skipped,\\n                \\\"total_bytes\\\": summary.total_bytes,\\n                \\\"chunks_created\\\": summary.chunks_created,\\n                \\\"items\\\": serialized_items,\\n                \\\"finished_at\\\": finished_at.isoformat(),\\n            },\\n        )\\n    except Exception as exc:  # noqa: BLE001\\n        await logger.aerror(\\\"Failed to finalize ingestion run %s: %s\\\", run_id, exc)\\n\\n\\ndef _serialize_item(item) -> dict:\\n    \\\"\\\"\\\"Convert an ``IngestionItemResult`` into a JSON-safe dict.\\\"\\\"\\\"\\n    status = item.status.value if isinstance(item.status, IngestionItemStatus) else item.status\\n    return {\\n        \\\"item_id\\\": item.item_id,\\n        \\\"display_name\\\": item.display_name,\\n        \\\"status\\\": status,\\n        \\\"chunks_created\\\": item.chunks_created,\\n        \\\"error_message\\\": item.error_message,\\n    }\\n\\n\\nasync def list_runs_for_kb(\\n    *,\\n    kb_name: str,\\n    user_id: UUID,\\n    page: int = 1,\\n    limit: int = 50,\\n) -> tuple[list[RunRow], int]:\\n    \\\"\\\"\\\"Return a page of KB ingestion runs for ``kb_name`` scoped to ``user_id``.\\n\\n    Prefers the indexed ``Job.asset_id`` filter (resolved via\\n    ``KnowledgeBaseRecord.id``) over a JSON-extract on\\n    ``Job.job_metadata.kb_name``. The asset_id path is a btree index\\n    lookup, free of dialect-specific JSON gymnastics; the JSON-extract\\n    fallback only fires for legacy KBs that exist on disk but haven't\\n    been backfilled into the ``knowledge_base`` table yet.\\n\\n    Ordered newest-first by ``Job.created_timestamp`` \u2014 the drill-down\\n    UI reads the most recent run the vast majority of the time.\\n    \\\"\\\"\\\"\\n    # Lazy import: ``ingestion_run_service`` lives in the langflow API\\n    # surface but the KB record lookup is also there; avoid a circular\\n    # at module import time.\\n    from langflow.api.utils import knowledge_base_service\\n\\n    offset = max(page - 1, 0) * limit\\n    kb_record = await knowledge_base_service.get_by_user_and_name(user_id, kb_name)\\n\\n    async with session_scope() as session:\\n        if kb_record is not None:\\n            base_filter = (\\n                (Job.user_id == user_id)\\n                & (Job.type == JobType.INGESTION)\\n                & (Job.asset_type == \\\"knowledge_base\\\")\\n                & (Job.asset_id == kb_record.id)\\n            )\\n        else:\\n            # Legacy fallback for KBs not yet reconciled into the DB.\\n            kb_name_expr = Job.job_metadata[\\\"kb_name\\\"].as_string()\\n            base_filter = (Job.user_id == user_id) & (Job.type == JobType.INGESTION) & (kb_name_expr == kb_name)\\n\\n        count_stmt = select(func.count()).select_from(Job).where(base_filter)\\n        total = (await session.exec(count_stmt)).one()\\n\\n        page_stmt = (\\n            select(Job)\\n            .where(base_filter)\\n            .order_by(Job.created_timestamp.desc())  # type: ignore[attr-defined]\\n            .offset(offset)\\n            .limit(limit)\\n        )\\n        rows = list((await session.exec(page_stmt)).all())\\n\\n    return [_job_to_run_row(j) for j in rows], int(total)\\n\\n\\nasync def get_run(run_id: UUID, *, user_id: UUID) -> RunRow | None:\\n    \\\"\\\"\\\"Fetch a single run, scoped to ``user_id`` for authz.\\n\\n    ``run_id`` is the parent ``job_id``. Returns ``None`` when the row\\n    is missing OR belongs to someone else \u2014 the caller maps both to\\n    404 so a user can't enumerate other users' run ids.\\n\\n    Also returns ``None`` for jobs of the wrong type (e.g. a workflow\\n    job_id submitted to a KB runs endpoint), since the response shape\\n    is KB-specific.\\n    \\\"\\\"\\\"\\n    async with session_scope() as session:\\n        job = await session.get(Job, run_id)\\n    if job is None or job.user_id != user_id or job.type != JobType.INGESTION:\\n        return None\\n    return _job_to_run_row(job)\\n\\n\\ndef _job_to_run_row(job: Job) -> RunRow:\\n    \\\"\\\"\\\"Project a ``Job`` row into the legacy ``RunRow`` shape.\\n\\n    Counters / per-item outcomes live on ``job_metadata``; lifecycle\\n    timestamps come from the ``job`` row itself so they reflect the\\n    canonical ``execute_with_status`` lifecycle (not whatever the\\n    ingestion code happened to write).\\n    \\\"\\\"\\\"\\n    metadata: dict[str, Any] = dict(job.job_metadata or {})\\n    kb_id_raw = metadata.get(\\\"kb_id\\\")\\n    return RunRow(\\n        id=job.job_id,\\n        kb_name=metadata.get(\\\"kb_name\\\", \\\"\\\"),\\n        kb_id=UUID(kb_id_raw) if isinstance(kb_id_raw, str) and kb_id_raw else None,\\n        job_id=job.job_id,\\n        user_id=job.user_id,\\n        source_type=metadata.get(\\\"source_type\\\", \\\"\\\"),\\n        source_config=dict(metadata.get(\\\"source_config\\\") or {}),\\n        status=metadata.get(\\\"status\\\", IngestionRunStatus.PENDING.value),\\n        error_message=metadata.get(\\\"error_message\\\"),\\n        total_items=int(metadata.get(\\\"total_items\\\", 0) or 0),\\n        succeeded=int(metadata.get(\\\"succeeded\\\", 0) or 0),\\n        failed=int(metadata.get(\\\"failed\\\", 0) or 0),\\n        skipped=int(metadata.get(\\\"skipped\\\", 0) or 0),\\n        total_bytes=int(metadata.get(\\\"total_bytes\\\", 0) or 0),\\n        chunks_created=int(metadata.get(\\\"chunks_created\\\", 0) or 0),\\n        items=list(metadata.get(\\\"items\\\") or []),\\n        user_metadata=dict(metadata.get(\\\"user_metadata\\\") or {}),\\n        started_at=job.created_timestamp,\\n        finished_at=job.finished_timestamp,\\n    )\\n\\n\\nasync def _patch_job_metadata(job_id: UUID, patch: dict[str, Any]) -> None:\\n    \\\"\\\"\\\"Shallow-merge ``patch`` into ``job.job_metadata`` (creating it if needed).\\n\\n    Best-effort: a missing job row, a stale session, or an in-flight\\n    enum migration on ``status`` should never crash the ingestion. The\\n    parent caller in ``perform_ingestion`` already has its own\\n    ``finally`` cleanup; this layer just records the data.\\n    \\\"\\\"\\\"\\n    try:\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return\\n            existing = job.job_metadata or {}\\n            job.job_metadata = {**existing, **patch}\\n            session.add(job)\\n            await session.commit()\\n    except Exception as exc:  # noqa: BLE001\\n        await logger.awarning(\\\"Job metadata write failed for %s: %s\\\", job_id, exc)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/kb_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ddce41f1e3d649308909f898b596faef50ce131f91326843dda5aed3c46c33a4\",\"content\":\"import asyncio\\nimport contextlib\\nimport gc\\nimport json\\nimport shutil\\nimport time\\nimport uuid\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nimport chromadb\\nimport chromadb.errors\\nimport pandas as pd\\nfrom chromadb.api.shared_system_client import SharedSystemClient\\nfrom chromadb.config import Settings\\nfrom langchain_chroma import Chroma\\nfrom langchain_core.documents import Document\\nfrom langchain_text_splitters import RecursiveCharacterTextSplitter\\nfrom lfx.base.data.utils import extract_text_from_bytes\\nfrom lfx.base.knowledge_bases.backends import BackendType, create_backend, is_local_chroma\\nfrom lfx.base.knowledge_bases.backends.base import (\\n    METADATA_KEY_CHUNK_INDEX,\\n    METADATA_KEY_FILE_NAME,\\n    METADATA_KEY_INGESTED_AT,\\n    METADATA_KEY_JOB_ID,\\n    METADATA_KEY_SOURCE,\\n    METADATA_KEY_SOURCE_METADATA,\\n    METADATA_KEY_SOURCE_TYPE,\\n    METADATA_KEY_TOTAL_CHUNKS,\\n    BackendConfigurationError,\\n    BaseVectorStoreBackend,\\n)\\nfrom lfx.base.knowledge_bases.ingestion_sources import (\\n    FileUploadSource,\\n    IngestionItemResult,\\n    IngestionSummary,\\n    KBIngestionSource,\\n)\\nfrom lfx.base.knowledge_bases.ingestion_sources.base import IngestionItemStatus, IngestionRunStatus\\nfrom lfx.base.vectorstores.chroma_security import chroma_langchain_collection_kwargs\\nfrom lfx.components.models_and_agents.embedding_model import EmbeddingModelComponent\\nfrom lfx.log import logger\\n\\nfrom langflow.api.utils import CurrentActiveUser\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom langflow.services.database.models.knowledge_base.model import KnowledgeBaseStatus\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.services.jobs.service import JobService\\nfrom langflow.utils.kb_constants import (\\n    DELETE_BACKOFF_SECONDS,\\n    EXPONENTIAL_BACKOFF_MULTIPLIER,\\n    INGESTION_BATCH_SIZE,\\n    MAX_DELETE_RETRIES,\\n    MAX_RETRY_ATTEMPTS,\\n)\\n\\n# Default ingestion source type written to every chunk created via the\\n# direct file-upload path. Phase 1 will introduce additional source types\\n# (folder, connectors, URL, template) through the ingestion-source registry.\\nDEFAULT_INGESTION_SOURCE_TYPE = \\\"file_upload\\\"\\n\\n# Marker file dropped inside a KB directory whose row has been deleted from\\n# the DB but whose on-disk contents could not be removed (most commonly\\n# because Chroma still holds an exclusive SQLite lock on Windows).  Listing\\n# code paths skip directories containing this file so the deleted KB does\\n# not reappear in the UI before the next server restart cleans up the dir.\\nKB_DELETED_SENTINEL = \\\".kb_deleted\\\"\\n\\n\\nclass IngestionCancelledError(Exception):\\n    \\\"\\\"\\\"Custom error for when an ingestion job is cancelled.\\\"\\\"\\\"\\n\\n\\ndef chunk_text_for_ingestion(\\n    text: str,\\n    *,\\n    chunk_size: int = 1000,\\n    chunk_overlap: int = 100,\\n    separator: str | None = None,\\n) -> list[str]:\\n    r\\\"\\\"\\\"Split text into chunks using ``RecursiveCharacterTextSplitter``.\\n\\n    Single source of truth for chunking config used by every ingestion path \u2014\\n    KB file ingestion and Memory Base raw / preprocessed message ingestion.\\n    Centralizing this keeps chunk-size / overlap behavior identical so a\\n    chunk that fits in one path won't suddenly overflow in another.\\n\\n    ``separator``: when provided, escaped newlines (``\\\"\\\\\\\\n\\\"``) are unescaped\\n    and the value is passed as a single-element ``separators`` list, matching\\n    the behavior of ``KBIngestionHelper.perform_ingestion``.\\n\\n    Returns ``[]`` for empty / whitespace-only input.\\n    \\\"\\\"\\\"\\n    if not text or not text.strip():\\n        return []\\n    splitter_kwargs: dict = {\\\"chunk_size\\\": chunk_size, \\\"chunk_overlap\\\": chunk_overlap}\\n    if separator:\\n        splitter_kwargs[\\\"separators\\\"] = [separator.replace(\\\"\\\\\\\\n\\\", \\\"\\\\n\\\")]\\n    splitter = RecursiveCharacterTextSplitter(**splitter_kwargs)\\n    return splitter.split_text(text)\\n\\n\\ndef _coerce_backend_config_value(value: Any) -> dict[str, Any]:\\n    \\\"\\\"\\\"Normalize a stored ``backend_config`` into a plain dict.\\\"\\\"\\\"\\n    if isinstance(value, dict):\\n        return dict(value)\\n    return {}\\n\\n\\ndef validate_kb_name(kb_name: str) -> None:\\n    \\\"\\\"\\\"Reject a KB name that could escape the per-user KB namespace.\\n\\n    Must run before persistence for **every** backend. Remote backends\\n    (OpenSearch / Chroma Cloud / Mongo / Astra / Postgres) resolve no local\\n    path, so the containment guard in :func:`resolve_local_store_path` never\\n    runs for them \u2014 without this a crafted name such as\\n    ``../victim_user/evil_kb`` would be accepted and persisted verbatim. That\\n    both collides with another user's KB namespace and, once such a row is\\n    reconciled onto local Chroma, escapes the KB root on disk.\\n\\n    Path separators and parent-directory segments have no legitimate place in a\\n    KB name (spaces are the only structural character the create path allows,\\n    and it maps them to underscores before this runs), so rejecting them is a\\n    backend-independent guard rather than a filesystem one.\\n    \\\"\\\"\\\"\\n    if not kb_name:\\n        msg = \\\"KB name is empty\\\"\\n        raise ValueError(msg)\\n    if \\\"\\\\x00\\\" in kb_name:\\n        msg = \\\"KB name contains a null byte\\\"\\n        raise ValueError(msg)\\n    if \\\"/\\\" in kb_name or \\\"\\\\\\\\\\\" in kb_name:\\n        msg = \\\"KB name contains a path separator\\\"\\n        raise ValueError(msg)\\n    # With separators already rejected the name is a single path segment, so the\\n    # only remaining traversal form is the segment being a bare '.' or '..'.\\n    if kb_name in {\\\".\\\", \\\"..\\\"}:\\n        msg = \\\"KB name is a directory-traversal segment\\\"\\n        raise ValueError(msg)\\n\\n\\ndef validate_kb_path(kb_root: Path, kb_path: Path) -> None:\\n    \\\"\\\"\\\"Assert that ``kb_path`` is contained within ``kb_root`` (path traversal guard).\\n\\n    Prevents crafted usernames or KB names with '..' segments from escaping the KB\\n    root directory. Follows the same pattern as ``services/storage/local.py:save_file``.\\n\\n    Defined here rather than in ``memory_base.kb_path_helpers`` (which re-exports it\\n    for its long-standing importers) because that module already depends on this one;\\n    hosting the guard in the lower-level module keeps the import graph acyclic.\\n    \\\"\\\"\\\"\\n    kb_root_resolved = kb_root.resolve()\\n    kb_path_resolved = kb_path.resolve()\\n    if not kb_path_resolved.is_relative_to(kb_root_resolved):\\n        msg = \\\"KB path escapes root directory\\\"\\n        raise ValueError(msg)\\n\\n\\ndef local_chroma_rejection_reason(\\n    backend_type: str | None,\\n    backend_config: dict[str, Any] | None,\\n    *,\\n    resource: str = \\\"knowledge base\\\",\\n) -> str | None:\\n    \\\"\\\"\\\"Explain why local Chroma is unavailable here, or ``None`` when it is fine.\\n\\n    Local Chroma writes vectors to the serving box's own filesystem: they do not\\n    survive a replica restart, cannot be shared between replicas, and scale with\\n    the machine rather than the cluster. The production profile therefore refuses\\n    it and expects pgVector, OpenSearch, or Chroma Cloud instead.\\n\\n    This create-time check is the only enforcement needed. Prod boot already\\n    requires a reachable pgVector (``preflight.probe_pgvector`` is a *required*\\n    check that aborts startup), so ``resolve_default_kb_backend()`` never falls\\n    back to Chroma there \u2014 local Chroma can only arrive as an explicit client\\n    selection.\\n\\n    Returns the message rather than raising so HTTP routes and service-layer\\n    callers can wrap it in their own error type without duplicating the rule.\\n    \\\"\\\"\\\"\\n    if not is_local_chroma(backend_type, backend_config):\\n        return None\\n    if get_settings_service().settings.deployment_profile != \\\"prod\\\":\\n        return None\\n    return (\\n        f\\\"Local Chroma is not available in the production deployment profile, so this {resource} \\\"\\n        \\\"cannot be created with it. Choose a shared vector store (pgVector, OpenSearch, or Chroma \\\"\\n        \\\"Cloud), or run with LANGFLOW_DEPLOYMENT_PROFILE=dev for local-only storage.\\\"\\n    )\\n\\n\\ndef resolve_local_store_path(\\n    kb_name: str,\\n    kb_username: str,\\n    *,\\n    backend_type: str | None,\\n    backend_config: dict[str, Any] | None,\\n    create: bool = False,\\n) -> Path | None:\\n    \\\"\\\"\\\"Return the on-disk directory for a KB, or ``None`` when it needs no disk.\\n\\n    The single place KB code turns a ``(backend_type, backend_config)`` pair into\\n    a filesystem location, so \\\"does this KB touch disk?\\\" has exactly one answer.\\n\\n    Returns ``None`` for every non-local-Chroma backend **without reading\\n    settings or touching the filesystem** \u2014 notably without calling\\n    ``KBStorageHelper.get_root_path()``, which raises when ``knowledge_bases_dir``\\n    is unset. That is what lets a deployment with no local storage at all serve\\n    remote-backed KBs.\\n\\n    For local Chroma it resolves ``<root>/<username>/<kb_name>``, containment-checks\\n    it against the root, and creates it when ``create=True``.\\n\\n    Deliberately does **not** raise when the directory is absent. Existence is a\\n    property of the ``knowledge_base`` row, not of the filesystem: Chroma creates\\n    its directory lazily on first write, so a KB that has been created but never\\n    ingested into legitimately has no directory yet.\\n    \\\"\\\"\\\"\\n    if not is_local_chroma(backend_type, backend_config):\\n        return None\\n\\n    kb_root = KBStorageHelper.get_root_path()\\n    kb_user_path = (kb_root / kb_username).resolve()\\n    kb_path = (kb_user_path / kb_name).resolve()\\n    # The username roots the path, so check it against the real root first: a\\n    # username containing \\\"..\\\" would otherwise escape before the kb_name check.\\n    validate_kb_path(kb_root, kb_user_path)\\n    validate_kb_path(kb_user_path, kb_path)\\n\\n    if create:\\n        kb_path.mkdir(parents=True, exist_ok=True)\\n    return kb_path\\n\\n\\nasync def resolve_backend_selection(\\n    *,\\n    user_id: uuid.UUID,\\n    kb_name: str,\\n) -> tuple[str, dict[str, Any]]:\\n    \\\"\\\"\\\"Resolve ``(backend_type, backend_config)`` for a KB from its ``knowledge_base`` row.\\n\\n    The row is the sole authority. When there is no row this raises rather than\\n    assuming local storage: guessing would write a remote-backed KB into a local\\n    Chroma directory while queries followed the real config to the configured\\n    cluster and returned nothing, with no error anywhere.\\n\\n    Reads no filesystem, so it behaves identically on a replica whose local disk\\n    never held the KB directory. KB directories written by a Langflow version that\\n    predates the row are adopted by ``langflow reconcile-kb-from-disk``, not by an\\n    implicit fallback here.\\n\\n    Shared by Knowledge Bases and Memory Bases so the two cannot drift apart.\\n    \\\"\\\"\\\"\\n    from langflow.api.utils import knowledge_base_service\\n\\n    record = await knowledge_base_service.get_by_user_and_name(user_id, kb_name)\\n    if record is not None:\\n        return (\\n            record.backend_type or BackendType.CHROMA.value,\\n            _coerce_backend_config_value(record.backend_config),\\n        )\\n\\n    msg = (\\n        f\\\"Cannot determine the vector-store backend for '{kb_name}': it has no knowledge_base record. \\\"\\n        \\\"Refusing to fall back to local storage, which would write to a different store than queries \\\"\\n        \\\"read from. If this knowledge base predates the database-backed metadata, adopt it with \\\"\\n        \\\"'langflow reconcile-kb-from-disk'.\\\"\\n    )\\n    raise ValueError(msg)\\n\\n\\n# Last-resort embedding when the row records none. Matches the historical\\n# fallback in ``resolve_embedding`` so behavior is unchanged for callers that\\n# relied on it.\\n_DEFAULT_EMBEDDING_PROVIDER = \\\"OpenAI\\\"\\n_DEFAULT_EMBEDDING_MODEL = \\\"text-embedding-3-small\\\"\\n\\n\\nasync def resolve_embedding_selection(\\n    *,\\n    user_id: uuid.UUID,\\n    kb_name: str,\\n) -> tuple[str, str]:\\n    \\\"\\\"\\\"Resolve ``(embedding_provider, embedding_model)`` for a KB from its ``knowledge_base`` row.\\n\\n    Counterpart to :func:`resolve_backend_selection`: the row's ``model_selection``\\n    is authoritative and a hardcoded default is the only fallback. Unlike the\\n    backend, a missing embedding selection is recoverable \u2014 the default is a real,\\n    working model \u2014 so this returns rather than raising.\\n\\n    Reads no filesystem, so a Knowledge Base or Memory Base resolves identically on\\n    any replica.\\n\\n    Shared by Knowledge Bases and Memory Bases so the two cannot drift apart.\\n    \\\"\\\"\\\"\\n    from langflow.api.utils import knowledge_base_service\\n    from langflow.api.utils.knowledge_base_service import get_embedding_model, get_embedding_provider\\n\\n    record = await knowledge_base_service.get_by_user_and_name(user_id, kb_name)\\n    if record is not None:\\n        model = get_embedding_model(record.model_selection)\\n        if model:\\n            return get_embedding_provider(record.model_selection), model\\n\\n    return _DEFAULT_EMBEDDING_PROVIDER, _DEFAULT_EMBEDDING_MODEL\\n\\n\\nclass KBStorageHelper:\\n    \\\"\\\"\\\"Helper class for Knowledge Base storage and path management.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def get_root_path() -> Path:\\n        \\\"\\\"\\\"Lazy load and return the knowledge bases root directory.\\n\\n        Not cached: reading from the settings service is cheap, and a\\n        process-wide ``@lru_cache`` would lock in a mis-configured\\n        value until restart even when the operator fixes it. Making\\n        the read live also keeps the behaviour consistent with other\\n        settings-dependent helpers in the codebase.\\n        \\\"\\\"\\\"\\n        settings = get_settings_service().settings\\n        knowledge_directory = settings.knowledge_bases_dir\\n        if not knowledge_directory:\\n            msg = \\\"Knowledge bases directory is not set in the settings.\\\"\\n            raise ValueError(msg)\\n        return Path(knowledge_directory).expanduser()\\n\\n    @staticmethod\\n    def get_directory_size(path: Path) -> int:\\n        \\\"\\\"\\\"Calculate the total size of all files in a directory.\\\"\\\"\\\"\\n        total_size = 0\\n        try:\\n            for file_path in path.rglob(\\\"*\\\"):\\n                if file_path.is_file():\\n                    total_size += file_path.stat().st_size\\n        except (OSError, PermissionError):\\n            pass\\n        return total_size\\n\\n    @staticmethod\\n    def get_fresh_chroma_client(kb_path: Path) -> chromadb.PersistentClient:\\n        \\\"\\\"\\\"Get a fresh Chroma client with a unique session ID to avoid 'readonly' errors.\\\"\\\"\\\"\\n        path_key = str(kb_path)\\n        try:\\n            if path_key in SharedSystemClient._identifier_to_system:  # noqa: SLF001\\n                del SharedSystemClient._identifier_to_system[path_key]  # noqa: SLF001\\n        except KeyError as e:\\n            logger.debug(f\\\"Failed to clear existing Chroma registry entry for {path_key}: {e}\\\")\\n\\n        return chromadb.PersistentClient(\\n            path=path_key,\\n            settings=Settings(\\n                is_persistent=True,\\n                persist_directory=path_key,\\n                chroma_otel_service_name=str(uuid.uuid4()),\\n            ),\\n        )\\n\\n    @staticmethod\\n    def release_chroma_resources(kb_path: Path) -> None:\\n        \\\"\\\"\\\"Release ChromaDB resources by clearing the registry entry and forcing GC.\\\"\\\"\\\"\\n        path_key = str(kb_path)\\n        try:\\n            if path_key in SharedSystemClient._identifier_to_system:  # noqa: SLF001\\n                del SharedSystemClient._identifier_to_system[path_key]  # noqa: SLF001\\n        except KeyError:\\n            pass\\n        gc.collect()\\n\\n    @staticmethod\\n    def delete_storage(kb_path: Path, kb_name: str) -> bool:\\n        \\\"\\\"\\\"Teardown ChromaDB connections and delete KB directory with retry logic.\\n\\n        Handles ChromaDB SQLite file locks that can prevent deletion, particularly\\n        on Windows where mandatory file locks block deletion of open files.\\n        Uses retry with exponential backoff and a sentinel-file fallback when\\n        physical removal is impossible.\\n\\n        The sentinel-file fallback (``.kb_deleted``) is preferred over the\\n        previous rename-based fallback because Windows can refuse to rename a\\n        directory whose contents are still locked open, in which case the\\n        directory remained at its original name and the disk-scan listing\\n        path re-discovered it as a valid KB.  Writing a marker file inside\\n        the dir works in cases where rename does not, and the listing layer\\n        treats it identically to a missing dir.\\n\\n        Returns:\\n            True if the KB is no longer visible to listing code (either\\n            because the dir was removed, or because a sentinel was written\\n            after a failed rmtree).  False only when both physical removal\\n            and the sentinel write fail.\\n        \\\"\\\"\\\"\\n        if not kb_path.exists():\\n            return True\\n\\n        # Teardown ChromaDB collection to release handles\\n        try:\\n            has_data = any((kb_path / m).exists() for m in [\\\"chroma\\\", \\\"chroma.sqlite3\\\", \\\"index\\\"])\\n            if has_data:\\n                client = KBStorageHelper.get_fresh_chroma_client(kb_path)\\n                chroma = Chroma(client=client, collection_name=kb_name, **chroma_langchain_collection_kwargs())\\n                with contextlib.suppress(Exception):\\n                    chroma.delete_collection()\\n                chroma = None\\n                client = None\\n        except (OSError, ValueError, TypeError, chromadb.errors.ChromaError) as e:\\n            logger.debug(\\\"Collection teardown failed for %s: %s\\\", kb_path.name, e)\\n\\n        gc.collect()\\n\\n        for attempt in range(MAX_DELETE_RETRIES):\\n            try:\\n                if attempt > 0:\\n                    time.sleep(DELETE_BACKOFF_SECONDS * (2**attempt))\\n\\n                _remove_sqlite_lock_files(kb_path)\\n                _truncate_sqlite_files(kb_path)\\n                gc.collect()\\n\\n                shutil.rmtree(kb_path, ignore_errors=False)\\n\\n                if not kb_path.exists():\\n                    logger.info(\\\"Deleted knowledge base %s on attempt %d\\\", kb_name, attempt + 1)\\n                    return True\\n\\n            except OSError as e:\\n                if attempt < MAX_DELETE_RETRIES - 1:\\n                    logger.debug(\\\"KB deletion attempt %d failed for %s: %s\\\", attempt + 1, kb_name, e)\\n                else:\\n                    logger.warning(\\n                        \\\"KB deletion failed for %s after %d attempts: %s\\\",\\n                        kb_name,\\n                        MAX_DELETE_RETRIES,\\n                        e,\\n                    )\\n\\n        # Fallback: drop a sentinel inside the dir so the listing code paths\\n        # treat it as deleted even though the bytes are still on disk.  Done\\n        # AFTER the final rmtree attempt so anything that did get cleaned out\\n        # of the dir does not also remove the sentinel we just wrote.\\n        if kb_path.exists() and kb_path.is_dir():\\n            try:\\n                (kb_path / KB_DELETED_SENTINEL).touch(exist_ok=True)\\n            except OSError as e:\\n                logger.warning(\\\"Could not write %s sentinel for %s: %s\\\", KB_DELETED_SENTINEL, kb_name, e)\\n                return False\\n            logger.info(\\\"Wrote %s sentinel for %s; dir remains on disk pending restart\\\", KB_DELETED_SENTINEL, kb_name)\\n            return True\\n\\n        return False\\n\\n    @staticmethod\\n    def is_kb_dir_deleted(kb_path: Path) -> bool:\\n        \\\"\\\"\\\"Return True if the KB directory carries the deletion sentinel.\\n\\n        Used by listing endpoints and the disk-scan fallback in\\n        :func:`get_knowledge_bases` so a KB whose row was deleted but whose\\n        bytes could not be removed (locked-file case) does not reappear in\\n        the UI.\\n        \\\"\\\"\\\"\\n        try:\\n            return kb_path.is_dir() and (kb_path / KB_DELETED_SENTINEL).is_file()\\n        except OSError:\\n            # Permission errors / disappearing dir under our feet -> treat as\\n            # not-deleted; the caller will fall through to its own checks.\\n            return False\\n\\n    @staticmethod\\n    def clear_deletion_sentinel(kb_path: Path) -> None:\\n        \\\"\\\"\\\"Remove a leftover ``.kb_deleted`` marker before reusing the path.\\n\\n        Called from the create / first-ingest paths so a recreate-with-the-\\n        same-name immediately after a failed delete does not silently vanish\\n        from listings.  Safe to call when the marker is absent.\\n        \\\"\\\"\\\"\\n        marker = kb_path / KB_DELETED_SENTINEL\\n        try:\\n            marker.unlink(missing_ok=True)\\n        except OSError as e:\\n            logger.debug(\\\"Could not clear %s sentinel under %s: %s\\\", KB_DELETED_SENTINEL, kb_path, e)\\n\\n\\ndef _remove_sqlite_lock_files(kb_path: Path) -> None:\\n    \\\"\\\"\\\"Remove SQLite auxiliary files (WAL, SHM, journal) that hold locks.\\\"\\\"\\\"\\n    for pattern in [\\\"*.sqlite3-wal\\\", \\\"*.sqlite3-shm\\\", \\\"*.sqlite3-journal\\\"]:\\n        for lock_file in kb_path.glob(pattern):\\n            try:\\n                lock_file.unlink()\\n            except OSError as e:\\n                logger.debug(\\\"Could not remove lock file %s: %s\\\", lock_file.name, e)\\n\\n\\ndef _truncate_sqlite_files(kb_path: Path) -> None:\\n    \\\"\\\"\\\"Truncate SQLite database files to release locks.\\\"\\\"\\\"\\n    for sqlite_file in kb_path.glob(\\\"*.sqlite3\\\"):\\n        try:\\n            with sqlite_file.open(\\\"r+b\\\") as f:\\n                f.truncate(0)\\n        except OSError as e:\\n            logger.debug(\\\"Could not truncate %s: %s\\\", sqlite_file.name, e)\\n\\n\\nclass KBAnalysisHelper:\\n    \\\"\\\"\\\"Helper class for Knowledge Base metadata, metrics, and configuration detection.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    async def update_text_metrics_via_backend(metadata: dict, backend) -> None:\\n        \\\"\\\"\\\"Backend-agnostic metrics refresh.\\n\\n        Drives ``chunks`` / ``words`` / ``characters`` / ``avg_chunk_size``\\n        from the backend's ``count`` + ``iter_documents`` abstraction so\\n        every vector-store target (Chroma / Mongo / Astra / Postgres) is\\n        covered. Silently tolerates iterator failures \u2014 metrics are\\n        cosmetic, and raising here would wrongly fail an ingestion whose\\n        writes already succeeded.\\n        \\\"\\\"\\\"\\n        try:\\n            total_chunks = await backend.count()\\n        except Exception as exc:  # noqa: BLE001 \u2014 backend-level issues are best-effort\\n            logger.debug(f\\\"Backend count() failed during metrics refresh: {exc}\\\")\\n            total_chunks = 0\\n        metadata[\\\"chunks\\\"] = total_chunks\\n\\n        if total_chunks <= 0:\\n            return\\n\\n        total_words = 0\\n        total_characters = 0\\n        try:\\n            async for batch in backend.iter_documents(batch_size=5000):\\n                if not batch:\\n                    continue\\n                source_chunks = pd.DataFrame({\\\"document\\\": [doc.content for doc in batch]})\\n                words, characters = KBAnalysisHelper._calculate_text_metrics(source_chunks, [\\\"document\\\"])\\n                total_words += words\\n                total_characters += characters\\n        except Exception as exc:  # noqa: BLE001 \u2014 see note above\\n            logger.debug(f\\\"Backend iter_documents failed during metrics refresh: {exc}\\\")\\n            return\\n\\n        metadata[\\\"words\\\"] = total_words\\n        metadata[\\\"characters\\\"] = total_characters\\n        metadata[\\\"avg_chunk_size\\\"] = round(total_characters / total_chunks, 1) if total_chunks > 0 else 0.0\\n\\n    @staticmethod\\n    def update_text_metrics(kb_path: Path, metadata: dict, chroma: Chroma | None = None) -> None:\\n        \\\"\\\"\\\"Update text metrics (chunks, words, characters) for a knowledge base.\\\"\\\"\\\"\\n        created_locally = chroma is None\\n        client = None\\n        try:\\n            if created_locally:\\n                client = KBStorageHelper.get_fresh_chroma_client(kb_path)\\n                chroma = Chroma(client=client, collection_name=kb_path.name, **chroma_langchain_collection_kwargs())\\n\\n            if chroma is None:\\n                return\\n            collection = chroma._collection  # noqa: SLF001\\n            metadata[\\\"chunks\\\"] = collection.count()\\n\\n            if metadata[\\\"chunks\\\"] > 0:\\n                total_words = 0\\n                total_characters = 0\\n                # Use a robust batch size to avoid SQLite limits and memory pressure\\n                batch_size = 5000\\n\\n                for offset in range(0, metadata[\\\"chunks\\\"], batch_size):\\n                    results = collection.get(\\n                        include=[\\\"documents\\\"],\\n                        limit=batch_size,\\n                        offset=offset,\\n                    )\\n                    if not results[\\\"documents\\\"]:\\n                        break\\n\\n                    # Chroma collections always return the text content within the 'documents' field\\n                    source_chunks = pd.DataFrame({\\\"document\\\": results[\\\"documents\\\"]})\\n                    words, characters = KBAnalysisHelper._calculate_text_metrics(source_chunks, [\\\"document\\\"])\\n                    total_words += words\\n                    total_characters += characters\\n\\n                metadata[\\\"words\\\"] = total_words\\n                metadata[\\\"characters\\\"] = total_characters\\n                metadata[\\\"avg_chunk_size\\\"] = (\\n                    round(total_characters / metadata[\\\"chunks\\\"], 1) if metadata[\\\"chunks\\\"] > 0 else 0.0\\n                )\\n        except (OSError, ValueError, TypeError, json.JSONDecodeError, chromadb.errors.ChromaError) as e:\\n            logger.debug(f\\\"Metrics update failed for {kb_path.name}: {e}\\\")\\n        finally:\\n            if created_locally:\\n                client = None\\n                chroma = None\\n                KBStorageHelper.release_chroma_resources(kb_path)\\n\\n    @staticmethod\\n    def _calculate_text_metrics(df: pd.DataFrame, text_columns: list[str]) -> tuple[int, int]:\\n        \\\"\\\"\\\"Internal helper to calculate total words and characters.\\\"\\\"\\\"\\n        total_words = 0\\n        total_characters = 0\\n\\n        for col in text_columns:\\n            if col not in df.columns:\\n                continue\\n\\n            text_series = df[col].astype(str).fillna(\\\"\\\")\\n            total_characters += int(text_series.str.len().sum())\\n            total_words += int(text_series.str.split().str.len().sum())\\n\\n        return total_words, total_characters\\n\\n\\nclass KBIngestionHelper:\\n    \\\"\\\"\\\"Helper class for Knowledge Base ingestion processes.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    async def perform_ingestion(\\n        kb_name: str,\\n        kb_path: Path | None,\\n        files_data: list[tuple[str, bytes]] | None,\\n        chunk_size: int,\\n        chunk_overlap: int,\\n        separator: str,\\n        source_name: str,\\n        current_user: CurrentActiveUser,\\n        model_selection: dict | list[dict],\\n        task_job_id: uuid.UUID,\\n        job_service: JobService,\\n        source_type: str = DEFAULT_INGESTION_SOURCE_TYPE,\\n        source_metadata: dict | None = None,\\n        source: KBIngestionSource | None = None,\\n        per_file_metadata: dict[str, dict] | None = None,\\n    ) -> dict[str, object]:\\n        \\\"\\\"\\\"Orchestrate the ingestion of content into a knowledge base.\\n\\n        Accepts either a preloaded ``files_data`` list (the long-standing\\n        file-upload path) or a ``source`` \u2014 any ``KBIngestionSource``\\n        implementation. When both are provided, ``source`` wins; when\\n        neither is, raises ``ValueError``.\\n\\n        ``model_selection`` is the canonical embedding-config payload\\n        (matching ``KnowledgeBaseRecord.model_selection``); provider /\\n        model name are derived via the ``get_embedding_provider`` /\\n        ``get_embedding_model`` helpers when this function needs them\\n        for ``build_embeddings``.\\n\\n        Every chunk carries ``source_type`` + ``source_metadata`` so\\n        Phase 2 visibility tooling can group, filter, and drill into\\n        chunks by origin.\\n\\n        Persistence side-effects: on entry, inserts a PENDING row in\\n        ``ingestion_run`` and transitions it to RUNNING; on exit,\\n        finalizes the row with succeeded / failed / skipped counters,\\n        per-item details, and one of SUCCEEDED / PARTIAL / FAILED /\\n        CANCELLED.\\n        \\\"\\\"\\\"\\n        # Lazy import: the service reaches into langflow DB plumbing we\\n        # can't expose at module scope without widening lfx's surface.\\n        from langflow.api.utils import ingestion_run_service, knowledge_base_service\\n        from langflow.api.utils.knowledge_base_service import (\\n            get_embedding_model,\\n            get_embedding_provider,\\n        )\\n\\n        embedding_provider = get_embedding_provider(model_selection)\\n        embedding_model = get_embedding_model(model_selection)\\n\\n        if source is None:\\n            if not files_data:\\n                msg = \\\"perform_ingestion requires either 'source' or non-empty 'files_data'.\\\"\\n                raise ValueError(msg)\\n            source_config: dict[str, Any] = {\\\"files\\\": files_data, \\\"source_name\\\": source_name}\\n            if per_file_metadata:\\n                source_config[\\\"per_file_metadata\\\"] = per_file_metadata\\n            source = FileUploadSource(\\n                user_id=current_user.id,\\n                source_config=source_config,\\n            )\\n\\n        try:\\n            await source.validate_config()\\n        except ValueError as exc:\\n            await logger.aerror(\\\"Ingestion source validation failed: %s\\\", exc)\\n            raise\\n\\n        summary = IngestionSummary(\\n            kb_name=kb_name,\\n            source_type=source.source_type.value,\\n            user_id=current_user.id,\\n            job_id=task_job_id,\\n            source_config=source.describe().get(\\\"config\\\") or {},\\n            user_metadata=dict(source_metadata or {}),\\n        )\\n        # Link the run to the ``knowledge_base`` row when one exists.\\n        # During the Phase 1.5 rollout some KBs still only exist in\\n        # JSON files; in that case ``kb_id`` stays None and the run\\n        # row keeps pointing at ``kb_name`` for N-1 compatibility.\\n        kb_record = await knowledge_base_service.get_by_user_and_name(current_user.id, kb_name)\\n        kb_record_id = kb_record.id if kb_record is not None else None\\n        run_id = await ingestion_run_service.create_run(\\n            kb_name=kb_name,\\n            user_metadata=dict(source_metadata or {}),\\n            source=source,\\n            job_id=task_job_id,\\n            user_id=current_user.id,\\n            kb_id=kb_record_id,\\n        )\\n        await ingestion_run_service.mark_running(run_id)\\n        # Reflect the in-flight ingestion on the KB row so the UI can\\n        # surface accurate status + failure_reason without re-deriving\\n        # them from job state alone.\\n        if kb_record_id is not None:\\n            try:\\n                await knowledge_base_service.update_status(\\n                    kb_record_id,\\n                    status=KnowledgeBaseStatus.INGESTING,\\n                    failure_reason=None,\\n                )\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.awarning(\\\"KB status update to INGESTING lagged for %s: %s\\\", kb_name, exc)\\n\\n        # ``create_backend`` can return any ``BaseVectorStoreBackend``\\n        # subclass. Typing the local as the narrower ``ChromaBackend``\\n        # would hide type errors when this code path routes to\\n        # MongoDB/Astra/Postgres.\\n        backend: BaseVectorStoreBackend | None = None\\n        final_status = IngestionRunStatus.SUCCEEDED\\n        final_error: str | None = None\\n        encoded_metadata_tag = json.dumps(source_metadata) if source_metadata else \\\"\\\"\\n        source_extension_tags: set[str] = set()\\n        try:\\n            embeddings = await KBIngestionHelper.build_embeddings(embedding_provider, embedding_model, current_user)\\n            backend_type_value = (\\n                kb_record.backend_type if kb_record and kb_record.backend_type else BackendType.CHROMA.value\\n            )\\n            backend_config = (kb_record.backend_config or {}) if kb_record is not None else {}\\n            backend = create_backend(\\n                backend_type_value,\\n                kb_name=kb_name,\\n                kb_path=kb_path,\\n                backend_config=backend_config,\\n                embedding_function=embeddings,\\n                # Forward the user id so Mongo/Astra/Postgres backends can\\n                # pull their connection URI / tokens from Langflow's\\n                # variable_service instead of forcing the server to export\\n                # matching env vars.\\n                user_id=getattr(current_user, \\\"id\\\", None),\\n            )\\n\\n            job_id_str = str(task_job_id)\\n\\n            async for item in source.list_items():\\n                if await KBIngestionHelper.is_job_cancelled(job_service, task_job_id):\\n                    raise IngestionCancelledError\\n\\n                await logger.ainfo(\\\"Starting ingestion of %s for %s\\\", item.display_name, kb_name)\\n\\n                try:\\n                    content_obj = await source.fetch_content(item)\\n                except (OSError, ValueError) as fetch_exc:\\n                    summary.record_item(\\n                        IngestionItemResult(\\n                            item_id=item.item_id,\\n                            display_name=item.display_name,\\n                            status=IngestionItemStatus.FAILED,\\n                            error_message=f\\\"fetch failed: {fetch_exc}\\\",\\n                        ),\\n                        size_bytes=item.size_bytes or 0,\\n                    )\\n                    await logger.awarning(\\\"Failed to fetch %s: %s\\\", item.display_name, fetch_exc)\\n                    continue\\n\\n                size_bytes = len(content_obj.raw_bytes)\\n                text = extract_text_from_bytes(content_obj.file_name, content_obj.raw_bytes)\\n                if not text.strip():\\n                    summary.record_item(\\n                        IngestionItemResult(\\n                            item_id=item.item_id,\\n                            display_name=item.display_name,\\n                            status=IngestionItemStatus.SKIPPED,\\n                            error_message=\\\"no extractable text\\\",\\n                        ),\\n                        size_bytes=size_bytes,\\n                    )\\n                    continue\\n\\n                # Collapse run-level + per-item metadata into one blob so\\n                # Phase 2 can render either view. Per-item wins on key\\n                # collision: callers that set both run-level and per-file\\n                # tags expect the file-specific value to override the\\n                # batch default (e.g. ``confidential=true`` on one file\\n                # in an otherwise public batch).\\n                combined_metadata: dict = dict(source_metadata or {})\\n                if item.source_metadata:\\n                    combined_metadata.update(item.source_metadata)\\n                item_metadata_tag = json.dumps(combined_metadata) if combined_metadata else encoded_metadata_tag\\n\\n                chunks = chunk_text_for_ingestion(\\n                    text,\\n                    chunk_size=chunk_size,\\n                    chunk_overlap=chunk_overlap,\\n                    separator=separator,\\n                )\\n                docs = [\\n                    Document(\\n                        page_content=c,\\n                        metadata={\\n                            METADATA_KEY_SOURCE: source_name or content_obj.file_name,\\n                            METADATA_KEY_FILE_NAME: content_obj.file_name,\\n                            METADATA_KEY_CHUNK_INDEX: i,\\n                            METADATA_KEY_TOTAL_CHUNKS: len(chunks),\\n                            METADATA_KEY_INGESTED_AT: datetime.now(timezone.utc).isoformat(),\\n                            METADATA_KEY_JOB_ID: job_id_str,\\n                            METADATA_KEY_SOURCE_TYPE: source.source_type.value or source_type,\\n                            METADATA_KEY_SOURCE_METADATA: item_metadata_tag,\\n                        },\\n                    )\\n                    for i, c in enumerate(chunks)\\n                ]\\n\\n                # Writes that exhaust the retry budget still propagate to\\n                # the outer handler so the whole run can roll back\\n                # uncommitted chunks. Only per-item fetch/extraction\\n                # failures are caught and continue (above).\\n                item_chunks_written = await KBIngestionHelper.write_documents_to_backend(\\n                    documents=docs,\\n                    backend=backend,\\n                    task_job_id=task_job_id,\\n                    job_service=job_service,\\n                )\\n                if item_chunks_written < len(docs):\\n                    # Job was cancelled mid-item \u2014 bail out and let the\\n                    # outer handler roll the run back.\\n                    raise IngestionCancelledError\\n\\n                summary.record_item(\\n                    IngestionItemResult(\\n                        item_id=item.item_id,\\n                        display_name=item.display_name,\\n                        status=IngestionItemStatus.SUCCEEDED,\\n                        chunks_created=item_chunks_written,\\n                    ),\\n                    size_bytes=size_bytes,\\n                )\\n                # Track extension for the KB row's ``source_types`` list,\\n                # which drives the file-type icon in the KB list.\\n                if \\\".\\\" in content_obj.file_name:\\n                    source_extension_tags.add(content_obj.file_name.rsplit(\\\".\\\", 1)[-1].lower())\\n\\n            # Status order matters: a run with zero successes and any\\n            # failure is FAILED; a run with mixed outcomes (some failed\\n            # OR some skipped) is PARTIAL; otherwise SUCCEEDED. Skipped\\n            # items (e.g. empty file, no extractable text) used to fall\\n            # through to SUCCEEDED, which made notifications and the\\n            # runs list misreport an ingestion that produced 0 chunks.\\n            if summary.failed > 0 and summary.succeeded == 0:\\n                final_status = IngestionRunStatus.FAILED\\n            elif summary.failed > 0 or summary.skipped > 0:\\n                final_status = IngestionRunStatus.PARTIAL\\n            else:\\n                final_status = IngestionRunStatus.SUCCEEDED\\n\\n            # Refresh the counters straight onto the ``knowledge_base`` row \u2014\\n            # there is no on-disk sidecar to keep in sync any more. The scratch\\n            # dict is just a carrier for ``update_text_metrics_via_backend``,\\n            # which is backend-agnostic: the older Chroma-only path broke\\n            # Mongo/Astra/Postgres with AttributeError, which then falsely marked\\n            # the run failed and rolled back chunks we had already written.\\n            metrics: dict[str, Any] = {}\\n            await KBAnalysisHelper.update_text_metrics_via_backend(metrics, backend)\\n\\n            # ``size`` is a local-Chroma concept: it measures the persistence\\n            # directory. Remote stores keep nothing on this box, so reporting a\\n            # directory walk there would be meaningless (and would need a path we\\n            # deliberately no longer resolve).\\n            size_bytes = KBStorageHelper.get_directory_size(kb_path) if kb_path is not None else 0\\n\\n            existing_source_types = list(kb_record.source_types or []) if kb_record is not None else []\\n            merged_source_types = sorted(set(existing_source_types) | source_extension_tags)\\n\\n            if kb_record_id is not None:\\n                try:\\n                    await knowledge_base_service.update_stats(\\n                        kb_record_id,\\n                        chunks=metrics.get(\\\"chunks\\\", 0),\\n                        words=metrics.get(\\\"words\\\", 0),\\n                        characters=metrics.get(\\\"characters\\\", 0),\\n                        size_bytes=size_bytes,\\n                        source_types=merged_source_types,\\n                        chunk_size=chunk_size,\\n                        chunk_overlap=chunk_overlap,\\n                        separator=separator or None,\\n                    )\\n                except Exception as exc:  # noqa: BLE001\\n                    await logger.awarning(\\\"KB DB stat update lagged for %s: %s\\\", kb_name, exc)\\n                # Clear any previous failure marker once the run finishes\\n                # writing chunks; ``final_status`` (PARTIAL/SUCCEEDED) is\\n                # not \\\"failed\\\", so the KB row should reflect READY.\\n                try:\\n                    await knowledge_base_service.update_status(\\n                        kb_record_id,\\n                        status=KnowledgeBaseStatus.READY,\\n                        failure_reason=None,\\n                    )\\n                except Exception as exc:  # noqa: BLE001\\n                    await logger.awarning(\\\"KB status update to READY lagged for %s: %s\\\", kb_name, exc)\\n\\n            await logger.ainfo(\\n                \\\"Completed ingestion for %s (succeeded=%d failed=%d skipped=%d)\\\",\\n                kb_name,\\n                summary.succeeded,\\n                summary.failed,\\n                summary.skipped,\\n            )\\n\\n            return {\\n                \\\"message\\\": f\\\"Successfully ingested {summary.succeeded} item(s)\\\",\\n                \\\"files_processed\\\": summary.succeeded,\\n                \\\"chunks_created\\\": summary.chunks_created,\\n                \\\"ingestion_run_id\\\": str(run_id),\\n                \\\"failed\\\": summary.failed,\\n                \\\"skipped\\\": summary.skipped,\\n            }\\n\\n        except IngestionCancelledError:\\n            final_status = IngestionRunStatus.CANCELLED\\n            final_error = \\\"ingestion cancelled by user\\\"\\n            await logger.awarning(\\\"Ingestion job %s was cancelled; rolling back partial data.\\\", task_job_id)\\n            await KBIngestionHelper.cleanup_chroma_chunks_by_job(\\n                task_job_id,\\n                kb_path,\\n                kb_name,\\n                backend_type=kb_record.backend_type if kb_record is not None else None,\\n                backend_config=kb_record.backend_config if kb_record is not None else None,\\n                user_id=getattr(current_user, \\\"id\\\", None),\\n            )\\n            if kb_record_id is not None:\\n                try:\\n                    await knowledge_base_service.update_status(\\n                        kb_record_id,\\n                        status=KnowledgeBaseStatus.FAILED,\\n                        failure_reason=final_error,\\n                    )\\n                except Exception as status_exc:  # noqa: BLE001\\n                    await logger.awarning(\\\"KB status update to FAILED (cancel) lagged for %s: %s\\\", kb_name, status_exc)\\n            return {\\\"message\\\": \\\"Job cancelled\\\", \\\"ingestion_run_id\\\": str(run_id)}\\n        except Exception as exc:\\n            final_status = IngestionRunStatus.FAILED\\n            final_error = str(exc) or exc.__class__.__name__\\n            # ``aexception`` includes the traceback so the underlying\\n            # backend error (e.g. OpenSearch auth / connection failure)\\n            # is preserved in the server logs even when the UI surface\\n            # is limited to a single-line ``failure_reason``.\\n            await logger.aexception(\\\"Error in background ingestion for %s: %s. Initiating rollback.\\\", kb_name, exc)\\n            await KBIngestionHelper.cleanup_chroma_chunks_by_job(\\n                task_job_id,\\n                kb_path,\\n                kb_name,\\n                backend_type=kb_record.backend_type if kb_record is not None else None,\\n                backend_config=kb_record.backend_config if kb_record is not None else None,\\n                user_id=getattr(current_user, \\\"id\\\", None),\\n            )\\n            if kb_record_id is not None:\\n                try:\\n                    await knowledge_base_service.update_status(\\n                        kb_record_id,\\n                        status=KnowledgeBaseStatus.FAILED,\\n                        failure_reason=final_error,\\n                    )\\n                except Exception as status_exc:  # noqa: BLE001\\n                    await logger.awarning(\\\"KB status update to FAILED lagged for %s: %s\\\", kb_name, status_exc)\\n            raise\\n        finally:\\n            if backend is not None:\\n                await backend.teardown()\\n            await ingestion_run_service.finalize_run(\\n                run_id,\\n                summary=summary,\\n                status=final_status,\\n                error_message=final_error,\\n            )\\n\\n    @staticmethod\\n    async def cleanup_chroma_chunks_by_job(\\n        job_id: uuid.UUID,\\n        kb_path: Path | None,\\n        kb_name: str,\\n        backend_type: str | None = None,\\n        backend_config: dict | None = None,\\n        user_id=None,\\n    ) -> None:\\n        \\\"\\\"\\\"Delete every chunk written by ``job_id`` from this KB.\\n\\n        Used by the ingestion rollback path on error or cancellation. The\\n        backend-level filter keyed on ``METADATA_KEY_JOB_ID`` is what makes\\n        rollbacks safe even when multiple concurrent jobs write to the same\\n        collection.\\n\\n        Name kept for backward compatibility \u2014 the cleanup now runs through\\n        whichever backend the KB is configured with, not just Chroma.\\n        Defaults to Chroma so existing callers still work.\\n        \\\"\\\"\\\"\\n        effective_type = backend_type or BackendType.CHROMA.value\\n        backend = create_backend(\\n            effective_type,\\n            kb_name=kb_name,\\n            kb_path=kb_path,\\n            backend_config=backend_config or {},\\n            user_id=user_id,\\n        )\\n        try:\\n            await backend.delete_by({METADATA_KEY_JOB_ID: str(job_id)})\\n            await logger.ainfo(f\\\"Cleaned up chunks for job {job_id} in knowledge base '{kb_name}'\\\")\\n        except (OSError, ValueError, TypeError, chromadb.errors.ChromaError) as cleanup_error:\\n            await logger.aerror(f\\\"Failed to clean up chunks for job {job_id}: {cleanup_error}\\\")\\n        finally:\\n            await backend.teardown()\\n\\n    @staticmethod\\n    async def write_documents_to_backend(\\n        *,\\n        documents: list[Document],\\n        backend: BaseVectorStoreBackend,\\n        task_job_id: uuid.UUID,\\n        job_service: JobService,\\n    ) -> int:\\n        \\\"\\\"\\\"Write pre-built Documents through a ``BaseVectorStoreBackend``.\\n\\n        The single write primitive for every ingestion path \u2014 file-based\\n        Knowledge Bases and message-based Memory Bases alike \u2014 so batching,\\n        cancellation checking, and exponential-backoff retry behave identically\\n        whatever backend the KB is on. A Chroma-only counterpart used to exist\\n        for Memory Bases; it was removed so the local-only path cannot be\\n        reintroduced by accident.\\n\\n        Documents must already be chunked with metadata populated.\\n\\n        Returns:\\n            Number of documents successfully written. Less than\\n            ``len(documents)`` when the job is cancelled mid-write.\\n\\n        Raises:\\n            Exception: Re-raises any non-cancellation write failure\\n                after the retry budget is exhausted.\\n        \\\"\\\"\\\"\\n        written = 0\\n        for i in range(0, len(documents), INGESTION_BATCH_SIZE):\\n            if await KBIngestionHelper.is_job_cancelled(job_service, task_job_id):\\n                return written\\n\\n            batch = documents[i : i + INGESTION_BATCH_SIZE]\\n            for attempt in range(MAX_RETRY_ATTEMPTS):\\n                if await KBIngestionHelper.is_job_cancelled(job_service, task_job_id):\\n                    return written\\n                try:\\n                    await backend.add_documents(batch)\\n                    break\\n                except BackendConfigurationError:\\n                    # Permanent, operator-actionable misconfiguration (missing\\n                    # extension, embedding-dimension mismatch, \u2026). Retrying only\\n                    # burns the backoff budget (~20s) on a call that cannot\\n                    # succeed, so surface it immediately.\\n                    raise\\n                except Exception as exc:\\n                    if attempt == MAX_RETRY_ATTEMPTS - 1:\\n                        raise\\n                    wait = (attempt + 1) * EXPONENTIAL_BACKOFF_MULTIPLIER\\n                    await logger.awarning(\\\"Write failed, retrying in %ds: %s\\\", wait, exc)\\n                    await asyncio.sleep(wait)\\n\\n            written += len(batch)\\n            await asyncio.sleep(0.01)\\n\\n        return written\\n\\n    @staticmethod\\n    async def is_job_cancelled(job_service: JobService, job_id: uuid.UUID) -> bool:\\n        \\\"\\\"\\\"Internal helper to check if a job has been cancelled.\\\"\\\"\\\"\\n        job = await job_service.get_job_by_job_id(job_id)\\n        return job is not None and job.status == JobStatus.CANCELLED\\n\\n    @staticmethod\\n    async def build_embeddings(provider: str, model: str, current_user):\\n        \\\"\\\"\\\"Build a LangChain embeddings instance for a stored KB.\\n\\n        The provider/model pair is the source of truth recorded on the KB's\\n        ``knowledge_base`` row at creation time. We resolve the embedding\\n        class and parameter mapping straight from the static registry rather\\n        than the user-filtered catalog, so retrieval keeps working when:\\n\\n        - the call originates from a context where the credential lookup\\n          inside ``get_embedding_model_options`` silently returns an empty\\n          set of enabled providers (e.g. a thread-bridged async hop), or\\n        - the user has since disabled the model in their settings.\\n\\n        The runtime credential is still resolved by ``get_embeddings`` via\\n        ``get_api_key_for_provider``, so a missing API key still raises a\\n        clear, user-actionable error at instantiation time.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.unified_models.class_registry import (\\n            EMBEDDING_PARAM_MAPPINGS,\\n            EMBEDDING_PROVIDER_CLASS_MAPPING,\\n        )\\n\\n        embedding_class = EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider)\\n        param_mapping = EMBEDDING_PARAM_MAPPINGS.get(provider)\\n        if not embedding_class or not param_mapping:\\n            supported = \\\", \\\".join(sorted(EMBEDDING_PROVIDER_CLASS_MAPPING))\\n            msg = (\\n                f\\\"Embedding model '{model}' for provider '{provider}' could not be \\\"\\n                f\\\"resolved: provider '{provider}' is not registered. Supported \\\"\\n                f\\\"providers: {supported}.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        selected_option = {\\n            \\\"name\\\": model,\\n            \\\"provider\\\": provider,\\n            \\\"category\\\": provider,\\n            \\\"icon\\\": provider,\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": embedding_class,\\n                \\\"param_mapping\\\": param_mapping,\\n                \\\"model_type\\\": \\\"embeddings\\\",\\n            },\\n        }\\n\\n        # Force None so input defaults (localhost Ollama / blank api_base) do not override globals.\\n        embedding_model = EmbeddingModelComponent(\\n            model=[selected_option],\\n            ollama_base_url=None,\\n            api_base=None,\\n            _user_id=current_user.id,\\n        )\\n        return embedding_model.build_embeddings()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/kb_metadata.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e74430f28fae1e18330c4d9940e09833ffa200f83fae41e863924394790713b9\",\"content\":\"\\\"\\\"\\\"User-supplied metadata helpers for Knowledge Base ingestion.\\n\\nTwo helpers:\\n\\n* :func:`parse_user_metadata` decodes a JSON string from a multipart Form\\n  field, runs the rule set in :func:`validate_user_metadata`, and returns a\\n  dict \u2014 or raises :class:`fastapi.HTTPException` with a 422 status so the\\n  rejection surfaces as an inline form-validation error in the UI.\\n* :func:`parse_per_file_metadata` does the same for the\\n  ``per_file_metadata`` field, which carries a ``{filename: {...}}`` map of\\n  per-file overrides. Each inner dict goes through the same validator.\\n\\nMirrors the bounds in :mod:`langflow.utils.kb_constants` and is the only\\nmetadata gate at the API boundary \u2014 :class:`KBIngestionHelper.perform_ingestion`\\ntrusts that whatever it receives has already been validated.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import Any\\n\\nfrom fastapi import HTTPException\\n\\nfrom langflow.utils.kb_constants import (\\n    KB_METADATA_MAX_ARRAY_LENGTH,\\n    KB_METADATA_MAX_KEY_LENGTH,\\n    KB_METADATA_MAX_KEYS,\\n    KB_METADATA_MAX_VALUE_LENGTH,\\n    KB_METADATA_RESERVED_KEYS,\\n)\\n\\n_KEY_ALLOWED_CHARS = set(\\\"abcdefghijklmnopqrstuvwxyz0123456789_\\\")\\n\\n\\ndef _is_valid_key(key: str) -> bool:\\n    if not key or len(key) > KB_METADATA_MAX_KEY_LENGTH:\\n        return False\\n    return all(c in _KEY_ALLOWED_CHARS for c in key)\\n\\n\\ndef _validate_value(key: str, value: Any) -> None:\\n    if isinstance(value, (bool, int, float)):\\n        return\\n    if isinstance(value, str):\\n        if len(value) > KB_METADATA_MAX_VALUE_LENGTH:\\n            msg = f\\\"Metadata value for '{key}' exceeds {KB_METADATA_MAX_VALUE_LENGTH} characters.\\\"\\n            raise HTTPException(status_code=422, detail=msg)\\n        return\\n    if isinstance(value, list):\\n        if len(value) > KB_METADATA_MAX_ARRAY_LENGTH:\\n            msg = f\\\"Metadata array '{key}' exceeds {KB_METADATA_MAX_ARRAY_LENGTH} items.\\\"\\n            raise HTTPException(status_code=422, detail=msg)\\n        for entry in value:\\n            if not isinstance(entry, str):\\n                msg = f\\\"Metadata array '{key}' must contain only strings.\\\"\\n                raise HTTPException(status_code=422, detail=msg)\\n            if len(entry) > KB_METADATA_MAX_VALUE_LENGTH:\\n                msg = f\\\"Metadata array entry under '{key}' exceeds {KB_METADATA_MAX_VALUE_LENGTH} characters.\\\"\\n                raise HTTPException(status_code=422, detail=msg)\\n        return\\n    msg = f\\\"Metadata value for '{key}' must be a string, number, bool, or string array; got {type(value).__name__}.\\\"\\n    raise HTTPException(status_code=422, detail=msg)\\n\\n\\ndef validate_user_metadata(metadata: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Enforce the user-metadata contract on a decoded dict.\\n\\n    Returns the same dict (a shallow copy is *not* made \u2014 callers may mutate\\n    safely once validation passes). Raises :class:`HTTPException` with a 422\\n    status on any violation so FastAPI surfaces an inline error.\\n    \\\"\\\"\\\"\\n    if not isinstance(metadata, dict):\\n        msg = \\\"Metadata must be a JSON object.\\\"\\n        raise HTTPException(status_code=422, detail=msg)\\n    if len(metadata) > KB_METADATA_MAX_KEYS:\\n        msg = f\\\"Metadata exceeds the {KB_METADATA_MAX_KEYS} key limit.\\\"\\n        raise HTTPException(status_code=422, detail=msg)\\n    for key, value in metadata.items():\\n        if not isinstance(key, str) or not _is_valid_key(key):\\n            msg = (\\n                f\\\"Metadata key {key!r} is invalid: must be 1-{KB_METADATA_MAX_KEY_LENGTH} \\\"\\n                \\\"lowercase alphanumeric or underscore characters.\\\"\\n            )\\n            raise HTTPException(status_code=422, detail=msg)\\n        if key in KB_METADATA_RESERVED_KEYS:\\n            msg = f\\\"Metadata key '{key}' is reserved for ingestion-internal use.\\\"\\n            raise HTTPException(status_code=422, detail=msg)\\n        _validate_value(key, value)\\n    return metadata\\n\\n\\ndef parse_user_metadata(raw: str | None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Decode + validate the ``metadata`` form field. Empty/None \u2192 ``{}``.\\\"\\\"\\\"\\n    if not raw:\\n        return {}\\n    try:\\n        decoded = json.loads(raw)\\n    except json.JSONDecodeError as exc:\\n        msg = f\\\"Metadata is not valid JSON: {exc.msg}\\\"\\n        raise HTTPException(status_code=422, detail=msg) from exc\\n    return validate_user_metadata(decoded)\\n\\n\\ndef parse_per_file_metadata(raw: str | None) -> dict[str, dict[str, Any]]:\\n    \\\"\\\"\\\"Decode + validate the ``per_file_metadata`` form field.\\n\\n    Shape: ``{filename: {metadata_dict}, ...}``. Each inner dict goes through\\n    the same validator as run-level metadata, so per-file overrides obey the\\n    same key/value rules. Empty/None \u2192 ``{}``.\\n    \\\"\\\"\\\"\\n    if not raw:\\n        return {}\\n    try:\\n        decoded = json.loads(raw)\\n    except json.JSONDecodeError as exc:\\n        msg = f\\\"Per-file metadata is not valid JSON: {exc.msg}\\\"\\n        raise HTTPException(status_code=422, detail=msg) from exc\\n    if not isinstance(decoded, dict):\\n        msg = \\\"Per-file metadata must be a JSON object keyed by filename.\\\"\\n        raise HTTPException(status_code=422, detail=msg)\\n    if len(decoded) > KB_METADATA_MAX_KEYS:\\n        msg = f\\\"Per-file metadata exceeds the {KB_METADATA_MAX_KEYS} file limit.\\\"\\n        raise HTTPException(status_code=422, detail=msg)\\n    out: dict[str, dict[str, Any]] = {}\\n    for filename, file_metadata in decoded.items():\\n        if not isinstance(filename, str) or not filename:\\n            msg = \\\"Per-file metadata keys must be non-empty filename strings.\\\"\\n            raise HTTPException(status_code=422, detail=msg)\\n        if not isinstance(file_metadata, dict):\\n            msg = f\\\"Per-file metadata for {filename!r} must be a JSON object.\\\"\\n            raise HTTPException(status_code=422, detail=msg)\\n        out[filename] = validate_user_metadata(file_metadata)\\n    return out\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/knowledge_base_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b55b97e14d687d014227c8001517ad170253a6decc076de0653a1ce87a7609a\",\"content\":\"\\\"\\\"\\\"CRUD + backfill helpers for ``knowledge_base`` rows.\\n\\nTwo responsibilities:\\n\\n1. **Dual-write** helpers the existing KB code paths can adopt without\\n   a big-bang refactor \u2014 every ``create_record`` / ``update_stats``\\n   call is paired with continued JSON-file writes in ``kb_helpers`` so\\n   older service versions still see an intact filesystem view.\\n\\n2. **DB-first read** helper that consolidates metadata from either the\\n   row or the on-disk JSON, whichever is populated. New KBs live only\\n   in the DB after Phase 1.5; older KBs continue to work because the\\n   startup reconciliation upserts rows for any directory that lacks one.\\n\\nKept small and procedural on purpose \u2014 no repository class because\\nthe CRUD surface is tiny (create, upsert, update counters, update\\nstatus, delete, get_by_*_, list_by_user, backfill_from_disk) and\\nPhase 2's new endpoints will add their own query methods alongside.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization.base import ResourceVisibilityScope\\nfrom sqlmodel import select\\n\\nfrom langflow.services.database.models.knowledge_base import KnowledgeBaseRecord, KnowledgeBaseStatus\\nfrom langflow.services.deps import session_scope\\nfrom langflow.services.memory_base.embedding_helpers import infer_embedding_provider\\n\\n\\nclass _UnsetType:\\n    \\\"\\\"\\\"Sentinel for optional fields where ``None`` is a valid value.\\\"\\\"\\\"\\n\\n\\n_UNSET = _UnsetType()\\n\\n\\ndef get_embedding_provider(model_selection: Any) -> str:\\n    \\\"\\\"\\\"Extract the provider name from a ``model_selection`` payload.\\n\\n    ``model_selection`` is the canonical source of truth for embedding\\n    config on a KB; this helper centralizes the \\\"what provider is this\\n    KB on\\\" lookup so the answer doesn't drift between callers.\\n\\n    Accepts the persisted dict shape (``{\\\"name\\\": ..., \\\"provider\\\": ...}``),\\n    the list-wrapped shape used by some unified-models entry points, or\\n    ``None``. Returns ``\\\"Unknown\\\"`` when nothing usable is present so\\n    list-style API responses can render a stable column.\\n    \\\"\\\"\\\"\\n    selection = _coerce_model_dict(model_selection)\\n    if not selection:\\n        return \\\"Unknown\\\"\\n    provider = selection.get(\\\"provider\\\")\\n    return str(provider).strip() if provider else \\\"Unknown\\\"\\n\\n\\ndef get_embedding_model(model_selection: Any) -> str:\\n    \\\"\\\"\\\"Extract the model name from a ``model_selection`` payload.\\n\\n    Counterpart to :func:`get_embedding_provider`. Returns ``\\\"\\\"`` (rather\\n    than ``\\\"Unknown\\\"``) on missing input \u2014 call sites distinguish\\n    \\\"model unknown\\\" (display-only) from \\\"model missing\\\" (don't try to\\n    instantiate embeddings).\\n    \\\"\\\"\\\"\\n    selection = _coerce_model_dict(model_selection)\\n    if not selection:\\n        return \\\"\\\"\\n    name = selection.get(\\\"name\\\")\\n    return str(name).strip() if name else \\\"\\\"\\n\\n\\ndef _coerce_model_dict(model_selection: Any) -> dict[str, Any] | None:\\n    \\\"\\\"\\\"Coerce ``model_selection`` to the canonical single-dict form.\\\"\\\"\\\"\\n    if model_selection is None:\\n        return None\\n    if isinstance(model_selection, list):\\n        return model_selection[0] if model_selection else None\\n    if isinstance(model_selection, dict):\\n        return model_selection\\n    return None\\n\\n\\nasync def create_record(\\n    *,\\n    user_id: UUID,\\n    name: str,\\n    model_selection: dict[str, Any] | list[dict[str, Any]] | None = None,\\n    chunk_size: int = 1000,\\n    chunk_overlap: int = 200,\\n    separator: str | None = None,\\n    column_config: list[dict[str, Any]] | None = None,\\n    backend_type: str = \\\"chroma\\\",\\n    backend_config: dict[str, Any] | None = None,\\n    chunks: int = 0,\\n    words: int = 0,\\n    characters: int = 0,\\n    size_bytes: int = 0,\\n    source_types: list[str] | None = None,\\n    record_id: UUID | None = None,\\n) -> KnowledgeBaseRecord:\\n    \\\"\\\"\\\"Insert a new KB record. Caller should already hold the name lock.\\n\\n    ``model_selection`` is the single source of truth for embedding\\n    config \u2014 the legacy ``embedding_provider`` / ``embedding_model``\\n    flat columns were dropped in favor of the\\n    :func:`get_embedding_provider` / :func:`get_embedding_model` helpers\\n    that read from ``model_selection``. Callers that previously passed\\n    those two params now just supply ``model_selection``.\\n    \\\"\\\"\\\"\\n    normalized_selection = _normalize_model_selection(model_selection)\\n    record = KnowledgeBaseRecord(\\n        id=record_id or uuid4(),\\n        name=name,\\n        user_id=user_id,\\n        model_selection=normalized_selection,\\n        chunk_size=chunk_size,\\n        chunk_overlap=chunk_overlap,\\n        separator=separator,\\n        column_config=column_config or [],\\n        backend_type=backend_type,\\n        backend_config=backend_config or {},\\n        chunks=chunks,\\n        words=words,\\n        characters=characters,\\n        size_bytes=size_bytes,\\n        source_types=sorted(set(source_types or [])),\\n        status=KnowledgeBaseStatus.READY.value,\\n    )\\n    async with session_scope() as session:\\n        session.add(record)\\n        await session.commit()\\n        await session.refresh(record)\\n    return record\\n\\n\\nasync def get_by_user_and_name(user_id: UUID, name: str) -> KnowledgeBaseRecord | None:\\n    async with session_scope() as session:\\n        stmt = select(KnowledgeBaseRecord).where(\\n            KnowledgeBaseRecord.user_id == user_id,\\n            KnowledgeBaseRecord.name == name,\\n        )\\n        result = await session.exec(stmt)\\n        return result.first()\\n\\n\\nasync def get_by_id(record_id: UUID) -> KnowledgeBaseRecord | None:\\n    async with session_scope() as session:\\n        return await session.get(KnowledgeBaseRecord, record_id)\\n\\n\\nasync def list_by_name(name: str) -> list[KnowledgeBaseRecord]:\\n    \\\"\\\"\\\"Return every KB record with the given ``name`` across all users.\\n\\n    Cross-user share resolution: ``(user_id, name)`` is the unique key per\\n    user, but the name itself can collide across users. Callers that need\\n    to find a non-owned KB referenced by a share grant scan name matches and\\n    let the enforcer pick the one the actor can reach.\\n    \\\"\\\"\\\"\\n    async with session_scope() as session:\\n        stmt = select(KnowledgeBaseRecord).where(KnowledgeBaseRecord.name == name)\\n        result = await session.exec(stmt)\\n        return list(result.all())\\n\\n\\nasync def get_backends_for_names(names: list[str]) -> dict[str, tuple[str, dict]]:\\n    \\\"\\\"\\\"Return ``{name: (backend_type, backend_config)}`` for KB names in one query.\\n\\n    Used to enrich Memory Base list/read responses with the backing KB's\\n    vector-store backend without an N+1 per-item lookup. ``backend_config`` is\\n    included so callers can distinguish Chroma Local from Chroma Cloud (both are\\n    stored as ``backend_type=\\\"chroma\\\"``; the discriminator is\\n    ``backend_config[\\\"mode\\\"] == \\\"cloud\\\"``); it carries only variable *names* and\\n    routing flags, never secrets.\\n\\n    Keyed by name alone: Memory Base ``kb_name``s carry a random suffix so they\\n    are globally unique, which also lets this resolve shared (cross-user) Memory\\n    Bases. Missing names are absent from the map; callers default to\\n    ``(\\\"chroma\\\", {})``.\\n    \\\"\\\"\\\"\\n    if not names:\\n        return {}\\n    async with session_scope() as session:\\n        stmt = select(\\n            KnowledgeBaseRecord.name,\\n            KnowledgeBaseRecord.backend_type,\\n            KnowledgeBaseRecord.backend_config,\\n        ).where(KnowledgeBaseRecord.name.in_(names))  # type: ignore[attr-defined]\\n        result = await session.exec(stmt)\\n        return {\\n            name: (backend_type or \\\"chroma\\\", backend_config or {})\\n            for name, backend_type, backend_config in result.all()\\n        }\\n\\n\\nasync def list_by_user(user_id: UUID) -> list[KnowledgeBaseRecord]:\\n    \\\"\\\"\\\"Return all KBs for ``user_id`` (newest first).\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        stmt = (\\n            select(KnowledgeBaseRecord)\\n            .where(KnowledgeBaseRecord.user_id == user_id)\\n            .order_by(KnowledgeBaseRecord.created_at.desc())  # type: ignore[attr-defined]\\n        )\\n        result = await session.exec(stmt)\\n        return list(result.all())\\n\\n\\nasync def list_owned_or_visible(\\n    user_id: UUID,\\n    visibility: ResourceVisibilityScope,\\n) -> list[KnowledgeBaseRecord]:\\n    \\\"\\\"\\\"Return KB rows owned by ``user_id`` or visible through a supported scope.\\\"\\\"\\\"\\n    from langflow.services.authorization.listing import restrict_to_owned_or_visible_scope\\n\\n    async with session_scope() as session:\\n        # KnowledgeBaseRecord has no canonical workspace/project columns, so\\n        # domain-only grants intentionally remain owner-scoped.\\n        stmt = restrict_to_owned_or_visible_scope(\\n            select(KnowledgeBaseRecord),\\n            id_column=KnowledgeBaseRecord.id,\\n            owner_clause=KnowledgeBaseRecord.user_id == user_id,\\n            visibility=visibility,\\n        ).order_by(KnowledgeBaseRecord.created_at.desc())  # type: ignore[attr-defined]\\n        result = await session.exec(stmt)\\n        return list(result.all())\\n\\n\\nasync def backfill_all_users_from_disk(\\n    *,\\n    kb_root: Path | None = None,\\n    username: str | None = None,\\n    dry_run: bool = False,\\n) -> int:\\n    \\\"\\\"\\\"Adopt KB directories that have no ``knowledge_base`` row.\\n\\n    Legacy-recovery only. The ``knowledge_base`` row is the sole authority for KB\\n    metadata and nothing in the steady-state code path reads the on-disk\\n    ``embedding_metadata.json`` sidecar any more, so this exists purely to adopt\\n    directories written by a Langflow version that predates that change. It is\\n    opt-in at startup (``LANGFLOW_KB_DISK_RECONCILE_ENABLED``) and available on\\n    demand as ``langflow reconcile-kb-from-disk``.\\n\\n    ``username`` narrows the scan to a single account \u2014 the usual shape of a\\n    real recovery (\\\"this user's KBs vanished after the upgrade\\\"). ``dry_run``\\n    reports what would be adopted without writing.\\n\\n    Returns the number of rows inserted (or that would be inserted, under\\n    ``dry_run``). Never raises for per-user failures.\\n    \\\"\\\"\\\"\\n    from langflow.api.utils.kb_helpers import KBStorageHelper\\n    from langflow.services.database.models.user.model import User\\n\\n    effective_root = kb_root or KBStorageHelper.get_root_path()\\n    if not effective_root.exists():\\n        return 0\\n\\n    async with session_scope() as session:\\n        stmt = select(User)\\n        if username:\\n            stmt = stmt.where(User.username == username)\\n        users = list((await session.exec(stmt)).all())\\n\\n    inserted = 0\\n    for user in users:\\n        kb_user_root = effective_root / user.username\\n        if not kb_user_root.exists():\\n            continue\\n        try:\\n            inserted += await backfill_from_disk(\\n                user_id=user.id,\\n                kb_user_root=kb_user_root,\\n                dry_run=dry_run,\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.awarning(\\n                \\\"knowledge-base disk reconciliation failed for user %s: %s\\\",\\n                user.username,\\n                exc,\\n            )\\n\\n    return inserted\\n\\n\\nasync def backfill_memory_base_rows() -> int:\\n    \\\"\\\"\\\"Ensure every Memory Base has a backing ``knowledge_base`` row.\\n\\n    Memory Bases are DB-driven: their backend + embedding config resolve from the\\n    ``knowledge_base`` row, never an on-disk sidecar. Memory Bases created before\\n    that row existed have only a ``memory_base`` row, so this startup reconcile\\n    creates the missing ``knowledge_base`` row from the ``memory_base`` table\\n    itself \u2014 no disk access, so it works on a replica whose filesystem never held\\n    the KB directory.\\n\\n    Only Memory Bases *lacking* a ``knowledge_base`` row are fetched (a single\\n    ``NOT EXISTS`` query), so after the first run this returns zero rows and does\\n    almost nothing \u2014 startup cost is proportional to the backlog, not the total\\n    Memory Base count. ``backend_type=\\\"chroma\\\"`` with empty config is the correct\\n    reconstruction: a Memory Base with no row predates the backend selector, when\\n    every Memory Base was local Chroma, and the ``memory_base`` table records no\\n    backend to recover. Memory Bases created through the selector get their real\\n    backend from ``_create_kb_record_for_memory_base`` and never reach this path.\\n\\n    Returns the number of rows inserted. Never raises \u2014 per-MB failures are logged\\n    and skipped so one bad row doesn't block startup.\\n    \\\"\\\"\\\"\\n    from sqlalchemy import exists\\n\\n    from langflow.services.database.models.memory_base.model import MemoryBase\\n    from langflow.services.memory_base.embedding_helpers import infer_embedding_provider\\n\\n    # Fetch only Memory Bases with no matching knowledge_base row (by owner + name).\\n    orphan_stmt = (\\n        select(MemoryBase)\\n        .where(MemoryBase.kb_name != \\\"\\\")\\n        .where(\\n            ~exists(\\n                select(KnowledgeBaseRecord.id)\\n                .where(KnowledgeBaseRecord.user_id == MemoryBase.user_id)\\n                .where(KnowledgeBaseRecord.name == MemoryBase.kb_name)\\n            )\\n        )\\n    )\\n    async with session_scope() as session:\\n        orphans = list((await session.exec(orphan_stmt)).all())\\n\\n    inserted = 0\\n    for mb in orphans:\\n        try:\\n            provider = infer_embedding_provider(mb.embedding_model)\\n            await create_record(\\n                user_id=mb.user_id,\\n                name=mb.kb_name,\\n                model_selection={\\\"name\\\": mb.embedding_model, \\\"provider\\\": provider},\\n                backend_type=\\\"chroma\\\",\\n                backend_config={},\\n                source_types=[\\\"memory\\\"],\\n            )\\n            inserted += 1\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.aerror(\\\"memory-base backfill: failed to upsert KB row for %s: %s\\\", mb.kb_name, exc)\\n\\n    return inserted\\n\\n\\nasync def update_stats(\\n    record_id: UUID,\\n    *,\\n    chunks: int | None = None,\\n    words: int | None = None,\\n    characters: int | None = None,\\n    size_bytes: int | None = None,\\n    source_types: list[str] | None = None,\\n    chunk_size: int | None = None,\\n    chunk_overlap: int | None = None,\\n    separator: str | None | _UnsetType = _UNSET,\\n) -> None:\\n    \\\"\\\"\\\"Refresh the cached aggregates + chunker settings after an ingestion run.\\n\\n    Silently returns if the row is missing \u2014 the row may have been\\n    deleted between the ingestion start and the finalize call; we\\n    don't want that to fail the run.\\n    \\\"\\\"\\\"\\n    async with session_scope() as session:\\n        row = await session.get(KnowledgeBaseRecord, record_id)\\n        if row is None:\\n            await logger.awarning(\\\"knowledge_base row %s missing on update_stats; skipping\\\", record_id)\\n            return\\n        if chunks is not None:\\n            row.chunks = chunks\\n        if words is not None:\\n            row.words = words\\n        if characters is not None:\\n            row.characters = characters\\n        if size_bytes is not None:\\n            row.size_bytes = size_bytes\\n        if source_types is not None:\\n            row.source_types = sorted(set(source_types))\\n        if chunk_size is not None:\\n            row.chunk_size = chunk_size\\n        if chunk_overlap is not None:\\n            row.chunk_overlap = chunk_overlap\\n        if not isinstance(separator, _UnsetType):\\n            row.separator = separator\\n        row.updated_at = datetime.now(timezone.utc)\\n        session.add(row)\\n        await session.commit()\\n\\n\\nasync def update_status(\\n    record_id: UUID,\\n    *,\\n    status: KnowledgeBaseStatus,\\n    failure_reason: str | None = None,\\n) -> None:\\n    async with session_scope() as session:\\n        row = await session.get(KnowledgeBaseRecord, record_id)\\n        if row is None:\\n            return\\n        row.status = status.value\\n        row.failure_reason = failure_reason\\n        row.updated_at = datetime.now(timezone.utc)\\n        session.add(row)\\n        await session.commit()\\n\\n\\nasync def update_column_config(\\n    record_id: UUID,\\n    column_config: list[dict[str, Any]],\\n) -> None:\\n    async with session_scope() as session:\\n        row = await session.get(KnowledgeBaseRecord, record_id)\\n        if row is None:\\n            return\\n        row.column_config = column_config\\n        row.updated_at = datetime.now(timezone.utc)\\n        session.add(row)\\n        await session.commit()\\n\\n\\nasync def delete_record(record_id: UUID) -> None:\\n    \\\"\\\"\\\"Remove the KB row. Caller is responsible for filesystem cleanup.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        row = await session.get(KnowledgeBaseRecord, record_id)\\n        if row is None:\\n            return\\n        await session.delete(row)\\n        await session.commit()\\n\\n\\nasync def delete_by_user_and_name(user_id: UUID, name: str) -> None:\\n    record = await get_by_user_and_name(user_id, name)\\n    if record is not None:\\n        await delete_record(record.id)\\n\\n\\nasync def read_metadata(\\n    *,\\n    user_id: UUID,\\n    name: str,\\n    kb_path: Path,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Return KB metadata, preferring the DB row over the JSON file.\\n\\n    Older KBs that pre-date Phase 1.5 (or were created by an older\\n    service version during the rollout) may only exist on disk \u2014\\n    ``load_metadata_from_disk`` is the fallback. When both sources\\n    exist, the DB wins: it's the authoritative copy going forward.\\n    \\\"\\\"\\\"\\n    record = await get_by_user_and_name(user_id, name)\\n    if record is not None:\\n        return record_to_metadata_dict(record)\\n\\n    return load_metadata_from_disk(kb_path)\\n\\n\\ndef record_to_metadata_dict(record: KnowledgeBaseRecord) -> dict[str, Any]:\\n    \\\"\\\"\\\"Serialize a row into the legacy JSON-file shape.\\n\\n    Matches the key set the API routes and the frontend expect, so the\\n    row can back the response shape without a parallel consumer refactor.\\n    \\\"\\\"\\\"\\n    status = record.status\\n    if status == KnowledgeBaseStatus.READY.value and record.chunks <= 0:\\n        status = \\\"empty\\\"\\n\\n    return {\\n        \\\"id\\\": str(record.id),\\n        \\\"name\\\": record.name,\\n        # Flat fields are derived views over ``model_selection`` \u2014 kept\\n        # in the response shape for API back-compat (the frontend reads\\n        # ``embedding_provider`` / ``embedding_model`` as flat keys),\\n        # but the canonical source of truth is ``model_selection``.\\n        \\\"embedding_provider\\\": get_embedding_provider(record.model_selection),\\n        \\\"embedding_model\\\": get_embedding_model(record.model_selection),\\n        \\\"model_selection\\\": record.model_selection or None,\\n        \\\"chunk_size\\\": record.chunk_size,\\n        \\\"chunk_overlap\\\": record.chunk_overlap,\\n        \\\"separator\\\": record.separator,\\n        \\\"column_config\\\": record.column_config,\\n        \\\"backend_type\\\": record.backend_type,\\n        \\\"backend_config\\\": record.backend_config,\\n        \\\"chunks\\\": record.chunks,\\n        \\\"words\\\": record.words,\\n        \\\"characters\\\": record.characters,\\n        \\\"size\\\": record.size_bytes,\\n        \\\"source_types\\\": record.source_types,\\n        \\\"status\\\": status,\\n        \\\"failure_reason\\\": record.failure_reason,\\n        \\\"avg_chunk_size\\\": round(record.characters / record.chunks, 1) if record.chunks > 0 else 0.0,\\n    }\\n\\n\\ndef load_metadata_from_disk(kb_path: Path) -> dict[str, Any]:\\n    \\\"\\\"\\\"Read ``embedding_metadata.json`` from ``kb_path``.\\n\\n    Extracted so the backfill + fallback paths share a single parser.\\n    Returns an empty dict when the file is missing or malformed \u2014\\n    callers treat that as \\\"no DB row yet\\\" and either backfill or emit\\n    a 404.\\n    \\\"\\\"\\\"\\n    metadata_file = kb_path / \\\"embedding_metadata.json\\\"\\n    if not metadata_file.exists():\\n        return {}\\n    try:\\n        return json.loads(metadata_file.read_text())\\n    except (OSError, json.JSONDecodeError) as exc:\\n        logger.debug(\\\"Failed to read KB metadata file %s: %s\\\", metadata_file, exc)\\n        return {}\\n\\n\\nasync def backfill_from_disk(\\n    *,\\n    user_id: UUID,\\n    kb_user_root: Path,\\n    dry_run: bool = False,\\n) -> int:\\n    \\\"\\\"\\\"Create missing ``knowledge_base`` rows for existing KB directories.\\n\\n    Legacy-recovery only \u2014 see :func:`backfill_all_users_from_disk`. This is the\\n    one remaining reader of the on-disk ``embedding_metadata.json`` sidecar, and\\n    it runs only when an operator asks for it.\\n\\n    ``dry_run`` counts what would be adopted without writing any rows.\\n\\n    Returns the number of rows inserted. Never raises \u2014 failures are\\n    logged and skipped so one malformed KB directory doesn't block the\\n    rest.\\n    \\\"\\\"\\\"\\n    if not kb_user_root.exists():\\n        return 0\\n\\n    from langflow.api.utils.kb_helpers import KBStorageHelper\\n\\n    inserted = 0\\n    for kb_dir in kb_user_root.iterdir():\\n        if not kb_dir.is_dir() or kb_dir.name.startswith(\\\".\\\"):\\n            continue\\n\\n        # Skip directories carrying the ``.kb_deleted`` sentinel: their DB\\n        # row was intentionally deleted but the bytes could not be removed\\n        # (typically a Windows Chroma SQLite lock).  Without this check the\\n        # next startup re-inserts the row and the deleted KB reappears.\\n        if KBStorageHelper.is_kb_dir_deleted(kb_dir):\\n            continue\\n\\n        name = kb_dir.name\\n        existing = await get_by_user_and_name(user_id, name)\\n        if existing is not None:\\n            continue\\n\\n        metadata = load_metadata_from_disk(kb_dir)\\n        if not metadata:\\n            # Unreadable metadata: skip. A subsequent ingestion will\\n            # rewrite the file and the next backfill will pick it up.\\n            continue\\n\\n        try:\\n            model_selection = _normalize_model_selection(metadata.get(\\\"model_selection\\\"))\\n            record_id = _coerce_uuid(metadata.get(\\\"id\\\")) or uuid4()\\n            # ``backend_type``/``backend_config`` are persisted by\\n            # ``create_knowledge_base`` into ``embedding_metadata.json``\\n            # precisely so a later backfill can reconstruct the correct\\n            # routing. Fall back to \\\"chroma\\\" only when the file\\n            # predates the multi-backend change (legacy KBs).\\n            backend_type = str(metadata.get(\\\"backend_type\\\") or \\\"chroma\\\")\\n            backend_config_raw = metadata.get(\\\"backend_config\\\") or {}\\n            backend_config = backend_config_raw if isinstance(backend_config_raw, dict) else {}\\n            # Synthesise ``model_selection`` from legacy flat fields\\n            # when the on-disk metadata predates the unified-models\\n            # work. Reuse :func:`infer_embedding_provider` (#12417) so\\n            # backfilled rows get a non-\\\"Unknown\\\" provider whenever the\\n            # model name is recognizable\\n            # (e.g. ``text-embedding-3-small`` \u2192 ``OpenAI``).\\n            normalized_selection = _normalize_model_selection(model_selection)\\n            if not normalized_selection:\\n                embedding_model_raw = str(metadata.get(\\\"embedding_model\\\") or \\\"\\\")\\n                provider_raw = str(metadata.get(\\\"embedding_provider\\\") or \\\"Unknown\\\")\\n                if provider_raw == \\\"Unknown\\\" and embedding_model_raw:\\n                    provider_raw = infer_embedding_provider(embedding_model_raw)\\n                if embedding_model_raw or provider_raw != \\\"Unknown\\\":\\n                    normalized_selection = {\\n                        \\\"name\\\": embedding_model_raw,\\n                        \\\"provider\\\": provider_raw,\\n                    }\\n\\n            if not dry_run:\\n                await create_record(\\n                    user_id=user_id,\\n                    name=name,\\n                    model_selection=normalized_selection,\\n                    chunk_size=int(metadata.get(\\\"chunk_size\\\") or 1000),\\n                    chunk_overlap=int(metadata.get(\\\"chunk_overlap\\\") or 200),\\n                    separator=metadata.get(\\\"separator\\\"),\\n                    column_config=metadata.get(\\\"column_config\\\") or [],\\n                    backend_type=backend_type,\\n                    backend_config=backend_config,\\n                    chunks=_coerce_int(metadata.get(\\\"chunks\\\"), default=0),\\n                    words=_coerce_int(metadata.get(\\\"words\\\"), default=0),\\n                    characters=_coerce_int(metadata.get(\\\"characters\\\"), default=0),\\n                    size_bytes=_coerce_int(metadata.get(\\\"size_bytes\\\", metadata.get(\\\"size\\\")), default=0),\\n                    source_types=_coerce_source_types(metadata.get(\\\"source_types\\\")),\\n                    record_id=record_id,\\n                )\\n            inserted += 1\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.aerror(\\\"backfill: failed to upsert KB %s/%s: %s\\\", user_id, name, exc)\\n\\n    return inserted\\n\\n\\ndef _normalize_model_selection(raw) -> dict[str, Any]:\\n    \\\"\\\"\\\"Collapse a model_selection to its canonical single-dict form.\\\"\\\"\\\"\\n    if raw is None:\\n        return {}\\n    if isinstance(raw, list):\\n        return raw[0] if raw else {}\\n    if isinstance(raw, dict):\\n        return raw\\n    return {}\\n\\n\\ndef _coerce_uuid(value) -> UUID | None:\\n    \\\"\\\"\\\"Safely coerce a mixed-type value to ``UUID`` or ``None``.\\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    if isinstance(value, UUID):\\n        return value\\n    try:\\n        return UUID(str(value))\\n    except (ValueError, AttributeError, TypeError):\\n        return None\\n\\n\\ndef _coerce_int(value, *, default: int) -> int:\\n    \\\"\\\"\\\"Safely coerce metadata counters from legacy JSON into non-negative ints.\\\"\\\"\\\"\\n    try:\\n        coerced = int(value)\\n    except (TypeError, ValueError):\\n        return default\\n    return max(coerced, 0)\\n\\n\\ndef _coerce_source_types(value) -> list[str]:\\n    \\\"\\\"\\\"Normalize legacy source type metadata into a stable list of strings.\\\"\\\"\\\"\\n    if not isinstance(value, list):\\n        return []\\n    return sorted({str(item) for item in value if str(item).strip()})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/mcp/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e331d7a6f1faa00d1e840dc91a241c0ff763c2994cd3e7748b1d441b2874a90f\",\"content\":\"\\\"\\\"\\\"MCP utilities for Langflow.\\\"\\\"\\\"\\n\\nfrom langflow.api.utils.mcp.config_utils import (\\n    auto_configure_starter_projects_mcp,\\n    get_composer_streamable_http_url,\\n    get_project_local_sse_url,\\n    get_project_local_streamable_http_url,\\n    get_project_sse_url,\\n    get_project_streamable_http_url,\\n    get_url_by_os,\\n)\\n\\n__all__ = [\\n    \\\"auto_configure_starter_projects_mcp\\\",\\n    \\\"get_composer_streamable_http_url\\\",\\n    \\\"get_project_local_sse_url\\\",\\n    \\\"get_project_local_streamable_http_url\\\",\\n    \\\"get_project_sse_url\\\",\\n    \\\"get_project_streamable_http_url\\\",\\n    \\\"get_url_by_os\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/mcp/agentic_mcp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"58e2d80f0e0dcc2d3403f8dfa8de9a588a0c56188950a8d868974dd0016299ef\",\"content\":\"\\\"\\\"\\\"Per-user agentic global variables (FLOW_ID, COMPONENT_ID, FIELD_NAME).\\n\\nThe MCP-server auto-configuration that used to live here was removed: external\\nclients connect to the HTTP mount at ``/api/v1/agentic/mcp`` with their own API\\nkey instead of a per-user auto-registered stdio entry.\\n\\\"\\\"\\\"\\n\\nfrom uuid import UUID\\n\\nfrom fastapi import HTTPException\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import get_settings_service\\nfrom sqlalchemy import exc as sqlalchemy_exc\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_variable_service\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE, GENERIC_TYPE\\n\\n\\nasync def initialize_agentic_global_variables(session: AsyncSession) -> None:\\n    \\\"\\\"\\\"Initialize default global variables for agentic experience for all users.\\n\\n    This function creates agentic-specific global variables (FLOW_ID, COMPONENT_ID, FIELD_NAME)\\n    for all users if they don't already exist. These variables are used by the agentic\\n    experience to provide context-aware suggestions and operations.\\n\\n    Args:\\n        session: Database session for querying users and creating variables.\\n    \\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n\\n    # Only initialize if agentic experience is enabled\\n    if not settings_service.settings.agentic_experience:\\n        await logger.adebug(\\\"Agentic experience disabled, skipping agentic variables initialization\\\")\\n        return\\n\\n    await logger.ainfo(\\\"Initializing agentic global variables for all users...\\\")\\n\\n    try:\\n        # Get all users in the system\\n        users = (await session.exec(select(User))).all()\\n        await logger.adebug(f\\\"Found {len(users)} users for agentic variables initialization\\\")\\n\\n        if not users:\\n            await logger.adebug(\\\"No users found, skipping agentic variables initialization\\\")\\n            return\\n\\n        variable_service = get_variable_service()\\n\\n        # Define agentic variables with default values\\n        agentic_variables = {\\n            \\\"FLOW_ID\\\": \\\"\\\",\\n            \\\"COMPONENT_ID\\\": \\\"\\\",\\n            \\\"FIELD_NAME\\\": \\\"\\\",\\n        }\\n\\n        # Initialize variables for each user\\n        variables_created = 0\\n        variables_skipped = 0\\n\\n        for user in users:\\n            try:\\n                await logger.adebug(f\\\"Initializing agentic variables for user: {user.username}\\\")\\n\\n                # Get existing variables for this user\\n                existing_vars = await variable_service.list_variables(user.id, session)\\n\\n                for var_name, default_value in agentic_variables.items():\\n                    try:\\n                        if var_name not in existing_vars:\\n                            # Create variable with default value\\n                            await variable_service.create_variable(\\n                                user_id=user.id,\\n                                name=var_name,\\n                                value=default_value,\\n                                default_fields=[],\\n                                type_=GENERIC_TYPE,\\n                                session=session,\\n                            )\\n                            variables_created += 1\\n                            await logger.adebug(f\\\"Created agentic variable {var_name} for user {user.username}\\\")\\n                        else:\\n                            variables_skipped += 1\\n                            await logger.adebug(\\n                                f\\\"Agentic variable {var_name} already exists for user {user.username}, skipping\\\"\\n                            )\\n                    except (\\n                        HTTPException,\\n                        sqlalchemy_exc.SQLAlchemyError,\\n                        OSError,\\n                        PermissionError,\\n                        FileNotFoundError,\\n                        RuntimeError,\\n                        ValueError,\\n                        AttributeError,\\n                    ) as e:\\n                        await logger.aexception(\\n                            f\\\"Error creating agentic variable {var_name} for user {user.username}: {e}\\\"\\n                        )\\n                        continue\\n\\n            except (\\n                HTTPException,\\n                sqlalchemy_exc.SQLAlchemyError,\\n                OSError,\\n                PermissionError,\\n                FileNotFoundError,\\n                RuntimeError,\\n                ValueError,\\n                AttributeError,\\n            ) as e:\\n                await logger.aexception(f\\\"Failed to initialize agentic variables for user {user.username}: {e}\\\")\\n                continue\\n\\n        await logger.ainfo(\\n            f\\\"Agentic variables initialization complete: {variables_created} created, {variables_skipped} skipped\\\"\\n        )\\n\\n    except (\\n        HTTPException,\\n        sqlalchemy_exc.SQLAlchemyError,\\n        OSError,\\n        PermissionError,\\n        FileNotFoundError,\\n        RuntimeError,\\n        ValueError,\\n        AttributeError,\\n    ) as e:\\n        await logger.aexception(f\\\"Error during agentic variables initialization: {e}\\\")\\n\\n\\nasync def initialize_agentic_user_variables(user_id: UUID | str, session: AsyncSession) -> None:\\n    \\\"\\\"\\\"Initialize agentic-specific global variables for a single user if they don't exist.\\n\\n    This function is called during user login or creation to ensure each user has the\\n    required agentic variables (FLOW_ID, COMPONENT_ID, FIELD_NAME).\\n\\n    Args:\\n        user_id: The user ID to initialize variables for.\\n        session: Database session for creating variables.\\n    \\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n\\n    # Only initialize if agentic experience is enabled\\n    if not settings_service.settings.agentic_experience:\\n        await logger.adebug(f\\\"Agentic experience disabled, skipping agentic variables for user {user_id}\\\")\\n        return\\n\\n    await logger.adebug(f\\\"Initializing agentic variables for user {user_id}\\\")\\n\\n    try:\\n        variable_service = get_variable_service()\\n\\n        # Define agentic variables with defaults\\n        from lfx.services.settings.constants import AGENTIC_VARIABLES, DEFAULT_AGENTIC_VARIABLE_VALUE\\n\\n        # Create a dict with agentic variable names and default values as empty strings\\n        agentic_variables = dict.fromkeys(AGENTIC_VARIABLES, DEFAULT_AGENTIC_VARIABLE_VALUE)\\n        await logger.adebug(f\\\"Agentic variables: {list(agentic_variables.keys())}\\\")\\n\\n        existing_vars = await variable_service.list_variables(user_id, session)\\n\\n        for var_name, default_value in agentic_variables.items():\\n            await logger.adebug(f\\\"Checking if agentic variable {var_name} exists for user {user_id}\\\")\\n            if var_name not in existing_vars:\\n                try:\\n                    await variable_service.create_variable(\\n                        user_id=user_id,\\n                        name=var_name,\\n                        value=default_value,\\n                        default_fields=[],\\n                        type_=CREDENTIAL_TYPE,\\n                        session=session,\\n                    )\\n                    await logger.adebug(f\\\"Created agentic variable {var_name} for user {user_id}\\\")\\n                except (\\n                    HTTPException,\\n                    sqlalchemy_exc.SQLAlchemyError,\\n                    OSError,\\n                    PermissionError,\\n                    FileNotFoundError,\\n                    RuntimeError,\\n                    ValueError,\\n                    AttributeError,\\n                ) as e:\\n                    await logger.aexception(f\\\"Error creating agentic variable {var_name} for user {user_id}: {e}\\\")\\n            else:\\n                await logger.adebug(f\\\"Agentic variable {var_name} already exists for user {user_id}, skipping\\\")\\n\\n    except (\\n        HTTPException,\\n        sqlalchemy_exc.SQLAlchemyError,\\n        OSError,\\n        PermissionError,\\n        FileNotFoundError,\\n        RuntimeError,\\n        ValueError,\\n        AttributeError,\\n    ) as e:\\n        await logger.aexception(f\\\"Error initializing agentic variables for user {user_id}: {e}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/mcp/backfill.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01af78ad3300653e89c91aeb15eebb33899a8ea1d950c1e283dba1b55c56e783\",\"content\":\"\\\"\\\"\\\"Backfill MCP servers from the legacy per-user JSON file into the mcp_server table.\\n\\nRuns best-effort on startup and via ``langflow migrate-mcp``. Properties:\\n\\n- **Idempotent** \u2014 only inserts a server that isn't already a row for that user, so\\n  it is safe to run on every boot and to re-run by hand.\\n- **Multi-replica safe** \u2014 the ``(user_id, name)`` unique constraint is the backstop;\\n  a concurrent insert from another replica raises ``IntegrityError`` which is caught.\\n- **Backend-agnostic** \u2014 reads through the storage service, so it covers local disk\\n  and S3/Ceph/MinIO identically.\\n- **Non-destructive** \u2014 the legacy file is never deleted, so rolling back to a\\n  file-based Langflow remains safe.\\n\\\"\\\"\\\"\\n\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\n\\nfrom langflow.api.v2.mcp import _read_legacy_mcp_file\\nfrom langflow.logging import logger\\nfrom langflow.services.auth.mcp_encryption import encrypt_mcp_config\\nfrom langflow.services.database.models import MCPServer\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_settings_service, get_storage_service\\n\\n\\nasync def backfill_mcp_servers_from_files(session, *, dry_run: bool = False) -> dict[str, int]:\\n    \\\"\\\"\\\"Import each user's legacy ``_mcp_servers_<id>.json`` entries into ``mcp_server``.\\n\\n    Args:\\n        session: An async DB session.\\n        dry_run: If True, count what would be imported without writing.\\n\\n    Returns:\\n        Summary counts: ``{\\\"users\\\", \\\"imported\\\", \\\"skipped\\\", \\\"errors\\\"}``.\\n    \\\"\\\"\\\"\\n    storage_service = get_storage_service()\\n    settings_service = get_settings_service()\\n    summary = {\\\"users\\\": 0, \\\"imported\\\": 0, \\\"skipped\\\": 0, \\\"errors\\\": 0}\\n\\n    users = (await session.exec(select(User))).all()\\n    for user in users:\\n        summary[\\\"users\\\"] += 1\\n        try:\\n            legacy = await _read_legacy_mcp_file(\\n                user, session, storage_service, settings_service, create_if_missing=False\\n            )\\n        except Exception as e:  # noqa: BLE001\\n            summary[\\\"errors\\\"] += 1\\n            await logger.awarning(f\\\"MCP backfill: could not read legacy MCP file for user {user.id}: {e}\\\")\\n            continue\\n\\n        pending = 0\\n        for name, config in (legacy.get(\\\"mcpServers\\\") or {}).items():\\n            already = (\\n                await session.exec(select(MCPServer).where(MCPServer.user_id == user.id, MCPServer.name == name))\\n            ).first()\\n            if already is not None:\\n                summary[\\\"skipped\\\"] += 1\\n                continue\\n            summary[\\\"imported\\\"] += 1\\n            if dry_run:\\n                continue\\n            session.add(MCPServer(user_id=user.id, name=name, config=encrypt_mcp_config(config or {})))\\n            pending += 1\\n\\n        if pending:\\n            try:\\n                await session.commit()\\n            except IntegrityError:\\n                # Another replica imported this user's servers first; safe to skip.\\n                await session.rollback()\\n\\n    await logger.ainfo(\\n        \\\"MCP backfill complete: users=%s imported=%s skipped=%s errors=%s\\\",\\n        summary[\\\"users\\\"],\\n        summary[\\\"imported\\\"],\\n        summary[\\\"skipped\\\"],\\n        summary[\\\"errors\\\"],\\n    )\\n    return summary\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/mcp/config_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"95daf244a0b1e9c30b439f49de290aa6dcf4fe096f3cddcadb3f78fe7cfe9299\",\"content\":\"import asyncio\\nimport platform\\nfrom asyncio.subprocess import create_subprocess_exec\\nfrom datetime import datetime, timezone\\nfrom uuid import UUID\\n\\nfrom fastapi import HTTPException\\nfrom lfx.base.mcp.constants import MAX_MCP_SERVER_NAME_LENGTH\\nfrom lfx.base.mcp.util import sanitize_mcp_name\\nfrom lfx.base.mcp.uvx import mcp_sdk_constraint_args\\nfrom lfx.log import logger\\nfrom lfx.services.deps import get_settings_service\\nfrom sqlmodel import select\\n\\nfrom langflow.api.v2.mcp import get_server_list, update_server\\nfrom langflow.services.auth.mcp_encryption import decrypt_auth_settings, encrypt_auth_settings\\nfrom langflow.services.database.models import Flow, Folder\\nfrom langflow.services.database.models.api_key.crud import create_api_key\\nfrom langflow.services.database.models.api_key.model import ApiKeyCreate\\nfrom langflow.services.database.models.folder.constants import DEFAULT_FOLDER_NAME\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_storage_service\\n\\nALL_INTERFACES_HOST = \\\"0.0.0.0\\\"  # noqa: S104\\n\\n\\ndef mcp_server_config_uses_current_uvx_constraint(server_config: dict, package: str) -> bool:\\n    \\\"\\\"\\\"Return whether a generated uvx config uses the current SDK constraint and package.\\\"\\\"\\\"\\n    if server_config.get(\\\"command\\\") != \\\"uvx\\\":\\n        return False\\n\\n    args = server_config.get(\\\"args\\\")\\n    if not isinstance(args, list):\\n        return False\\n\\n    expected_prefix = [*mcp_sdk_constraint_args(), package]\\n    return args[: len(expected_prefix)] == expected_prefix\\n\\n\\nclass MCPServerValidationResult:\\n    \\\"\\\"\\\"Represents the result of an MCP server validation check.\\n\\n    This class encapsulates the outcome of checking whether an MCP server\\n    configuration can be safely created or updated for a given project. The typical\\n    sequence is as follows:\\n\\n    1. Initiation: An operation requiring an MCP server (e.g., creating a\\n        new project with MCP enabled) triggers a validation check.\\n    2. Validation: The validate_mcp_server_for_project function is called.\\n        It generates the expected server name from the project name and checks\\n        if a server with that name already exists.\\n    3. Ownership Check: If a server exists, the function verifies if it\\n        belongs to the current project by checking for the project's UUID in\\n        the server's configuration.\\n    4. Result: An instance of this class is returned, summarizing whether\\n        the server exists and if the project ID matches.\\n    5. Decision: The calling code uses the properties of this result\\n        (has_conflict, should_skip, should_proceed) to determine the next\\n        action, such as aborting on conflict, skipping if already configured,\\n        or proceeding with the setup.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        server_exists: bool,\\n        project_id_matches: bool,\\n        server_name: str = \\\"\\\",\\n        existing_config: dict | None = None,\\n        conflict_message: str = \\\"\\\",\\n    ):\\n        self.server_exists = server_exists\\n        self.project_id_matches = project_id_matches\\n        self.server_name = server_name\\n        self.existing_config = existing_config\\n        self.conflict_message = conflict_message\\n\\n    @property\\n    def has_conflict(self) -> bool:\\n        \\\"\\\"\\\"Returns True when an MCP server name collision occurs.\\n\\n        This indicates that another project is already using the desired server name.\\n        \\\"\\\"\\\"\\n        return self.server_exists and not self.project_id_matches\\n\\n    @property\\n    def should_skip(self) -> bool:\\n        \\\"\\\"\\\"Returns True when the MCP server configuration is already correct for this project.\\n\\n        This indicates that the server exists and is properly configured for the current project.\\n        \\\"\\\"\\\"\\n        return self.server_exists and self.project_id_matches\\n\\n    @property\\n    def should_proceed(self) -> bool:\\n        \\\"\\\"\\\"Returns True when MCP server setup can proceed safely without conflicts.\\n\\n        This indicates either no server exists (safe to create) or the existing server\\n        belongs to the current project (safe to update).\\n        \\\"\\\"\\\"\\n        return not self.server_exists or self.project_id_matches\\n\\n\\nasync def validate_mcp_server_for_project(\\n    project_id: UUID,\\n    project_name: str,\\n    user,\\n    session,\\n    storage_service,\\n    settings_service,\\n    operation: str = \\\"create\\\",\\n) -> MCPServerValidationResult:\\n    \\\"\\\"\\\"Validate MCP server for a project operation.\\n\\n    Args:\\n        project_id: The project UUID\\n        project_name: The project name\\n        user: The user performing the operation\\n        session: Database session\\n        storage_service: Storage service\\n        settings_service: Settings service\\n        operation: Operation type (\\\"create\\\", \\\"update\\\", \\\"delete\\\")\\n\\n    Returns:\\n        MCPServerValidationResult with validation details\\n    \\\"\\\"\\\"\\n    # Generate server name that would be used for this project\\n    server_name = f\\\"lf-{sanitize_mcp_name(project_name)[: (MAX_MCP_SERVER_NAME_LENGTH - 4)]}\\\"\\n\\n    try:\\n        existing_servers = await get_server_list(user, session, storage_service, settings_service)\\n\\n        if server_name not in existing_servers.get(\\\"mcpServers\\\", {}):\\n            # Server doesn't exist\\n            return MCPServerValidationResult(\\n                project_id_matches=False,\\n                server_exists=False,\\n                server_name=server_name,\\n            )\\n\\n        # Server exists - check if project ID matches\\n        existing_server_config = existing_servers[\\\"mcpServers\\\"][server_name]\\n        existing_args = existing_server_config.get(\\\"args\\\", [])\\n        project_id_matches = False\\n\\n        if existing_args:\\n            # SSE URL is typically the last argument\\n            # TODO: Better way Required to check the postion of the SSE URL in the args\\n            existing_sse_urls = await extract_urls_from_strings(existing_args)\\n            for existing_sse_url in existing_sse_urls:\\n                if str(project_id) in existing_sse_url:\\n                    project_id_matches = True\\n                    break\\n        else:\\n            project_id_matches = False\\n\\n        # Generate appropriate conflict message based on operation\\n        conflict_message = \\\"\\\"\\n        if not project_id_matches:\\n            if operation == \\\"create\\\":\\n                conflict_message = (\\n                    f\\\"MCP server name conflict: '{server_name}' already exists \\\"\\n                    f\\\"for a different project. Cannot create MCP server for project \\\"\\n                    f\\\"'{project_name}' (ID: {project_id})\\\"\\n                )\\n            elif operation == \\\"update\\\":\\n                conflict_message = (\\n                    f\\\"MCP server name conflict: '{server_name}' exists for a different project. \\\"\\n                    f\\\"Cannot update MCP server for project '{project_name}' (ID: {project_id})\\\"\\n                )\\n            elif operation == \\\"delete\\\":\\n                conflict_message = (\\n                    f\\\"MCP server '{server_name}' exists for a different project. \\\"\\n                    f\\\"Cannot delete MCP server for project '{project_name}' (ID: {project_id})\\\"\\n                )\\n\\n        return MCPServerValidationResult(\\n            server_exists=True,\\n            project_id_matches=project_id_matches,\\n            server_name=server_name,\\n            existing_config=existing_server_config,\\n            conflict_message=conflict_message,\\n        )\\n\\n    except Exception as e:  # noqa: BLE001\\n        await logger.awarning(f\\\"Could not validate MCP server for project {project_id}: {e}\\\")\\n        # Return result allowing operation to proceed on validation failure\\n        return MCPServerValidationResult(\\n            project_id_matches=False,\\n            server_exists=False,\\n            server_name=server_name,\\n        )\\n\\n\\nasync def get_url_by_os(host: str, port: int, url: str) -> str:\\n    \\\"\\\"\\\"Get the URL by operating system.\\\"\\\"\\\"\\n    os_type = platform.system()\\n    is_wsl = os_type == \\\"Linux\\\" and \\\"microsoft\\\" in platform.uname().release.lower()\\n\\n    if is_wsl and host in {\\\"localhost\\\", \\\"127.0.0.1\\\"}:\\n        try:\\n            proc = await create_subprocess_exec(\\n                \\\"/usr/bin/hostname\\\",\\n                \\\"-I\\\",\\n                stdout=asyncio.subprocess.PIPE,\\n                stderr=asyncio.subprocess.PIPE,\\n            )\\n            stdout, _ = await proc.communicate()\\n\\n            if proc.returncode == 0 and stdout.strip():\\n                wsl_ip = stdout.decode().strip().split()[0]  # Get first IP address\\n                await logger.adebug(\\\"Using WSL IP for external access: %s\\\", wsl_ip)\\n                # Replace the localhost with the WSL IP in the URL\\n                url = url.replace(f\\\"http://{host}:{port}\\\", f\\\"http://{wsl_ip}:{port}\\\")\\n        except OSError as e:\\n            await logger.awarning(\\\"Failed to get WSL IP address: %s. Using default URL.\\\", str(e))\\n\\n    return url\\n\\n\\nasync def _get_project_base_url_components() -> tuple[str, int]:\\n    \\\"\\\"\\\"Return normalized host and port for building MCP URLs.\\\"\\\"\\\"\\n    # Get settings service to build the SSE URL\\n    settings_service = get_settings_service()\\n    server_host = getattr(settings_service.settings, \\\"host\\\", \\\"localhost\\\")\\n    # Use the runtime-detected port if available, otherwise fall back to configured port\\n    server_port = (\\n        getattr(settings_service.settings, \\\"runtime_port\\\", None)\\n        or getattr(settings_service.settings, \\\"port\\\", None)\\n        or 7860\\n    )\\n\\n    # For MCP clients, always use localhost instead of 0.0.0.0\\n    # 0.0.0.0 is a bind address, not a connect address\\n    host = \\\"localhost\\\" if server_host == ALL_INTERFACES_HOST else server_host\\n    return host, server_port\\n\\n\\nasync def _get_project_base_url() -> tuple[str, str | None, int | None]:\\n    \\\"\\\"\\\"Return ``(base_url, host, port)`` for building MCP project URLs.\\n\\n    When ``LANGFLOW_MCP_BASE_URL`` is set it is the authoritative externally-reachable origin\\n    (scheme + host + optional path) and is used verbatim; ``host``/``port`` come back ``None`` so\\n    callers skip OS/WSL rewriting of an operator-supplied URL. This is what lets a pod bind to\\n    ``0.0.0.0`` while advertising a routable gateway/service address \u2014 ``host`` alone cannot do both\\n    (it is also the uvicorn bind address, and the builder rewrites ``0.0.0.0`` to ``localhost``).\\n\\n    With the setting empty (the default) behaviour is unchanged: build ``http://{host}:{port}`` from\\n    ``host``/``port`` and keep WSL handling. Backwards compatible.\\n    \\\"\\\"\\\"\\n    settings_service = get_settings_service()\\n    configured = (getattr(settings_service.settings, \\\"mcp_base_url\\\", \\\"\\\") or \\\"\\\").strip().rstrip(\\\"/\\\")\\n    if configured:\\n        return configured, None, None\\n    host, port = await _get_project_base_url_components()\\n    return f\\\"http://{host}:{port}\\\".rstrip(\\\"/\\\"), host, port\\n\\n\\nasync def _build_project_url(project_id: UUID, suffix: str) -> str:\\n    \\\"\\\"\\\"Build the client-facing project URL, honouring an operator-supplied base URL.\\\"\\\"\\\"\\n    base_url, host, port = await _get_project_base_url()\\n    project_url = f\\\"{base_url}/api/v1/mcp/project/{project_id}/{suffix}\\\"\\n    # An explicit LANGFLOW_MCP_BASE_URL is used as-is; only host/port-derived URLs get WSL rewriting.\\n    if host is None or port is None:\\n        return project_url\\n    return await get_url_by_os(host, port, project_url)\\n\\n\\nasync def _build_local_project_url(project_id: UUID, suffix: str) -> str:\\n    \\\"\\\"\\\"Build the pod-local project URL, always from the bind host/port.\\\"\\\"\\\"\\n    host, port = await _get_project_base_url_components()\\n    project_url = f\\\"http://{host}:{port}/api/v1/mcp/project/{project_id}/{suffix}\\\"\\n    return await get_url_by_os(host, port, project_url)\\n\\n\\nasync def get_project_streamable_http_url(project_id: UUID) -> str:\\n    \\\"\\\"\\\"Generate the Streamable HTTP endpoint for a project (no /sse suffix).\\\"\\\"\\\"\\n    return await _build_project_url(project_id, \\\"streamable\\\")\\n\\n\\nasync def get_project_sse_url(project_id: UUID) -> str:\\n    \\\"\\\"\\\"Generate the legacy SSE URL for a project, including WSL handling.\\\"\\\"\\\"\\n    return await _build_project_url(project_id, \\\"sse\\\")\\n\\n\\nasync def get_project_local_streamable_http_url(project_id: UUID) -> str:\\n    \\\"\\\"\\\"Streamable HTTP endpoint as reachable from inside this process.\\n\\n    MCP Composer runs as a subprocess here and dials the project endpoint as an upstream\\n    member server, so it needs the address that resolves locally. ``LANGFLOW_MCP_BASE_URL``\\n    names where *clients* should connect; routing pod-local traffic through that gateway\\n    would leave the pod and, behind a load balancer, come back to a different one.\\n    \\\"\\\"\\\"\\n    return await _build_local_project_url(project_id, \\\"streamable\\\")\\n\\n\\nasync def get_project_local_sse_url(project_id: UUID) -> str:\\n    \\\"\\\"\\\"Legacy SSE endpoint as reachable from inside this process. See the streamable variant.\\\"\\\"\\\"\\n    return await _build_local_project_url(project_id, \\\"sse\\\")\\n\\n\\nasync def _get_mcp_composer_auth_config(project: Folder) -> dict:\\n    \\\"\\\"\\\"Decrypt and return MCP Composer auth configuration for a project.\\\"\\\"\\\"\\n    auth_config = None\\n    if project.auth_settings:\\n        decrypted_settings = decrypt_auth_settings(project.auth_settings)\\n        if decrypted_settings:\\n            auth_config = decrypted_settings\\n\\n    if not auth_config:\\n        error_message = \\\"Auth config is missing. Please check your settings and try again.\\\"\\n        raise ValueError(error_message)\\n\\n    return auth_config\\n\\n\\nasync def get_composer_streamable_http_url(project: Folder) -> str:\\n    \\\"\\\"\\\"Generate Streamable HTTP URL for the MCP Composer instance.\\\"\\\"\\\"\\n    auth_config = await _get_mcp_composer_auth_config(project)\\n    composer_host = auth_config.get(\\\"oauth_host\\\")\\n    composer_port = auth_config.get(\\\"oauth_port\\\")\\n    if not composer_host or not composer_port:\\n        error_msg = \\\"OAuth host and port are required to get the MCP Composer URL\\\"\\n        raise ValueError(error_msg)\\n    composer_url = f\\\"http://{composer_host}:{composer_port}\\\"\\n    return await get_url_by_os(composer_host, int(composer_port), composer_url)  # type: ignore[arg-type]\\n\\n\\nasync def auto_configure_starter_projects_mcp(session):\\n    \\\"\\\"\\\"Auto-configure MCP servers for starter projects for all users at startup.\\\"\\\"\\\"\\n    # Check if auto-configure is enabled\\n    settings_service = get_settings_service()\\n    await logger.adebug(\\\"Starting auto-configure starter projects MCP\\\")\\n    if not settings_service.settings.add_projects_to_mcp_servers:\\n        await logger.adebug(\\\"Auto-Configure MCP servers disabled, skipping starter project MCP configuration\\\")\\n        return\\n    await logger.adebug(\\n        f\\\"Auto-configure settings: add_projects_to_mcp_servers=\\\"\\n        f\\\"{settings_service.settings.add_projects_to_mcp_servers}, \\\"\\n        f\\\"create_starter_projects={settings_service.settings.create_starter_projects}, \\\"\\n        f\\\"update_starter_projects={settings_service.settings.update_starter_projects}\\\"\\n    )\\n\\n    try:\\n        # Get all users in the system\\n        users = (await session.exec(select(User))).all()\\n        await logger.adebug(f\\\"Found {len(users)} users in the system\\\")\\n        if not users:\\n            await logger.adebug(\\\"No users found, skipping starter project MCP configuration\\\")\\n            return\\n\\n        # Add starter projects to each user's MCP server configuration\\n        total_servers_added = 0\\n        for user in users:\\n            await logger.adebug(f\\\"Processing user: {user.username} (ID: {user.id})\\\")\\n            try:\\n                # First, let's see what folders this user has\\n                all_user_folders = (await session.exec(select(Folder).where(Folder.user_id == user.id))).all()\\n                folder_names = [f.name for f in all_user_folders]\\n                await logger.adebug(f\\\"User {user.username} has folders: {folder_names}\\\")\\n\\n                # Find THIS USER'S own starter projects folder\\n                # Each user has their own \\\"Starter Projects\\\" folder with unique ID\\n                user_starter_folder = (\\n                    await session.exec(\\n                        select(Folder).where(\\n                            Folder.name == DEFAULT_FOLDER_NAME,\\n                            Folder.user_id == user.id,  # Each user has their own!\\n                        )\\n                    )\\n                ).first()\\n                if not user_starter_folder:\\n                    await logger.adebug(\\n                        f\\\"No starter projects folder ('{DEFAULT_FOLDER_NAME}') found for user {user.username}, skipping\\\"\\n                    )\\n                    # Log what folders this user does have for debugging\\n                    await logger.adebug(f\\\"User {user.username} available folders: {folder_names}\\\")\\n                    continue\\n\\n                await logger.adebug(\\n                    f\\\"Found starter folder '{user_starter_folder.name}' for {user.username}: \\\"\\n                    f\\\"ID={user_starter_folder.id}\\\"\\n                )\\n\\n                # Configure MCP settings for flows in THIS USER'S starter folder\\n                flows_query = select(Flow).where(\\n                    Flow.folder_id == user_starter_folder.id,\\n                    Flow.is_component == False,  # noqa: E712\\n                )\\n                user_starter_flows = (await session.exec(flows_query)).all()\\n\\n                # Enable MCP for starter flows if not already configured\\n                flows_configured = 0\\n                for flow in user_starter_flows:\\n                    if flow.mcp_enabled is None:\\n                        flow.mcp_enabled = True\\n                        if not flow.action_name:\\n                            flow.action_name = sanitize_mcp_name(flow.name)\\n                        if not flow.action_description:\\n                            flow.action_description = flow.description or f\\\"Starter project: {flow.name}\\\"\\n                        flow.updated_at = datetime.now(timezone.utc)\\n                        session.add(flow)\\n                        flows_configured += 1\\n\\n                if flows_configured > 0:\\n                    await logger.adebug(f\\\"Enabled MCP for {flows_configured} starter flows for user {user.username}\\\")\\n\\n                # Validate MCP server for this starter projects folder\\n                validation_result = await validate_mcp_server_for_project(\\n                    user_starter_folder.id,\\n                    DEFAULT_FOLDER_NAME,\\n                    user,\\n                    session,\\n                    get_storage_service(),\\n                    settings_service,\\n                    operation=\\\"create\\\",\\n                )\\n\\n                # Skip if the server already has the expected URL and uvx SDK constraint.\\n                if validation_result.should_skip:\\n                    expected_url = await get_project_streamable_http_url(user_starter_folder.id)\\n                    existing_config = validation_result.existing_config or {}\\n                    existing_args = existing_config.get(\\\"args\\\", [])\\n                    existing_urls = await extract_urls_from_strings(existing_args)\\n\\n                    if mcp_server_config_uses_current_uvx_constraint(existing_config, \\\"mcp-proxy\\\") and any(\\n                        expected_url == url for url in existing_urls\\n                    ):\\n                        await logger.adebug(\\n                            f\\\"MCP server '{validation_result.server_name}' already exists and is correctly \\\"\\n                            f\\\"configured for user {user.username}'s starter projects (project ID: \\\"\\n                            f\\\"{user_starter_folder.id}), skipping\\\"\\n                        )\\n                        continue  # Skip this user since server already exists for the same project\\n\\n                    await logger.adebug(\\n                        f\\\"MCP server '{validation_result.server_name}' exists for user {user.username}'s \\\"\\n                        f\\\"starter projects but its generated configuration is stale \\\"\\n                        f\\\"(URLs: {existing_urls}, expected URL: {expected_url}), updating\\\"\\n                    )\\n\\n                server_name = validation_result.server_name\\n\\n                # Set up THIS USER'S starter folder authentication (same as new projects)\\n                # If AUTO_LOGIN is false, automatically enable API key authentication\\n                default_auth = {\\\"auth_type\\\": \\\"none\\\"}\\n                await logger.adebug(\\\"Settings service auth settings: [REDACTED]\\\")\\n                await logger.adebug(\\\"User starter folder auth settings: [REDACTED]\\\")\\n                if (\\n                    not user_starter_folder.auth_settings\\n                    and settings_service.auth_settings.AUTO_LOGIN\\n                    and not settings_service.auth_settings.SUPERUSER\\n                ):\\n                    default_auth = {\\\"auth_type\\\": \\\"apikey\\\"}\\n                    user_starter_folder.auth_settings = encrypt_auth_settings(default_auth)\\n                    await logger.adebug(\\n                        \\\"AUTO_LOGIN enabled without SUPERUSER; forcing API key auth for starter folder %s\\\",\\n                        user.username,\\n                    )\\n                elif not settings_service.auth_settings.AUTO_LOGIN and not user_starter_folder.auth_settings:\\n                    default_auth = {\\\"auth_type\\\": \\\"apikey\\\"}\\n                    user_starter_folder.auth_settings = encrypt_auth_settings(default_auth)\\n                    await logger.adebug(f\\\"Set up auth settings for user {user.username}'s starter folder\\\")\\n                elif user_starter_folder.auth_settings:\\n                    default_auth = user_starter_folder.auth_settings\\n\\n                # Create API key for this user to access their own starter projects\\n                api_key_name = f\\\"MCP Project {DEFAULT_FOLDER_NAME} - {user.username}\\\"\\n                unmasked_api_key = await create_api_key(session, ApiKeyCreate(name=api_key_name), user.id)\\n\\n                # Build connection URLs for THIS USER'S starter folder (unique ID per user)\\n                streamable_http_url = await get_project_streamable_http_url(user_starter_folder.id)\\n\\n                # Prepare server config (similar to new project creation)\\n                if default_auth.get(\\\"auth_type\\\", \\\"none\\\") == \\\"apikey\\\":\\n                    command = \\\"uvx\\\"\\n                    args = [\\n                        *mcp_sdk_constraint_args(),\\n                        \\\"mcp-proxy\\\",\\n                        \\\"--transport\\\",\\n                        \\\"streamablehttp\\\",\\n                        \\\"--headers\\\",\\n                        \\\"x-api-key\\\",\\n                        unmasked_api_key.api_key,\\n                        streamable_http_url,\\n                    ]\\n                elif default_auth.get(\\\"auth_type\\\", \\\"none\\\") == \\\"oauth\\\":\\n                    msg = \\\"OAuth authentication is not yet implemented for MCP server creation during project creation.\\\"\\n                    logger.warning(msg)\\n                    raise HTTPException(status_code=501, detail=msg)\\n                else:  # default_auth_type == \\\"none\\\"\\n                    # No authentication - direct connection\\n                    command = \\\"uvx\\\"\\n                    args = [\\n                        *mcp_sdk_constraint_args(),\\n                        \\\"mcp-proxy\\\",\\n                        \\\"--transport\\\",\\n                        \\\"streamablehttp\\\",\\n                        streamable_http_url,\\n                    ]\\n                server_config = {\\\"command\\\": command, \\\"args\\\": args}\\n\\n                # Add to user's MCP servers configuration\\n                await logger.adebug(f\\\"Adding MCP server '{server_name}' for user {user.username}\\\")\\n                await update_server(\\n                    server_name,\\n                    server_config,\\n                    user,\\n                    session,\\n                    get_storage_service(),\\n                    settings_service,\\n                )\\n\\n                total_servers_added += 1\\n                await logger.adebug(f\\\"Added starter projects MCP server for user: {user.username}\\\")\\n\\n            except Exception as e:  # noqa: BLE001\\n                # If server already exists or other issues, just log and continue\\n                await logger.aerror(f\\\"Could not add starter projects MCP server for user {user.username}: {e}\\\")\\n                continue\\n\\n        await session.commit()\\n\\n        if total_servers_added > 0:\\n            await logger.adebug(f\\\"Added starter projects MCP servers for {total_servers_added} users\\\")\\n        else:\\n            await logger.adebug(\\\"No new starter project MCP servers were added\\\")\\n\\n    except Exception as e:  # noqa: BLE001\\n        await logger.aerror(f\\\"Failed to auto-configure starter projects MCP servers: {e}\\\")\\n\\n\\nasync def extract_urls_from_strings(strings: list[str]) -> list[str]:\\n    \\\"\\\"\\\"Extract URLs from a list of strings.\\n\\n    Args:\\n        strings: List of strings to search for URLs\\n\\n    Returns:\\n        List of URLs found in the input strings\\n    \\\"\\\"\\\"\\n    import re\\n\\n    # URL pattern to match http/https URLs\\n    url_pattern = r'https?://[^\\\\s<>\\\"{}|\\\\\\\\^`\\\\[\\\\]]+[^\\\\s<>\\\"{}|\\\\\\\\^`\\\\[\\\\].,;:!?]'\\n\\n    urls = []\\n    for string in strings:\\n        if isinstance(string, str):\\n            found_urls = re.findall(url_pattern, string)\\n            urls.extend(found_urls)\\n\\n    return urls\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/mcp/flow_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3ad757f842fc80f9fdcafa6cd7a53e4961ca5d1a4d907308e5426df07f9673ee\",\"content\":\"\\\"\\\"\\\"Keep MCP credentials out of ``flow.data`` when a flow is written.\\n\\n``flow.data`` is an unencrypted JSON column that travels through export, share and\\nversion history, so a credential stored there is a credential handed to everyone the\\nflow is handed to. The ``mcp_server`` table is the encrypted home for the same value,\\nand ``resolve_mcp_config`` already prefers it at runtime, so moving the secret across\\ncosts the flow nothing at run time.\\n\\nForward-only by design: flows written before this keep their embedded config and keep\\nresolving through the same precedence, so no saved flow changes behavior.\\n\\\"\\\"\\\"\\n\\nimport hashlib\\nimport re\\nfrom typing import Any\\nfrom uuid import UUID\\n\\nfrom fastapi import HTTPException\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\n\\nfrom langflow.logging import logger\\nfrom langflow.services.auth.mcp_encryption import MCP_SECRET_CONFIG_MAPS, decrypt_mcp_config, encrypt_mcp_config\\nfrom langflow.services.database.lock_retry import is_database_lock_error\\nfrom langflow.services.database.models import MCPServer\\nfrom langflow.services.deps import get_variable_service\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE\\n\\nSECRET_CONFIG_FIELDS = (\\\"api_key\\\", \\\"apiKey\\\", \\\"authorization\\\", \\\"Authorization\\\")\\n\\n# Headers that are part of the HTTP conversation, never a credential. An allowlist of\\n# known non-secrets, deliberately not a heuristic for \\\"looks secret\\\": guessing which\\n# values are sensitive fails open into a leak, while these specific names cannot be one.\\nNON_SECRET_HEADERS = frozenset(\\n    {\\n        \\\"accept\\\",\\n        \\\"accept-charset\\\",\\n        \\\"accept-encoding\\\",\\n        \\\"accept-language\\\",\\n        \\\"cache-control\\\",\\n        \\\"content-type\\\",\\n        \\\"user-agent\\\",\\n    }\\n)\\n\\nHEADER_ARG_FLAG = \\\"--headers\\\"\\n\\nVARIABLE_PREFIX = \\\"MCP_\\\"\\n\\nPLACEHOLDER_PATTERN = re.compile(r\\\"^\\\\{\\\\{\\\\s*[A-Za-z_][A-Za-z0-9_\\\\-]*\\\\s*\\\\}\\\\}$\\\")\\n\\n\\ndef _is_variable_reference(value: str) -> bool:\\n    \\\"\\\"\\\"Whether a value is already a reference, so a re-save does not wrap it twice.\\n\\n    Recognising any capitalised token failed open on the alphabet of the secret: an AWS\\n    access key id, or any uppercase hex token, reads as a reference and was copied into\\n    the flow verbatim. Only the two shapes this system can actually resolve count \u2014 the\\n    names generated below, and the explicit ``{{NAME}}`` placeholder.\\n    \\\"\\\"\\\"\\n    return bool(PLACEHOLDER_PATTERN.match(value)) or value.startswith(VARIABLE_PREFIX)\\n\\n\\ndef _strip_header_args(args: list[Any]) -> tuple[list[Any], bool]:\\n    \\\"\\\"\\\"Drop ``--headers <name> <value>`` triples, which is where auto-install bakes the key.\\\"\\\"\\\"\\n    cleaned: list[Any] = []\\n    found = False\\n    index = 0\\n    while index < len(args):\\n        if args[index] == HEADER_ARG_FLAG and index + 2 < len(args):\\n            found = True\\n            index += 3\\n            continue\\n        cleaned.append(args[index])\\n        index += 1\\n    return cleaned, found\\n\\n\\ndef variable_name_for(server_name: str, key: str) -> str:\\n    \\\"\\\"\\\"Build the global-variable name that replaces a literal secret.\\n\\n    Deterministic so a re-save of the same server lands on the same variable instead of\\n    minting a new one on every write.\\n\\n    The digest is what makes the name injective. Slugifying alone collapsed\\n    ``billing-mcp``, ``billing_mcp`` and ``billing.mcp`` onto one name, and because an\\n    existing variable is never overwritten the second server would silently authenticate\\n    to its own target using the first server's credential.\\n    \\\"\\\"\\\"\\n    slug = re.sub(r\\\"[^A-Za-z0-9]+\\\", \\\"_\\\", f\\\"{server_name}_{key}\\\").strip(\\\"_\\\").upper()\\n    digest = hashlib.sha256(f\\\"{server_name}\\\\0{key}\\\".encode()).hexdigest()[:8].upper()\\n    return f\\\"{VARIABLE_PREFIX}{slug}_{digest}\\\"\\n\\n\\ndef strip_config_secrets(config: dict[str, Any], server_name: str) -> tuple[dict[str, Any], dict[str, str], bool]:\\n    \\\"\\\"\\\"Swap literal secrets for global-variable names.\\n\\n    A reference rather than a blank: a config with an empty ``headers`` names nothing, so\\n    a stateless runtime (``lfx serve``, which has no ``mcp_server`` table) has no way to\\n    restore the credential. The name keeps the flow self-describing and portable.\\n\\n    Returns the rewritten config, the variable name to value map that has to exist for it\\n    to resolve, and whether anything was rewritten.\\n    \\\"\\\"\\\"\\n    stripped = dict(config)\\n    variables: dict[str, str] = {}\\n    found = False\\n\\n    for key in MCP_SECRET_CONFIG_MAPS:\\n        value = stripped.get(key)\\n        if isinstance(value, dict) and value:\\n            referenced = {}\\n            for entry_key, entry_value in value.items():\\n                skip = key == \\\"headers\\\" and str(entry_key).lower() in NON_SECRET_HEADERS\\n                if (\\n                    not skip\\n                    and isinstance(entry_value, str)\\n                    and entry_value\\n                    and not _is_variable_reference(entry_value)\\n                ):\\n                    name = variable_name_for(server_name, entry_key)\\n                    variables[name] = entry_value\\n                    referenced[entry_key] = name\\n                    found = True\\n                else:\\n                    referenced[entry_key] = entry_value\\n            stripped[key] = referenced\\n\\n    for field in SECRET_CONFIG_FIELDS:\\n        if stripped.get(field):\\n            del stripped[field]\\n            found = True\\n\\n    args = stripped.get(\\\"args\\\")\\n    if isinstance(args, list):\\n        cleaned_args, had_header_args = _strip_header_args(args)\\n        if had_header_args:\\n            stripped[\\\"args\\\"] = cleaned_args\\n            found = True\\n\\n    return stripped, variables, found\\n\\n\\ndef _iter_mcp_server_fields(flow_data: dict[str, Any] | None):\\n    \\\"\\\"\\\"Yield every ``mcp_server`` template field of a flow, nested subflows included.\\\"\\\"\\\"\\n    if not isinstance(flow_data, dict):\\n        return\\n    frames = [iter(flow_data.get(\\\"nodes\\\") or [])]\\n    while frames:\\n        try:\\n            node = next(frames[-1])\\n        except StopIteration:\\n            frames.pop()\\n            continue\\n        if not isinstance(node, dict):\\n            continue\\n        node_data = node.get(\\\"data\\\")\\n        if not isinstance(node_data, dict):\\n            continue\\n        inner = node_data.get(\\\"node\\\")\\n        if not isinstance(inner, dict):\\n            continue\\n\\n        template = inner.get(\\\"template\\\")\\n        if isinstance(template, dict):\\n            field = template.get(\\\"mcp_server\\\")\\n            if isinstance(field, dict):\\n                yield field\\n\\n        nested = inner.get(\\\"flow\\\")\\n        if isinstance(nested, dict):\\n            nested_data = nested.get(\\\"data\\\")\\n            if isinstance(nested_data, dict) and isinstance(nested_data.get(\\\"nodes\\\"), list):\\n                frames.append(iter(nested_data[\\\"nodes\\\"]))\\n\\n\\ndef extract_and_strip_mcp_secrets(\\n    flow_data: dict[str, Any] | None,\\n) -> tuple[list[tuple[str, dict[str, Any]]], dict[str, str]]:\\n    \\\"\\\"\\\"Strip MCP secrets from ``flow_data`` in place, returning what has to be stored instead.\\n\\n    Each entry is the server name and the *original* config, so the caller can persist a\\n    runnable config while the flow keeps only what is safe to hand around.\\n    \\\"\\\"\\\"\\n    carried: list[tuple[str, dict[str, Any]]] = []\\n    variables: dict[str, str] = {}\\n\\n    for field in _iter_mcp_server_fields(flow_data):\\n        value = field.get(\\\"value\\\")\\n        if not isinstance(value, dict):\\n            continue\\n        config = value.get(\\\"config\\\")\\n        if not isinstance(config, dict):\\n            continue\\n\\n        name = value.get(\\\"name\\\")\\n        server_name = name if isinstance(name, str) and name else \\\"server\\\"\\n\\n        stripped, config_variables, found = strip_config_secrets(config, server_name)\\n        if not found:\\n            continue\\n\\n        if isinstance(name, str) and name:\\n            carried.append((name, config))\\n        variables.update(config_variables)\\n        value[\\\"config\\\"] = stripped\\n\\n    return carried, variables\\n\\n\\ndef mcp_server_names(flow_data: dict[str, Any] | None) -> set[str]:\\n    \\\"\\\"\\\"Names of the MCP servers a flow already references.\\\"\\\"\\\"\\n    names: set[str] = set()\\n    for field in _iter_mcp_server_fields(flow_data):\\n        value = field.get(\\\"value\\\")\\n        if isinstance(value, dict):\\n            name = value.get(\\\"name\\\")\\n            if isinstance(name, str) and name:\\n                names.add(name)\\n    return names\\n\\n\\nasync def stage_mcp_secrets(\\n    carried: list[tuple[str, dict[str, Any]]],\\n    variables: dict[str, str],\\n    user_id: UUID,\\n    session,\\n    *,\\n    rotatable_servers: set[str] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Stage the carried credential on the caller's session.\\n\\n    Split from the extraction on purpose. ``run_with_lock_retry`` rolls the session back\\n    between attempts, which discards the staged rows, while the in-place rewrite of\\n    ``flow_data`` survives in memory. Re-extracting on attempt 2 therefore finds only the\\n    reference it wrote itself, stages nothing, and the flow commits pointing at a global\\n    variable that does not exist. Extract once, stage per attempt.\\n\\n    Raises when a credential could not be stored securely. Putting the literal back into\\n    ``flow.data`` instead would answer 200 while writing the secret to an unencrypted\\n    column that travels through export, share and version history \u2014 the caller would never\\n    learn the protection had been skipped. Refusing the write is visible and recoverable.\\n    \\\"\\\"\\\"\\n    if not carried and not variables:\\n        return\\n\\n    failed = await _ensure_variables(variables, user_id, session)\\n    if failed:\\n        raise HTTPException(\\n            status_code=500,\\n            detail=(\\n                \\\"Could not store an MCP credential securely, so the flow was not saved. \\\"\\n                \\\"Retry, or set the credential as a global variable and reference it from the server config.\\\"\\n            ),\\n        )\\n\\n    for name, config in carried:\\n        existing = (\\n            await session.exec(select(MCPServer).where(MCPServer.user_id == user_id, MCPServer.name == name))\\n        ).first()\\n        if existing is not None:\\n            # Rotating here only makes sense when the user is editing a server this flow was\\n            # already bound to. The row is keyed on (user, name) and shared by every flow of\\n            # that user, so rotating on any write let one import re-point all of them at\\n            # whatever credential the file carried, unrecoverably. Only the secret-bearing\\n            # maps are replaced, so the URL, mode and args maintained here survive.\\n            if rotatable_servers and name in rotatable_servers:\\n                _apply_rotated_secrets(existing, config)\\n            continue\\n        try:\\n            async with session.begin_nested():\\n                session.add(MCPServer(user_id=user_id, name=name, config=encrypt_mcp_config(config)))\\n        except IntegrityError:\\n            # Another writer created the same (user, name) first; its row is authoritative.\\n            await logger.adebug(f\\\"MCP server row '{name}' already exists; keeping the stored config.\\\")\\n        except Exception as exc:\\n            if is_database_lock_error(exc):\\n                raise\\n            await logger.aerror(f\\\"Could not persist MCP server config carried by a flow: {exc}\\\")\\n\\n\\nasync def persist_and_strip_mcp_secrets(flow_data: dict[str, Any] | None, user_id: UUID, session) -> None:\\n    \\\"\\\"\\\"Move any MCP credential in ``flow_data`` into the user's encrypted server rows.\\n\\n    An existing row is never overwritten: it is the config the user maintains through the\\n    server manager, and a flow copy is not authoritative over it.\\n\\n    Nothing is committed here. The rows are staged on the caller's session so they land in\\n    the same transaction as the flow itself \u2014 committing mid-request would break the\\n    all-or-nothing contract of the batch write path.\\n\\n    Callers that run inside ``run_with_lock_retry`` must not use this: extract once with\\n    ``extract_and_strip_mcp_secrets`` outside the loop and call ``stage_mcp_secrets``\\n    inside each attempt, so a rollback cannot leave the flow referencing a variable that\\n    was never created.\\n\\n    A secret carried inside ``args`` (the ``--headers`` triple that auto-install bakes in)\\n    is dropped rather than referenced, because variables are not resolved inside ``args``.\\n    Under Langflow the ``mcp_server`` row still serves it; under ``lfx serve`` it is gone.\\n    \\\"\\\"\\\"\\n    carried, variables = extract_and_strip_mcp_secrets(flow_data)\\n    await stage_mcp_secrets(carried, variables, user_id, session)\\n\\n\\nasync def _ensure_variables(variables: dict[str, str], user_id: UUID, session) -> set[str]:\\n    \\\"\\\"\\\"Create the referenced global variables so the rewritten config resolves.\\n\\n    Existing names are left alone: the value the user maintains outranks a copy that\\n    happened to be sitting in a flow. Returns the names that could not be created, so the\\n    caller can put those literals back instead of saving a flow that cannot authenticate.\\n    \\\"\\\"\\\"\\n    if not variables:\\n        return set()\\n\\n    variable_service = get_variable_service()\\n    existing_names = set()\\n    try:\\n        existing_names = set(await variable_service.list_variables(user_id, session))\\n    except Exception as exc:\\n        if is_database_lock_error(exc):\\n            raise\\n        await logger.awarning(f\\\"Could not list global variables while scrubbing an MCP credential: {exc}\\\")\\n\\n    failed: set[str] = set()\\n    for name, value in variables.items():\\n        if name in existing_names:\\n            if not await _rotate_variable(variable_service, name, value, user_id, session):\\n                failed.add(name)\\n            continue\\n        try:\\n            async with session.begin_nested():\\n                await variable_service.create_variable(\\n                    user_id=user_id, name=name, value=value, type_=CREDENTIAL_TYPE, session=session\\n                )\\n        except Exception as exc:\\n            # A contended write is transient, not a verdict on this variable. Swallowing it\\n            # would hand the literal back and save the secret in plaintext; let the caller's\\n            # retry re-run the whole operation instead.\\n            if is_database_lock_error(exc):\\n                raise\\n            failed.add(name)\\n            await logger.aerror(f\\\"Could not create global variable '{name}' for an MCP credential: {exc}\\\")\\n    return failed\\n\\n\\ndef _apply_rotated_secrets(existing: MCPServer, config: dict[str, Any]) -> None:\\n    \\\"\\\"\\\"Overwrite only the secret-bearing maps of a stored server config.\\\"\\\"\\\"\\n    stored = decrypt_mcp_config(existing.config or {})\\n    changed = False\\n    for key in MCP_SECRET_CONFIG_MAPS:\\n        incoming = config.get(key)\\n        if isinstance(incoming, dict) and incoming and stored.get(key) != incoming:\\n            stored[key] = incoming\\n            changed = True\\n    if changed:\\n        existing.config = encrypt_mcp_config(stored)\\n\\n\\nasync def _rotate_variable(variable_service, name: str, value: str, user_id: UUID, session) -> bool:\\n    \\\"\\\"\\\"Point an existing variable at the value the flow just carried.\\n\\n    Returns whether the variable now holds it, so the caller can restore the literal\\n    rather than save a flow that authenticates with a credential the user replaced.\\n    \\\"\\\"\\\"\\n    try:\\n        current = await variable_service.get_variable(user_id=user_id, name=name, field=\\\"\\\", session=session)\\n    except Exception:  # noqa: BLE001\\n        current = None\\n    if current == value:\\n        return True\\n    try:\\n        async with session.begin_nested():\\n            await variable_service.update_variable(user_id=user_id, name=name, value=value, session=session)\\n    except Exception as exc:\\n        if is_database_lock_error(exc):\\n            raise\\n        await logger.aerror(f\\\"Could not rotate global variable '{name}' for an MCP credential: {exc}\\\")\\n        return False\\n    return True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/utils/zip_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"93e973640451f6d28bc1581439a2aab08573376ca14c68041d9908de1d6f4a67\",\"content\":\"\\\"\\\"\\\"Utilities for handling ZIP file uploads containing flow JSON data.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport io\\nimport zipfile\\nfrom dataclasses import dataclass, field\\n\\nimport orjson\\nfrom lfx.log.logger import logger\\n\\n# Safety limits to prevent zip bomb / DoS attacks\\nMAX_ZIP_ENTRIES = 500\\nMAX_ENTRY_UNCOMPRESSED_BYTES = 50 * 1024 * 1024  # 50 MB per file\\n\\n\\n@dataclass\\nclass _ZipExtractionResult:\\n    \\\"\\\"\\\"Result of synchronous ZIP extraction, including warnings to log after.\\\"\\\"\\\"\\n\\n    flows: list[dict] = field(default_factory=list)\\n    warnings: list[str] = field(default_factory=list)\\n\\n\\ndef _extract_flows_sync(contents: bytes) -> _ZipExtractionResult:\\n    \\\"\\\"\\\"Synchronous helper that performs all blocking ZIP I/O.\\n\\n    Raises:\\n        ValueError: If the ZIP is corrupt or contains more than MAX_ZIP_ENTRIES JSON files.\\n    \\\"\\\"\\\"\\n    result = _ZipExtractionResult()\\n\\n    try:\\n        zf = zipfile.ZipFile(io.BytesIO(contents), \\\"r\\\")\\n    except zipfile.BadZipFile as exc:\\n        msg = f\\\"Uploaded file is not a valid ZIP archive: {exc}\\\"\\n        raise ValueError(msg) from exc\\n\\n    with zf:\\n        json_entries = [info for info in zf.infolist() if info.filename.lower().endswith(\\\".json\\\")]\\n\\n        if len(json_entries) > MAX_ZIP_ENTRIES:\\n            msg = f\\\"ZIP contains {len(json_entries)} JSON entries, exceeding the limit of {MAX_ZIP_ENTRIES}\\\"\\n            raise ValueError(msg)\\n\\n        for info in json_entries:\\n            if info.file_size > MAX_ENTRY_UNCOMPRESSED_BYTES:\\n                result.warnings.append(\\n                    f\\\"Skipping ZIP entry '{info.filename}': uncompressed size \\\"\\n                    f\\\"{info.file_size} exceeds limit of {MAX_ENTRY_UNCOMPRESSED_BYTES} bytes\\\"\\n                )\\n                continue\\n            try:\\n                raw = zf.read(info.filename)\\n                if len(raw) > MAX_ENTRY_UNCOMPRESSED_BYTES:\\n                    result.warnings.append(\\n                        f\\\"Skipping ZIP entry '{info.filename}': actual size \\\"\\n                        f\\\"{len(raw)} exceeds limit of {MAX_ENTRY_UNCOMPRESSED_BYTES} bytes\\\"\\n                    )\\n                    continue\\n                result.flows.append(orjson.loads(raw))\\n            except orjson.JSONDecodeError:\\n                result.warnings.append(f\\\"Skipping ZIP entry '{info.filename}': invalid JSON\\\")\\n                continue\\n\\n    return result\\n\\n\\nasync def extract_flows_from_zip(contents: bytes) -> list[dict]:\\n    \\\"\\\"\\\"Extract flow JSON data from a ZIP file.\\n\\n    Reads all .json files from the ZIP archive and returns their parsed contents.\\n    Enforces limits on entry count and individual file size to mitigate zip bomb attacks.\\n    Blocking I/O is offloaded to a thread to avoid blocking the event loop.\\n\\n    Raises:\\n        ValueError: If the ZIP is corrupt or contains more than MAX_ZIP_ENTRIES JSON files.\\n    \\\"\\\"\\\"\\n    result = await asyncio.to_thread(_extract_flows_sync, contents)\\n\\n    for warning in result.warnings:\\n        await logger.awarning(warning)\\n\\n    return result.flows\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e267cd0acb13742f5c6a795798e05d279c0849d774c34a2fcaaf55991854acf0\",\"content\":\"from langflow.api.v1.a2a import router as a2a_router\\nfrom langflow.api.v1.api_key import router as api_key_router\\nfrom langflow.api.v1.authz_audit import router as authz_audit_router\\nfrom langflow.api.v1.authz_me import router as authz_me_router\\nfrom langflow.api.v1.authz_role_assignments import router as authz_role_assignments_router\\nfrom langflow.api.v1.authz_roles import router as authz_roles_router\\nfrom langflow.api.v1.authz_shares import router as authz_shares_router\\nfrom langflow.api.v1.authz_teams import router as authz_teams_router\\nfrom langflow.api.v1.catalog_policy import router as catalog_policy_router\\nfrom langflow.api.v1.chat import router as chat_router\\nfrom langflow.api.v1.endpoints import router as endpoints_router\\nfrom langflow.api.v1.extensions import router as extensions_router\\nfrom langflow.api.v1.files import router as files_router\\nfrom langflow.api.v1.flow_events import router as flow_events_router\\nfrom langflow.api.v1.flow_version import router as flow_version_router\\nfrom langflow.api.v1.flows import router as flows_router\\nfrom langflow.api.v1.folders import router as folders_router\\nfrom langflow.api.v1.knowledge_bases import router as knowledge_bases_router\\nfrom langflow.api.v1.login import router as login_router\\nfrom langflow.api.v1.mcp import router as mcp_router\\nfrom langflow.api.v1.mcp_projects import router as mcp_projects_router\\nfrom langflow.api.v1.memories import router as memories_router\\nfrom langflow.api.v1.model_options import router as model_options_router\\nfrom langflow.api.v1.model_provider_policy import router as model_provider_policy_router\\nfrom langflow.api.v1.models import router as models_router\\nfrom langflow.api.v1.monitor import router as monitor_router\\nfrom langflow.api.v1.openai_responses import router as openai_responses_router\\nfrom langflow.api.v1.policy_bundle import router as policy_bundle_router\\nfrom langflow.api.v1.projects import router as projects_router\\nfrom langflow.api.v1.starter_projects import router as starter_projects_router\\nfrom langflow.api.v1.store import router as store_router\\nfrom langflow.api.v1.traces import router as traces_router\\nfrom langflow.api.v1.users import router as users_router\\nfrom langflow.api.v1.validate import router as validate_router\\nfrom langflow.api.v1.variable import router as variables_router\\nfrom langflow.api.v1.voice_mode import router as voice_mode_router\\n\\n__all__ = [\\n    \\\"a2a_router\\\",\\n    \\\"api_key_router\\\",\\n    \\\"authz_audit_router\\\",\\n    \\\"authz_me_router\\\",\\n    \\\"authz_role_assignments_router\\\",\\n    \\\"authz_roles_router\\\",\\n    \\\"authz_shares_router\\\",\\n    \\\"authz_teams_router\\\",\\n    \\\"catalog_policy_router\\\",\\n    \\\"chat_router\\\",\\n    \\\"endpoints_router\\\",\\n    \\\"extensions_router\\\",\\n    \\\"files_router\\\",\\n    \\\"flow_events_router\\\",\\n    \\\"flow_version_router\\\",\\n    \\\"flows_router\\\",\\n    \\\"folders_router\\\",\\n    \\\"knowledge_bases_router\\\",\\n    \\\"login_router\\\",\\n    \\\"mcp_projects_router\\\",\\n    \\\"mcp_router\\\",\\n    \\\"memories_router\\\",\\n    \\\"model_options_router\\\",\\n    \\\"model_provider_policy_router\\\",\\n    \\\"models_router\\\",\\n    \\\"monitor_router\\\",\\n    \\\"openai_responses_router\\\",\\n    \\\"policy_bundle_router\\\",\\n    \\\"projects_router\\\",\\n    \\\"starter_projects_router\\\",\\n    \\\"store_router\\\",\\n    \\\"traces_router\\\",\\n    \\\"users_router\\\",\\n    \\\"validate_router\\\",\\n    \\\"variables_router\\\",\\n    \\\"voice_mode_router\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/a2a.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"49e6350702322d24741c2904e316256a9c6ca75d831fd42a4cfcd19b12dd80cd\",\"content\":\"\\\"\\\"\\\"A2A protocol routes.\\n\\nTwo public per-flow endpoints, both behind ``LANGFLOW_A2A_ENABLED`` (default off):\\n\\n- ``GET  /api/v1/a2a/{flow_id}/.well-known/agent-card.json`` serves the agent card.\\n- ``POST /api/v1/a2a/{flow_id}/jsonrpc`` serves the A2A JSON-RPC surface\\n  (``message/send`` runs the flow and returns a terminal Task; ``message/stream``\\n  streams the same run's lifecycle as SSE; ``tasks/get`` reads a task back from\\n  the durable, DB-backed store; ``tasks/resubscribe`` re-attaches to a live run).\\n\\nThe router is mounted unconditionally and a per-request guard returns 404 when\\nthe flag is off, so the routes are indistinguishable from \\\"not mounted\\\". This\\nmirrors the extensions router and avoids the import-time / env-file ordering\\ntrap of reading a module-level flag.\\n\\nThe a2a-sdk server stack is protobuf-based. One shared ``DefaultRequestHandler``\\n+ ``DurableTaskStore`` + ``JsonRpcDispatcher`` serve every flow; the per-request\\n``flow_id`` is carried via the server call-context state into the protocol-pure\\nexecutor (``a2a_executor.FlowAgentExecutor``). Tasks persist in the ``a2a_tasks``\\ntable so they survive restart and are visible across workers.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport hashlib\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nimport httpx\\nfrom a2a.server.agent_execution.active_task import TERMINAL_TASK_STATES\\nfrom a2a.server.context import ServerCallContext\\nfrom a2a.server.jsonrpc_models import JSONRPCError as CoreJSONRPCError\\nfrom a2a.server.owner_resolver import resolve_user_scope\\nfrom a2a.server.request_handlers import DefaultRequestHandler\\nfrom a2a.server.routes.common import DefaultServerCallContextBuilder\\nfrom a2a.server.routes.jsonrpc_dispatcher import JSONRPC03Adapter, JsonRpcDispatcher\\nfrom a2a.server.tasks import BasePushNotificationSender, InMemoryPushNotificationConfigStore, TaskStore\\nfrom a2a.types import a2a_pb2 as pb\\nfrom a2a.utils.errors import (\\n    JSON_RPC_ERROR_CODE_MAP as _A2A_ERROR_CODES,\\n)\\nfrom a2a.utils.errors import (\\n    A2AError,\\n    InvalidParamsError,\\n    TaskNotCancelableError,\\n    TaskNotFoundError,\\n    UnsupportedOperationError,\\n)\\nfrom fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, Request, Response, status\\nfrom google.protobuf.json_format import MessageToDict, ParseDict\\nfrom lfx.graph.checkpoint.resume import resume_graph_with_decision\\nfrom lfx.graph.checkpoint.schema import GraphCheckpoint\\nfrom lfx.graph.checkpoint.store import CheckpointStore\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.run.hitl import reroute_decision_on_timeout\\nfrom lfx.schema.workflow import (\\n    GLOBAL_KEY_MAX_LEN,\\n    JobStatus,\\n    WorkflowExecutionResponse,\\n    WorkflowRunRequest,\\n)\\nfrom lfx.services.deps import get_settings_service, session_scope, session_scope_readonly\\nfrom lfx.utils.flow_validation import prepare_public_flow_build, validate_public_flow_no_code_execution\\nfrom lfx.utils.ssrf_transport import create_ssrf_protected_client\\nfrom lfx.workflow.converters import parse_workflow_run_request, run_response_to_workflow_response\\nfrom sqlalchemy import case, delete, false\\nfrom sqlmodel import col, select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.utils.core import strip_secret_field_values\\nfrom langflow.api.utils.flow_utils import compute_virtual_flow_id, scope_session_to_namespace\\nfrom langflow.api.v1.a2a_executor import FlowAgentExecutor, ResumeConflictError\\nfrom langflow.api.v1.a2a_utils import (\\n    A2A_APIKEY_HEADER,\\n    build_agent_card,\\n    folder_auth_type,\\n    validate_webhook_url,\\n    webhook_pin_host,\\n)\\nfrom langflow.helpers.flow import get_flow_by_id_or_endpoint_name\\nfrom langflow.helpers.user import get_user_by_flow_id_or_endpoint_name\\nfrom langflow.services.auth.context import AuthCredentialContext, set_current_auth_context\\nfrom langflow.services.authorization import (\\n    FlowAction,\\n    ensure_flow_permission,\\n    filter_visible_resources,\\n    restrict_to_owned_or_visible_scope,\\n    should_apply_owner_override,\\n    visible_scope_prefilter,\\n)\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.authorization.public_access import (\\n    PUBLIC_ANONYMOUS_ACTOR_ID,\\n    PublicGrantSource,\\n    PublicResourceAction,\\n    authorize_public_flow_access,\\n    public_execution_user,\\n)\\nfrom langflow.services.authorization.utils import _resolve_authz_domain\\nfrom langflow.services.database.models import A2ACheckpoint, A2ATask, Flow\\nfrom langflow.services.database.models.api_key.crud import authenticate_api_key\\nfrom langflow.services.database.models.flow.model import FlowType\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User, UserRead\\nfrom langflow.services.model_provider_policy_scope import scoped_model_provider_policy_for_flow\\n\\nrouter = APIRouter(prefix=\\\"/a2a\\\", tags=[\\\"a2a\\\"])\\n\\n\\ndef _require_a2a_enabled() -> None:\\n    \\\"\\\"\\\"Return 404 when the A2A feature flag is off.\\n\\n    Reads the live settings per request (after env/dotenv load), matching\\n    langflow.api.v1.extensions._require_extension_reload_enabled.\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    if not getattr(settings, \\\"a2a_enabled\\\", False):\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\")\\n\\n\\nasync def _enforce_a2a_auth(flow: Flow, request: Request) -> User | None:\\n    \\\"\\\"\\\"Enforce the folder's auth scheme before any dispatch, failing closed on the rest.\\n\\n    Public agents run as the isolated anonymous principal; protected agents run\\n    as the authenticated flow owner. Gate by the folder's ``auth_type``:\\n\\n    - ``\\\"none\\\"`` / missing / no-folder -> public agent (the intended public A2A model).\\n    - ``\\\"apikey\\\"`` / ``\\\"oauth\\\"`` -> require a valid langflow API key in ``x-api-key`` whose\\n      owner is the flow owner. An oauth folder is fronted by an external OAuth broker (the dance\\n      happens in front); the langflow transport itself still takes an owner-scoped api key,\\n      exactly as the MCP transport does (``mcp_projects.verify_project_auth``), since credential\\n      forwarding from the broker isn't available yet. Accepting another user's valid key would\\n      let them trigger an owner-authenticated run, so scope to ``flow.user_id``.\\n    - anything else (an auth type A2A doesn't understand) -> fail closed with 403: treating a\\n      *protected* folder as public would bypass its admission policy.\\n\\n    Uses ``authenticate_api_key`` directly, NOT ``api_key_security``: under AUTO_LOGIN the latter\\n    returns the superuser for a *missing* key, which would silently bypass this gate.\\n    \\\"\\\"\\\"\\n    # Resolve the folder policy first, then close that read session before API-key\\n    # authentication opens its owned write transaction.\\n    async with session_scope_readonly() as session:\\n        auth_type = await folder_auth_type(flow, session)\\n    if auth_type == \\\"none\\\":\\n        await authorize_public_flow_access(\\n            flow=flow,\\n            action=PublicResourceAction.EXECUTE,\\n            request_host=request.url.hostname,\\n            compatibility_grant=PublicGrantSource.A2A_AUTH_NONE,\\n        )\\n        return None  # public agent\\n    if auth_type not in (\\\"apikey\\\", \\\"oauth\\\"):\\n        # Protected folder with a scheme A2A can't enforce: fail closed, never public.\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=f\\\"A2A access is disabled for this agent: unsupported folder auth type {auth_type!r}.\\\",\\n        )\\n    api_key = request.headers.get(A2A_APIKEY_HEADER)\\n    if not api_key:\\n        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"API key required\\\")\\n    api_key_result = await authenticate_api_key(api_key)\\n    # Same message for invalid and wrong-owner: don't reveal a key is valid for another user.\\n    if api_key_result is None or api_key_result.user.id != flow.user_id:\\n        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"Invalid API key\\\")\\n    user = api_key_result.user\\n    set_current_auth_context(AuthCredentialContext.from_api_key_result(api_key_result))\\n    try:\\n        await ensure_flow_permission(\\n            user,\\n            FlowAction.EXECUTE,\\n            flow_id=flow.id,\\n            flow_user_id=flow.user_id,\\n            folder_id=flow.folder_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Not Found\\\") from exc\\n    return user\\n\\n\\nclass _FlowContextBuilder(DefaultServerCallContextBuilder):\\n    \\\"\\\"\\\"Carry the per-request flow_id into the shared executor via call-context state.\\\"\\\"\\\"\\n\\n    def build(self, request: Request) -> ServerCallContext:\\n        context = super().build(request)\\n        # Canonicalize to the same string form the resume guard uses (str(UUID(...))), so the durable\\n        # store scope (_task_scope / _push_config_scope) and the checkpoint/resume guard agree even for\\n        # a non-canonical UUID in the path (uppercase or hyphenless, both valid to the UUID route\\n        # converter). Without this, the same task addressed via two encodings lands in two scopes.\\n        context.state[\\\"flow_id\\\"] = str(UUID(request.path_params[\\\"flow_id\\\"]))\\n        context.state[\\\"request_host\\\"] = request.url.hostname\\n        # Written only by ``a2a_jsonrpc`` after its auth gate. Never derive this\\n        # from headers inside the SDK producer: folder policy can change after\\n        # the HTTP handler returns while a background run is still starting.\\n        context.state[\\\"admitted_user_id\\\"] = getattr(request.state, \\\"a2a_admitted_user_id\\\", None)\\n        return context\\n\\n\\nasync def _is_public_a2a_flow(flow: Flow) -> bool:\\n    \\\"\\\"\\\"Whether an A2A flow admits callers without an API key.\\\"\\\"\\\"\\n    async with session_scope_readonly() as session:\\n        return await folder_auth_type(flow, session) == \\\"none\\\"\\n\\n\\nasync def _prepare_a2a_execution_flow(flow: Flow, request_host: str | None = None) -> Flow:\\n    \\\"\\\"\\\"Reauthorize and apply public code policy after the caller binds the public principal.\\\"\\\"\\\"\\n    await authorize_public_flow_access(\\n        flow=flow,\\n        action=PublicResourceAction.EXECUTE,\\n        request_host=request_host,\\n        compatibility_grant=PublicGrantSource.A2A_AUTH_NONE,\\n    )\\n    validate_public_flow_no_code_execution(flow.data)\\n    prepared_data = await prepare_public_flow_build(flow.data)\\n    sanitized_data = strip_secret_field_values(prepared_data if prepared_data is not None else flow.data)\\n    return flow.model_copy(update={\\\"data\\\": sanitized_data}, deep=True)\\n\\n\\ndef _require_admitted_a2a_principal(\\n    flow: Flow,\\n    *,\\n    is_public_now: bool,\\n    admitted_user_id: str | None,\\n) -> str:\\n    \\\"\\\"\\\"Require mutable folder policy to match the immutable HTTP-gate principal.\\\"\\\"\\\"\\n    current_principal_id = PUBLIC_ANONYMOUS_ACTOR_ID if is_public_now else flow.user_id\\n    if current_principal_id is None or admitted_user_id != str(current_principal_id):\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\")\\n    return str(current_principal_id)\\n\\n\\nasync def _prepare_a2a_resume_checkpoint(\\n    flow_id: UUID,\\n    checkpoint: GraphCheckpoint,\\n    request_host: str | None = None,\\n    admitted_user_id: str | None = None,\\n) -> tuple[GraphCheckpoint, Flow, User | UserRead]:\\n    \\\"\\\"\\\"Reauthorize and re-apply public policy before restoring a HITL graph.\\\"\\\"\\\"\\n    flow = await get_flow_by_id_or_endpoint_name(str(flow_id))\\n    is_public_now = await _is_public_a2a_flow(flow)\\n    current_principal_id = _require_admitted_a2a_principal(\\n        flow,\\n        is_public_now=is_public_now,\\n        admitted_user_id=admitted_user_id,\\n    )\\n    if checkpoint.user_id != current_principal_id:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\")\\n    if not is_public_now:\\n        user = await get_user_by_flow_id_or_endpoint_name(str(flow_id))\\n        return checkpoint, flow, user\\n\\n    await authorize_public_flow_access(\\n        flow=flow,\\n        action=PublicResourceAction.EXECUTE,\\n        request_host=request_host,\\n        compatibility_grant=PublicGrantSource.A2A_AUTH_NONE,\\n    )\\n    validate_public_flow_no_code_execution(checkpoint.flow_payload)\\n    prepared_data = await prepare_public_flow_build(checkpoint.flow_payload)\\n    sanitized_data = strip_secret_field_values(prepared_data if prepared_data is not None else checkpoint.flow_payload)\\n    sanitized_checkpoint = checkpoint.model_copy(update={\\\"flow_payload\\\": sanitized_data}, deep=True)\\n    return sanitized_checkpoint, flow, public_execution_user()\\n\\n\\nasync def _run_flow(\\n    flow_id: UUID,\\n    task_id: str,\\n    text: str,\\n    context_id: str | None,\\n    request_host: str | None = None,\\n    admitted_user_id: str | None = None,\\n) -> WorkflowExecutionResponse:\\n    \\\"\\\"\\\"Run a flow synchronously through the v2 surface under its admitted principal.\\n\\n    Anonymous A2A runs use the isolated public principal; API-key/OAuth runs\\n    retain their authenticated owner principal. The helpers self-manage short\\n    readonly sessions, so no DB session is held across the up-to-300s run.\\n    ``task_id`` doubles as the v2 job_id when it is a UUID (so run_id == taskId\\n    on the sync path); a non-UUID client task id falls back to a fresh job_id.\\n\\n    The A2A ``context_id`` is namespaced under a per-(principal, flow) virtual id and\\n    that becomes the flow ``session_id``, so multi-turn calls sharing a contextId\\n    share chat memory while a contextId can never address another flow's session.\\n    The SDK mints a contextId when the client omits one, so each conversation gets\\n    its own isolated session.\\n    \\\"\\\"\\\"\\n    # Lazy import: langflow.api.v2.workflow pulls in the execution stack and this\\n    # module is imported during router assembly.\\n    from langflow.api.v2.workflow import execute_sync_workflow_with_timeout\\n\\n    flow = await get_flow_by_id_or_endpoint_name(str(flow_id))\\n    is_public_now = await _is_public_a2a_flow(flow)\\n    _require_admitted_a2a_principal(\\n        flow,\\n        is_public_now=is_public_now,\\n        admitted_user_id=admitted_user_id,\\n    )\\n    if is_public_now:\\n        user = public_execution_user()\\n        flow = await _prepare_a2a_execution_flow(flow, request_host)\\n    else:\\n        user = await get_user_by_flow_id_or_endpoint_name(str(flow_id))\\n        flow = await get_flow_by_id_or_endpoint_name(str(flow_id), user.id)\\n    # context_id is client-controlled on a public endpoint, so namespace it under a\\n    # per-(principal, flow) virtual id before it becomes the chat session_id: a contextId\\n    # can never address another flow's session. The stable anonymous id or authenticated\\n    # owner id folds the admitted principal into the key. The namespaced value lands in the indexed\\n    # MessageTable.session_id (Postgres btree entries are size-capped), so when the\\n    # composed key would exceed the bound, hash the contextId rather than truncating\\n    # (which would collide two long ids) or falling back to the shared per-flow default\\n    # (which would re-open the cross-caller leak). Only an absent contextId uses the default.\\n    namespace = str(compute_virtual_flow_id(user.id, flow_id))\\n    if context_id:\\n        scoped = scope_session_to_namespace(context_id, namespace)\\n        session_id = (\\n            scoped\\n            if scoped and len(scoped) <= GLOBAL_KEY_MAX_LEN\\n            else f\\\"{namespace}:{hashlib.sha256(context_id.encode()).hexdigest()}\\\"\\n        )\\n    else:\\n        session_id = None\\n    parsed = parse_workflow_run_request(\\n        WorkflowRunRequest(flow_id=str(flow_id), input_value=text, mode=\\\"sync\\\", session_id=session_id)\\n    )\\n    try:\\n        job_id = UUID(task_id)\\n    except ValueError:\\n        job_id = uuid4()\\n    # Bound before the v2 executor underneath binds \\\"v2\\\": this run arrived over A2A, and\\n    # outermost wins, so the operator sees the surface rather than the shared implementation.\\n    with execution_protocol(\\\"a2a\\\"):\\n        return await execute_sync_workflow_with_timeout(\\n            parsed=parsed,\\n            flow=flow,\\n            job_id=job_id,\\n            current_user=user,\\n            background_tasks=BackgroundTasks(),\\n            http_request=None,\\n            # HITL: a flow with a HumanInput node durably checkpoints and returns a suspended\\n            # response instead of running through. Resume happens in _resume_flow.\\n            checkpoint_store=A2ACheckpointStore(),\\n            expose_error_details=False,\\n        )\\n\\n\\ndef _resolve_action(text: str, pending: dict[str, Any]) -> str | None:\\n    \\\"\\\"\\\"The allowed HumanInput action id the reply selects, or None when it matches none.\\n\\n    The node routes on an ``action_id`` (``label.lower().replace(\\\" \\\", \\\"_\\\")``). Match the reply\\n    against the pause's allowed action ids, then against option labels. None means \\\"no offered\\n    action\\\", so the caller re-parks rather than taking an empty no-branch path.\\n    \\\"\\\"\\\"\\n    allowed = pending.get(\\\"allowed_decisions\\\") or []\\n    candidate = text.strip().lower().replace(\\\" \\\", \\\"_\\\")\\n    if candidate in allowed:\\n        return candidate\\n    for option in pending.get(\\\"options\\\") or []:\\n        if str(option.get(\\\"label\\\", \\\"\\\")).strip().lower() == text.strip().lower():\\n            return option.get(\\\"action_id\\\")\\n    return None\\n\\n\\ndef _suspended_response(flow_id: UUID, task_id: str, session_id: str | None, pending: dict[str, Any]):\\n    return WorkflowExecutionResponse(\\n        flow_id=str(flow_id),\\n        session_id=session_id,\\n        job_id=task_id,\\n        status=JobStatus.SUSPENDED,\\n        human_request=pending,\\n    )\\n\\n\\nasync def _resume_flow(\\n    flow_id: UUID,\\n    task_id: str,\\n    text: str,\\n    request_host: str | None = None,\\n    admitted_user_id: str | None = None,\\n) -> WorkflowExecutionResponse:\\n    \\\"\\\"\\\"Resume a HITL run that paused for human input, advancing to the next pause or completion.\\n\\n    The A2A task id is the run id, so the parked checkpoint is loaded by it. The follow-up\\n    message text becomes the HumanInput decision; the restored graph re-runs from the paused\\n    node and either completes (checkpoint cleared) or pauses again (a new checkpoint, another\\n    ``input-required``). Built on lfx checkpoint primitives so it is portable to lfx serve.\\n\\n    A reply that matches no offered action re-parks the task (the human can answer again) rather\\n    than burning it on an empty completion. The checkpoint is dropped on completion or failure,\\n    but a never-answered task keeps its row (no background reaper on this path yet).\\n    \\\"\\\"\\\"\\n    store = A2ACheckpointStore()\\n    checkpoint = await store.load_by_run_id(task_id)\\n    if checkpoint is None:\\n        # The parked run is unrecoverable (cleared/expired); surface a failed task.\\n        msg = f\\\"No resumable checkpoint for A2A task {task_id}\\\"\\n        raise RuntimeError(msg)\\n    # Defense in depth: a task parked under one flow must not be resumable via another flow's\\n    # endpoint (which would run a different owner's graph). Don't delete it on mismatch.\\n    if checkpoint.flow_id != str(flow_id):\\n        msg = f\\\"A2A task {task_id} does not belong to flow {flow_id}\\\"\\n        raise RuntimeError(msg)\\n    checkpoint, provider_policy_flow, provider_policy_user = await _prepare_a2a_resume_checkpoint(\\n        flow_id,\\n        checkpoint,\\n        request_host,\\n        admitted_user_id,\\n    )\\n\\n    pending = (checkpoint.pause_context or {}).get(\\\"data\\\") or {}\\n    allowed = pending.get(\\\"allowed_decisions\\\") or []\\n    action_id = _resolve_action(text, pending)\\n    if allowed and action_id is None:\\n        # Out-of-range answer: re-park so the human can retry, keeping the checkpoint.\\n        return _suspended_response(flow_id, task_id, checkpoint.session_id, pending)\\n\\n    decision = {\\\"action_id\\\": action_id or text.strip().lower().replace(\\\" \\\", \\\"_\\\"), \\\"values\\\": {}}\\n    # Lazy HITL timeout: if the pause elapsed, a late answer must not take the picked branch. Reroute\\n    # to the fallback/expired path exactly like the CLI resume loop and the background build do. No-op\\n    # when the node defined no timeout.\\n    decision = reroute_decision_on_timeout(pending, decision)\\n    # Shared HITL resume seam (restore + inject decision + un-build the paused vertex), so this path\\n    # can't drift from the CLI resume loop; see lfx.run.hitl.resume_graph_with_decision.\\n    graph = resume_graph_with_decision(checkpoint, store, pending.get(\\\"request_id\\\"), decision)\\n\\n    from langflow.api.v2.workflow_execution import _resolve_execution_timeout\\n    from langflow.processing.process import run_graph_internal\\n\\n    # Atomic claim before executing: exactly one caller may run a given parked task's approved branch.\\n    # Two workers handling a duplicated message/send both loaded and rebuilt the graph above (both\\n    # side-effect-free); the DELETE picks the single winner, and a loser bails before run_graph_internal\\n    # so the gated action can't fire twice (the SDK's task lock is per-process, not cross-worker). Claim\\n    # here, not before the build, so a build failure leaves the checkpoint recoverable. A re-pause saves\\n    # a fresh checkpoint under this run_id.\\n    if not await store.claim_by_run_id(task_id):\\n        # A concurrent duplicate resume already claimed this task. Signal the executor to bail\\n        # quietly rather than emitting a terminal FAILED that could mask the winner's completion.\\n        msg = f\\\"A2A task {task_id} is already being resumed\\\"\\n        raise ResumeConflictError(msg)\\n\\n    try:\\n        # No flow_execution_span here: run_graph_internal reaches Graph.arun, which opens one.\\n        with (\\n            scoped_model_provider_policy_for_flow(\\n                provider_policy_flow,\\n                user_id=provider_policy_user.id,\\n                is_superuser=bool(getattr(provider_policy_user, \\\"is_superuser\\\", False)),\\n            ),\\n            execution_protocol(\\\"a2a\\\"),\\n        ):\\n            run_outputs, session_id = await asyncio.wait_for(\\n                run_graph_internal(\\n                    graph,\\n                    str(flow_id),\\n                    session_id=graph.session_id,\\n                    inputs=[],\\n                    outputs=graph.get_terminal_nodes(),\\n                ),\\n                timeout=_resolve_execution_timeout(),\\n            )\\n    except GraphPausedException as exc:\\n        # Paused again (multi-step HITL): the new checkpoint is already saved under this run_id.\\n        return _suspended_response(flow_id, task_id, graph.session_id, exc.data or {})\\n    except Exception:\\n        # Failure/timeout: drop the now-unusable checkpoint so it doesn't orphan a terminal task.\\n        await store.delete_by_run_id(task_id)\\n        raise\\n\\n    await store.delete_by_run_id(task_id)\\n    from langflow.api.v1.schemas import RunResponse\\n\\n    run_response = RunResponse(outputs=run_outputs, session_id=session_id)\\n    return run_response_to_workflow_response(\\n        run_response=run_response,\\n        flow_id=str(flow_id),\\n        job_id=task_id,\\n        inputs={},\\n        graph=graph,\\n    )\\n\\n\\ndef _admitted_principal_scope(context: ServerCallContext) -> str:\\n    \\\"\\\"\\\"Return the immutable server-admitted principal for a mounted A2A request.\\\"\\\"\\\"\\n    state = getattr(context, \\\"state\\\", None) or {}\\n    admitted_user_id = state.get(\\\"admitted_user_id\\\")\\n    if admitted_user_id is not None:\\n        return str(admitted_user_id)\\n    if state.get(\\\"flow_id\\\"):\\n        msg = \\\"A2A request context is missing its admitted principal\\\"\\n        raise RuntimeError(msg)\\n    # Protocol-store unit uses without a mounted flow retain the SDK's native\\n    # owner resolver; real per-flow HTTP requests always take the branch above.\\n    return resolve_user_scope(context)\\n\\n\\ndef _push_config_scope(context: ServerCallContext) -> str:\\n    \\\"\\\"\\\"Key push configs by (admitted principal, flow) across auth-mode transitions.\\n\\n    Both values come from server-authenticated call-context state. Only the\\n    user-callable set/get/list/delete paths are scoped; dispatch fans out by\\n    task_id via ``get_info_for_dispatch`` and is unaffected.\\n    \\\"\\\"\\\"\\n    return f\\\"{_admitted_principal_scope(context)}:{context.state.get('flow_id', '')}\\\"\\n\\n\\nclass _SafePushConfigStore(InMemoryPushNotificationConfigStore):\\n    \\\"\\\"\\\"Push-notification config store that SSRF-guards the webhook URL at registration.\\n\\n    The webhook target is caller-controlled on a public endpoint, so reject one that\\n    resolves to a private/loopback/link-local address before storing it (rather than\\n    letting the sender POST there). In-memory + per-worker for now; durable cross-worker\\n    push configs are a later slice (like the streaming queue manager).\\n    \\\"\\\"\\\"\\n\\n    async def set_info(self, task_id: str, notification_config: pb.TaskPushNotificationConfig, context) -> None:\\n        try:\\n            await validate_webhook_url(notification_config.url)\\n        except ValueError as exc:\\n            raise InvalidParamsError(message=str(exc)) from exc\\n        await super().set_info(task_id, notification_config, context)\\n\\n\\nclass _SafePushNotificationSender(BasePushNotificationSender):\\n    \\\"\\\"\\\"Re-validate + DNS-pin the webhook at dispatch, closing the registration-time rebind gap.\\n\\n    ``_SafePushConfigStore`` validates at registration, but a host can re-resolve to a\\n    private/metadata IP afterwards (DNS rebinding). Re-resolve here and pin the connection\\n    to the just-validated IPs (via the shared SSRF transport) so a rebind can't land on an\\n    internal address. A webhook that now resolves to a blocked address is dropped (logged),\\n    matching the SDK's swallow-and-return-False on a failed send.\\n    \\\"\\\"\\\"\\n\\n    async def _dispatch_notification(self, event, push_info, task_id) -> bool:\\n        url = push_info.url\\n        try:\\n            validated_ips = await validate_webhook_url(url)\\n        except ValueError:\\n            logger.warning(\\\"A2A push webhook for task %s blocked by SSRF check: %s\\\", task_id, url)\\n            return False\\n        # Pin by the exact host httpx connects to (IDNA/punycode raw_host) -- the same\\n        # derivation validate_webhook_url resolved -- so the pin key can't diverge from the\\n        # connected host for an IDN webhook (which would silently bypass the pin).\\n        hostname = webhook_pin_host(url)\\n        if not (validated_ips and hostname):\\n            # Private webhooks allowed / allowlisted host / protection off: nothing to pin.\\n            return await super()._dispatch_notification(event, push_info, task_id)\\n        # ponytail: per-dispatch client so DNS is pinned to the IPs just validated for this\\n        # host; reuse the SDK's exact POST (token header, error swallow) via a bound sender.\\n        async with create_ssrf_protected_client(\\n            hostname=hostname, validated_ips=validated_ips, timeout=_PUSH_TIMEOUT\\n        ) as client:\\n            pinned = BasePushNotificationSender(client, self._config_store)\\n            return await pinned._dispatch_notification(event, push_info, task_id)  # noqa: SLF001\\n\\n\\nclass A2ACheckpointStore(CheckpointStore):\\n    \\\"\\\"\\\"DB-backed graph checkpoint store for A2A HITL resume, keyed by ``run_id`` (the task id).\\n\\n    The graph saves a checkpoint here when a HumanInput node pauses; resume reads it back by\\n    run id. ``GraphCheckpoint`` round-trips through JSON, so it lives in one ``a2a_checkpoints``\\n    row. Only ``save`` / ``load_by_run_id`` / ``delete_by_run_id`` are used; the id/session\\n    lookups would scan the table and aren't on any A2A path, so they raise. lfx-portable:\\n    ``session_scope`` + one SQLModel table, no langflow job machinery.\\n    \\\"\\\"\\\"\\n\\n    async def save(self, checkpoint: GraphCheckpoint) -> None:\\n        blob: dict[str, Any] = checkpoint.model_dump(mode=\\\"json\\\")\\n        async with session_scope() as session:\\n            row = await session.get(A2ACheckpoint, checkpoint.run_id)\\n            if row is None:\\n                session.add(A2ACheckpoint(run_id=checkpoint.run_id, checkpoint=blob))\\n            else:\\n                row.checkpoint = blob  # fresh dict reference flags the JSON column dirty\\n\\n    async def load_by_run_id(self, run_id: str) -> GraphCheckpoint | None:\\n        async with session_scope_readonly() as session:  # pure read, no commit\\n            row = await session.get(A2ACheckpoint, run_id)\\n            blob = row.checkpoint if row is not None else None\\n        return GraphCheckpoint.model_validate(blob) if blob is not None else None\\n\\n    async def delete_by_run_id(self, run_id: str) -> None:\\n        async with session_scope() as session:\\n            row = await session.get(A2ACheckpoint, run_id)\\n            if row is not None:\\n                await session.delete(row)\\n\\n    async def claim_by_run_id(self, run_id: str) -> bool:\\n        \\\"\\\"\\\"Atomically claim the parked checkpoint so exactly one caller may resume the task.\\n\\n        A single conditional ``DELETE ... WHERE run_id = ?`` (not the read-then-delete of\\n        ``delete_by_run_id``): two workers handling a duplicated ``message/send`` both loaded this\\n        checkpoint, but only the one whose DELETE removes the row (rowcount 1) wins and runs the\\n        approved branch; the loser backs off, so the gated action can't fire twice. Atomic on both\\n        SQLite (writer-serialized) and Postgres (row lock), unlike ``SELECT ... FOR UPDATE`` which is\\n        a no-op on SQLite.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            result = await session.execute(delete(A2ACheckpoint).where(A2ACheckpoint.run_id == run_id))\\n            return (result.rowcount or 0) == 1\\n\\n    async def load(self, checkpoint_id: str) -> GraphCheckpoint | None:\\n        # A2A resolves by run_id (== task id); a by-checkpoint-id lookup isn't mounted.\\n        raise NotImplementedError\\n\\n    async def delete(self, checkpoint_id: str) -> None:\\n        raise NotImplementedError\\n\\n    async def list_by_session(self, session_id: str) -> list[GraphCheckpoint]:\\n        raise NotImplementedError\\n\\n\\n# MessageToDict serializes the enum by name, so a stored blob's state is e.g. \\\"TASK_STATE_CANCELED\\\".\\n_TERMINAL_STATE_NAMES = {pb.TaskState.Name(state) for state in TERMINAL_TASK_STATES}\\n\\n\\ndef _task_state(blob: dict[str, Any] | None) -> str | None:\\n    \\\"\\\"\\\"The stored task blob's state (MessageToDict enum name, e.g. ``TASK_STATE_CANCELED``), or None.\\\"\\\"\\\"\\n    return (blob.get(\\\"status\\\") or {}).get(\\\"state\\\") if blob else None\\n\\n\\ndef _task_scope(context: ServerCallContext) -> str:\\n    \\\"\\\"\\\"Principal key for the durable task store, scoped to the flow.\\n\\n    Folding both the canonical path ``flow_id`` and immutable HTTP-gate principal\\n    into the key prevents cross-flow and protected/public transition access. Falls\\n    back to the SDK owner scope only for protocol-store use without a mounted flow.\\n\\n    Delimited by ':' like ``_push_config_scope``: the flow_id prefix is a UUID (no ':'), so the key\\n    is unambiguous, and it avoids a NUL byte that Postgres text columns reject at write time.\\n    \\\"\\\"\\\"\\n    owner = _admitted_principal_scope(context)\\n    flow_id = (getattr(context, \\\"state\\\", None) or {}).get(\\\"flow_id\\\")\\n    return f\\\"{flow_id}:{owner}\\\" if flow_id else owner\\n\\n\\ndef _legacy_public_task_scope(context: ServerCallContext) -> str | None:\\n    \\\"\\\"\\\"Return the pre-public-principal task scope for anonymous mounted requests.\\n\\n    Before public A2A requests received a stable admitted principal, their SDK\\n    owner scope was empty and durable rows were stored as ``<flow_id>:``. Keep\\n    that read-only compatibility path restricted to the same flow and the\\n    anonymous public principal; protected callers must never inherit it.\\n    \\\"\\\"\\\"\\n    state = getattr(context, \\\"state\\\", None) or {}\\n    flow_id = state.get(\\\"flow_id\\\")\\n    if flow_id and _admitted_principal_scope(context) == str(PUBLIC_ANONYMOUS_ACTOR_ID):\\n        return f\\\"{flow_id}:\\\"\\n    return None\\n\\n\\nclass DurableTaskStore(TaskStore):\\n    \\\"\\\"\\\"DB-backed A2A task store keyed by ``(task_id, admitted principal + flow)``.\\n\\n    One short session per op, so tasks survive a restart and are shared across workers\\n    (unlike the SDK in-memory store). The whole proto Task is stored as one JSON blob\\n    since the mounted surface only does point lookups by id.\\n    \\\"\\\"\\\"\\n\\n    async def save(self, task: pb.Task, context: ServerCallContext) -> None:\\n        owner = _task_scope(context)\\n        blob: dict[str, Any] = MessageToDict(task)\\n        async with session_scope() as session:\\n            # Lock the row so a completion racing a cancel can't read stale state and then clobber\\n            # the terminal state (Postgres row lock; a no-op on SQLite, which serializes writers).\\n            row = await session.get(A2ATask, (task.id, owner), with_for_update=True)\\n            existing_state = _task_state(row.task) if row is not None else None\\n            if row is None:\\n                session.add(A2ATask(id=task.id, owner=owner, task=blob))\\n            elif existing_state in _TERMINAL_STATE_NAMES and _task_state(blob) != existing_state:\\n                # Terminal is final: once a task reaches a terminal state, a later save carrying a\\n                # different state must not transition it. Covers both race orders of a cancel against\\n                # a completion (a forced CANCELED arriving after COMPLETED persisted, or a late\\n                # completion arriving after CANCELED). The state that landed first wins.\\n                return\\n            else:\\n                row.task = blob  # fresh dict reference flags the JSON column dirty\\n\\n    async def get(self, task_id: str, context: ServerCallContext) -> pb.Task | None:\\n        owner = _task_scope(context)\\n        async with session_scope_readonly() as session:  # pure read, no commit\\n            row = await session.get(A2ATask, (task_id, owner))\\n            if row is None:\\n                legacy_public_owner = _legacy_public_task_scope(context)\\n                if legacy_public_owner is not None:\\n                    row = await session.get(A2ATask, (task_id, legacy_public_owner))\\n            blob = row.task if row is not None else None\\n        if blob is None:\\n            return None\\n        task = pb.Task()\\n        ParseDict(blob, task)\\n        return task\\n\\n    async def list(self, params: pb.ListTasksRequest, context: ServerCallContext) -> pb.ListTasksResponse:\\n        # ponytail: tasks/list isn't routed this slice; implement it (and decompose\\n        # context_id/status into columns) when F5/F7 mount a list/filter path.\\n        raise NotImplementedError\\n\\n    async def delete(self, task_id: str, context: ServerCallContext) -> None:\\n        # ponytail: no mounted path calls delete this slice.\\n        raise NotImplementedError\\n\\n\\n# Shared durable task store: read/written by the SDK handler and by _DurableCancelHandler, which\\n# forces a terminal CANCELED into it so tasks/cancel works for parked tasks and can't be lost to an\\n# event-queue close.\\n_TASK_STORE = DurableTaskStore()\\n\\n\\nclass _DurableCancelHandler(DefaultRequestHandler):\\n    \\\"\\\"\\\"Make tasks/cancel terminal, including for parked tasks the SDK won't touch.\\n\\n    The V2 handler only preempts a *live* producer (ActiveTask.cancel no-ops once the producer has\\n    finished), so cancelling a parked input-required task returns it unchanged, and cancelling a live\\n    run whose queue closed can leave it stuck 'working'. After delegating (which still preempts a live\\n    producer same-worker), force CANCELED into the returned task and the durable store so the state is\\n    terminal for both cases. A run on another worker still can't be preempted (LE-1699).\\n    \\\"\\\"\\\"\\n\\n    async def on_cancel_task(self, params, context: ServerCallContext):\\n        # The in-memory ActiveTaskRegistry is keyed by task id only, not flow, so without this a\\n        # cancel could reach a task created under a different flow's endpoint. Gate on the\\n        # flow-scoped store: a task this flow can't see is \\\"not found\\\" here (and we never reveal\\n        # that it exists under another flow).\\n        if await _TASK_STORE.get(params.id, context) is None:\\n            raise TaskNotFoundError\\n        task = await super().on_cancel_task(params, context)\\n        if task is None:\\n            return None\\n        # Terminal but not CANCELED: the run actually finished (a registry-resident task in the\\n        # async-cleanup window, or one a stream subscriber still pins) and the SDK returned it\\n        # terminal-but-uncanceled instead of raising. Match the SDK's cold path and refuse, rather\\n        # than clobbering a real COMPLETED/FAILED with CANCELED in the store.\\n        if task.status.state in TERMINAL_TASK_STATES and task.status.state != pb.TaskState.TASK_STATE_CANCELED:\\n            raise TaskNotCancelableError\\n        # Not yet CANCELED (the SDK left a parked task unchanged): force terminal CANCELED into the\\n        # returned task and the durable store.\\n        if task.status.state != pb.TaskState.TASK_STATE_CANCELED:\\n            task.status.state = pb.TaskState.TASK_STATE_CANCELED\\n            await _TASK_STORE.save(task, context)\\n        # The task is now CANCELED (whether the SDK cancelled a live/parked producer or we forced it).\\n        # Drop any HITL checkpoint: it is keyed by task id and is the cross-worker resume gate, so\\n        # without this a follow-up message routed to a worker whose in-memory task still looks parked\\n        # would reload it and resume a cancelled run. delete_by_run_id is a no-op with no checkpoint.\\n        await A2ACheckpointStore().delete_by_run_id(params.id)\\n        return task\\n\\n    async def on_subscribe_to_task(self, params, context: ServerCallContext):\\n        # Reattach to a still-streaming run, but only when there is genuinely a live producer to tail\\n        # in THIS worker. Two gates, both required:\\n        #   1. Flow-scoped store: a task this flow can't see is \\\"not found\\\" (same as on_cancel_task);\\n        #      never reveal that it exists under another flow, and keep the store off the delegate path.\\n        #   2. Live producer: the SDK's subscribe() taps the task's event queue and waits, so for a\\n        #      parked (input-required), terminal, or run-on-another-worker task it blocks forever and\\n        #      leaks an ActiveTask. Require both a WORKING durable state and a live registry entry\\n        #      before delegating; otherwise return the spec error and let tasks/get read it back.\\n        stored = await _TASK_STORE.get(params.id, context)\\n        if stored is None:\\n            raise TaskNotFoundError\\n        active = await self._active_task_registry.get(params.id)\\n        if stored.status.state != pb.TaskState.TASK_STATE_WORKING or active is None:\\n            msg = f\\\"Task {params.id} has no active stream to resubscribe to\\\"\\n            raise UnsupportedOperationError(message=msg)\\n        async for event in super().on_subscribe_to_task(params, context):\\n            yield event\\n\\n\\n# One shared httpx client sends webhooks; a short timeout so a slow/hostile webhook\\n# can't tie up the run. Created at import (no I/O) and reused across requests; closed\\n# from the app lifespan via close_push_client(). The sender re-validates and DNS-pins\\n# each webhook at dispatch (per-dispatch client), so this shared client only carries\\n# the no-pin path (private webhooks allowed / allowlisted host / SSRF protection off).\\n_PUSH_TIMEOUT = 10.0\\n_PUSH_HTTP_CLIENT = httpx.AsyncClient(timeout=_PUSH_TIMEOUT)\\n_PUSH_CONFIG_STORE = _SafePushConfigStore(owner_resolver=_push_config_scope)\\n_PUSH_SENDER = _SafePushNotificationSender(_PUSH_HTTP_CLIENT, _PUSH_CONFIG_STORE)\\n\\n\\nasync def close_push_client() -> None:\\n    \\\"\\\"\\\"Close the shared push-notification webhook client. Wired into the app lifespan.\\\"\\\"\\\"\\n    await _PUSH_HTTP_CLIENT.aclose()\\n\\n\\n# One shared handler/store/dispatcher serve every flow; the per-request flow_id\\n# selects the flow. The handler card carries only capabilities the SDK reads to gate\\n# methods: streaming=True admits message/stream + tasks/resubscribe; push_notifications=True\\n# admits the tasks/pushNotificationConfig methods. The real per-flow discovery card is the\\n# GET route. The stores do no DB work at construction, so the import-time singletons are safe.\\n# ponytail: streaming emits the run's lifecycle events (submitted -> working ->\\n# artifact -> completed) as SSE; per-token deltas would inject a stream_flow callable\\n# into the executor. tasks/resubscribe is best-effort same-worker live re-attach (the\\n# default in-memory QueueManager); a terminal or cross-worker task returns a spec error\\n# and tasks/get covers terminal reads. Push configs are in-memory per-worker; durable\\n# cross-worker re-attach and push delivery are a later slice.\\n_HANDLER = _DurableCancelHandler(\\n    agent_executor=FlowAgentExecutor(_run_flow, _resume_flow),\\n    task_store=_TASK_STORE,\\n    agent_card=pb.AgentCard(capabilities=pb.AgentCapabilities(streaming=True, push_notifications=True)),\\n    push_config_store=_PUSH_CONFIG_STORE,\\n    push_sender=_PUSH_SENDER,\\n)\\n\\n\\nclass _SpecErrorAdapter(JSONRPC03Adapter):\\n    \\\"\\\"\\\"Preserve spec JSON-RPC error codes on the v0.3 compat surface.\\n\\n    The base adapter's ``handle_request`` has a catch-all that wraps every exception in\\n    ``InternalError`` (-32603), so a deliberately-raised ``A2AError`` (``TaskNotFoundError`` -32001,\\n    ``TaskNotCancelableError`` -32002, ``UnsupportedOperationError`` -32004, ``InvalidParamsError``\\n    -32602) reaches the wire as a generic internal error and a conforming client can't distinguish\\n    \\\"no such task\\\" from \\\"the agent broke\\\". Catch ``A2AError`` in the non-streaming path and map it\\n    through the SDK's own ``JSON_RPC_ERROR_CODE_MAP`` before the catch-all sees it. Unknown\\n    ``A2AError`` subclasses fall through to the base -32603. The streaming path (``message/stream`` /\\n    ``tasks/resubscribe``) still collapses its error frame to -32603 in the SDK's stream generator;\\n    fixing that means reimplementing that generator, tracked separately.\\n    \\\"\\\"\\\"\\n\\n    async def _process_non_streaming_request(self, request_id, request_obj, context):\\n        try:\\n            return await super()._process_non_streaming_request(request_id, request_obj, context)\\n        except A2AError as exc:\\n            code = _A2A_ERROR_CODES.get(type(exc))\\n            if code is None:\\n                raise  # unknown A2AError: let the base catch-all map it to -32603\\n            return self._generate_error_response(\\n                request_id, CoreJSONRPCError(code=code, message=str(exc) or type(exc).__name__)\\n            )\\n\\n\\n_DISPATCHER = JsonRpcDispatcher(\\n    request_handler=_HANDLER,\\n    context_builder=_FlowContextBuilder(),\\n    # routes spec method names: message/send, message/stream, tasks/get, tasks/cancel,\\n    # tasks/resubscribe, tasks/pushNotificationConfig/{set,get,list,delete}\\n    enable_v0_3_compat=True,\\n)\\n# enable_v0_3_compat builds the compat adapter internally with no injection hook, so re-tag the\\n# built instance to preserve spec error codes (keeps its constructed handler/context state intact).\\nif _DISPATCHER._v03_adapter is not None:  # noqa: SLF001 - no public accessor for the compat adapter\\n    _DISPATCHER._v03_adapter.__class__ = _SpecErrorAdapter  # noqa: SLF001\\n\\n\\n# The flag guard is a route dependency so it runs BEFORE the CurrentActiveUser auth dependency\\n# (FastAPI resolves decorator dependencies first): a disabled route must look unmounted (404) to an\\n# anonymous caller, not leak a 403 from auth resolving ahead of an in-body flag check.\\n@router.get(\\\"/agents\\\", dependencies=[Depends(_require_a2a_enabled)])\\nasync def list_a2a_agents(request: Request, session: DbSession, current_user: CurrentActiveUser) -> list[dict]:\\n    \\\"\\\"\\\"List the caller's own A2A-published agent flows, each with its agent-card URL.\\n\\n    Authenticated and owner-scoped, mirroring the MCP-projects catalog: a public cross-user\\n    directory would strip the per-flow card's unguessable-id obscurity and expose other users'\\n    agents, so this enumerates only the calling user's agents. Each ``cardUrl`` is the public\\n    discovery entry point an orchestrator fetches per agent.\\n    \\\"\\\"\\\"\\n    base = str(request.base_url).rstrip(\\\"/\\\")\\n    owned_clause = Flow.user_id == current_user.id\\n    visibility = await visible_scope_prefilter(current_user, resource_type=\\\"flow\\\", act=FlowAction.READ)\\n    if visibility is not None:\\n        canonical_workspace = case(\\n            (col(Flow.folder_id).is_not(None), Folder.workspace_id),\\n            else_=Flow.workspace_id,\\n        )\\n        stmt = restrict_to_owned_or_visible_scope(\\n            select(Flow).outerjoin(Folder, Folder.id == Flow.folder_id),\\n            id_column=Flow.id,\\n            owner_clause=owned_clause if await should_apply_owner_override() else false(),\\n            workspace_expression=canonical_workspace,\\n            project_column=Flow.folder_id,\\n            visibility=visibility,\\n        )\\n    else:\\n        stmt = select(Flow).where(owned_clause)\\n    flows = (await session.exec(stmt.where(Flow.flow_type == FlowType.AGENT))).all()\\n    if visibility is None:\\n        flows = await filter_visible_resources(\\n            current_user,\\n            resource_type=\\\"flow\\\",\\n            candidates=list(flows),\\n            domain_extractor=lambda flow: _resolve_authz_domain(flow.workspace_id, flow.folder_id),\\n            owner_extractor=lambda flow: flow.user_id,\\n            act=FlowAction.READ,\\n        )\\n    # a2a_enabled is bool|None; filter truthiness in Python, matching the card route's gate.\\n    return [\\n        {\\n            \\\"id\\\": str(flow.id),\\n            \\\"name\\\": flow.name,\\n            \\\"description\\\": flow.description,\\n            \\\"cardUrl\\\": f\\\"{base}/api/v1/a2a/{flow.id}/.well-known/agent-card.json\\\",\\n        }\\n        for flow in flows\\n        if flow.a2a_enabled\\n    ]\\n\\n\\n@router.get(\\\"/{flow_id}/.well-known/agent-card.json\\\")\\nasync def get_agent_card(flow_id: UUID, request: Request, session: DbSession) -> dict:\\n    \\\"\\\"\\\"Serve the spec-valid A2A agent card for an agent-typed, a2a_enabled flow.\\n\\n    Public by design: the A2A public agent card is unauthenticated by spec, so\\n    gating it behind login would break standard discovery. Returns 404 when the\\n    flag is off, the flow does not exist, the flow is not flow_type=agent, or\\n    a2a_enabled is falsy.\\n    \\\"\\\"\\\"\\n    _require_a2a_enabled()\\n\\n    flow = (await session.exec(select(Flow).where(Flow.id == flow_id))).first()\\n    if flow is None or flow.flow_type != FlowType.AGENT or not flow.a2a_enabled:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\")\\n    if await folder_auth_type(flow, session) == \\\"none\\\":\\n        try:\\n            await authorize_public_flow_access(\\n                flow=flow,\\n                action=PublicResourceAction.READ,\\n                request_host=request.url.hostname,\\n                compatibility_grant=PublicGrantSource.A2A_AUTH_NONE,\\n                session=session,\\n            )\\n        except HTTPException as exc:\\n            if exc.status_code == status.HTTP_404_NOT_FOUND:\\n                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\") from exc\\n            raise\\n\\n    rpc_url = str(request.base_url).rstrip(\\\"/\\\") + f\\\"/api/v1/a2a/{flow_id}/jsonrpc\\\"\\n    return await build_agent_card(flow, rpc_url=rpc_url, session=session)\\n\\n\\n@router.post(\\\"/{flow_id}/jsonrpc\\\")\\nasync def a2a_jsonrpc(flow_id: UUID, request: Request) -> Response:\\n    \\\"\\\"\\\"Serve the A2A JSON-RPC surface (message/send, message/stream, tasks/get, tasks/resubscribe) for an agent flow.\\n\\n    Gated like the card route; apikey-folder flows additionally require a valid owner\\n    key (401). The flow runs as its owner. Returns the SDK's JSON-RPC response (HTTP 200\\n    even for JSON-RPC-level errors). No ``DbSession`` dependency here: holding a session\\n    open across the run would fight the v2 surface's lock-avoidance design, and the\\n    gate/run resolve from flow_id via short self-managed sessions.\\n    \\\"\\\"\\\"\\n    _require_a2a_enabled()\\n\\n    try:\\n        # Gate on the flow itself (resolve by PK, owner-agnostic), like the card\\n        # route. _run_flow resolves the principal for the actual run.\\n        flow = await get_flow_by_id_or_endpoint_name(str(flow_id))\\n        if flow.flow_type != FlowType.AGENT or not flow.a2a_enabled:\\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\")\\n\\n        # apikey-folder flows require a valid owner key here (401); \\\"none\\\" stays\\n        # public. Runs after the 404 gate, so disabled/non-agent/unknown flows\\n        # never reach a 401.\\n        admitted_user = await _enforce_a2a_auth(flow, request)\\n    except HTTPException as exc:\\n        if exc.status_code == status.HTTP_404_NOT_FOUND:\\n            # Unknown, unpublished, revoked, plugin-denied, and existing but\\n            # non-agent flows must have the exact same transport response.\\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Not Found\\\") from exc\\n        raise\\n    request.state.a2a_admitted_user_id = str(\\n        admitted_user.id if admitted_user is not None else PUBLIC_ANONYMOUS_ACTOR_ID\\n    )\\n\\n    return await _DISPATCHER.handle_requests(request)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/a2a_executor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"46ec03ecec09f5891156149340abbec867f27161bf190a5a41134f4a3d8d6fe9\",\"content\":\"\\\"\\\"\\\"Protocol-pure A2A AgentExecutor for Langflow flows.\\n\\nDeliberately free of langflow imports (only the a2a SDK, ``lfx.schema.workflow``,\\nand stdlib) so it can move to lfx when the A2A protocol layer is extracted. The\\nlangflow-bound seam (flow lookup, v2 execution, gating) lives in ``a2a.py`` and\\nis injected as the ``run_flow`` callable.\\n\\nThe a2a-sdk 1.x server stack is protobuf-based (``a2a.types.a2a_pb2``); the\\nspec-name methods ``message/send`` / ``tasks/get`` reach it through the v0.3\\ncompat adapter wired up in ``a2a.py``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nimport logging\\nfrom collections.abc import Awaitable, Callable\\nfrom uuid import UUID\\n\\nfrom a2a.helpers.proto_helpers import get_data_parts, new_data_part, new_text_part\\nfrom a2a.server.agent_execution import AgentExecutor, RequestContext\\nfrom a2a.server.events import EventQueue\\nfrom a2a.server.tasks import TaskUpdater\\nfrom a2a.types import a2a_pb2 as pb\\nfrom lfx.schema.workflow import JobStatus, OutputReason, WorkflowExecutionResponse\\n\\nlogger = logging.getLogger(__name__)\\n\\n\\nclass ResumeConflictError(RuntimeError):\\n    \\\"\\\"\\\"A duplicate HITL resume lost the atomic checkpoint claim.\\n\\n    The worker that won the claim owns the task's terminal state, so the loser must bail without\\n    emitting a terminal event: a FAILED here would race the winner's COMPLETED and could\\n    permanently mask it. Raised by the injected ``resume_flow`` seam, caught in ``execute``.\\n    \\\"\\\"\\\"\\n\\n\\n# (flow_id, task_id, input_text, context_id, request_host, admitted_user_id) -> the v2 sync run result.\\n# context_id scopes the run's chat memory (the A2A conversation = the flow session).\\nRunFlow = Callable[[UUID, str, str, str | None, str | None, str | None], Awaitable[WorkflowExecutionResponse]]\\n# (flow_id, task_id, decision_text, request_host, admitted_user_id) -> the run result after\\n# applying a human decision to a paused task. The final fields preserve the original HTTP gate.\\nResumeFlow = Callable[[UUID, str, str, str | None, str | None], Awaitable[WorkflowExecutionResponse]]\\n\\n\\ndef _json_safe(content: object) -> object:\\n    \\\"\\\"\\\"Coerce a data-output payload to a JSON-native value for ``new_data_part``.\\n\\n    ``new_data_part`` serializes via ``ParseDict`` into a protobuf ``Value``, which rejects\\n    non-JSON-native values (datetime, UUID, a pydantic model such as lfx ``OutputValue``). Round-trip\\n    through json, dumping pydantic models and str-ifying anything else, so a data-typed flow output\\n    can't raise a ParseError mid-artifact and leave the task with no terminal event.\\n    \\\"\\\"\\\"\\n\\n    def _default(obj: object) -> object:\\n        dump = getattr(obj, \\\"model_dump\\\", None)\\n        return dump(mode=\\\"json\\\") if callable(dump) else str(obj)\\n\\n    return json.loads(json.dumps(content, default=_default))\\n\\n\\ndef _answer_parts(response: WorkflowExecutionResponse) -> list[pb.Part]:\\n    \\\"\\\"\\\"The run's answer as A2A artifact parts: text for string channels, data for the rest.\\n\\n    SINGLE is the canonical agent shape (one ChatOutput); preserve its text, including an\\n    intentional \\\"\\\". Otherwise read each ``outputs`` channel: a string message/text becomes a\\n    text part, and anything else that carries content (a ``data``-typed output, or a non-string\\n    payload) becomes an ``application/json`` data part, so a structured / data-only flow emits\\n    its JSON instead of being silently dropped to an empty text answer. The card already\\n    advertises ``application/json`` output, so this makes that contract real.\\n    \\\"\\\"\\\"\\n    if response.output.reason == OutputReason.SINGLE:\\n        return [new_text_part(response.output.text or \\\"\\\")]\\n    parts: list[pb.Part] = []\\n    for output in response.outputs.values():\\n        if output.content is None:\\n            continue\\n        if output.type in {\\\"message\\\", \\\"text\\\"} and isinstance(output.content, str):\\n            parts.append(new_text_part(output.content))\\n        else:\\n            parts.append(new_data_part(_json_safe(output.content), media_type=\\\"application/json\\\"))\\n    return parts\\n\\n\\nclass FlowAgentExecutor(AgentExecutor):\\n    \\\"\\\"\\\"Runs a Langflow flow for one A2A ``message/send`` and reports a terminal Task.\\\"\\\"\\\"\\n\\n    def __init__(self, run_flow: RunFlow, resume_flow: ResumeFlow) -> None:\\n        self._run_flow = run_flow\\n        self._resume_flow = resume_flow\\n\\n    async def execute(self, context: RequestContext, event_queue: EventQueue) -> None:\\n        flow_id = context.call_context.state[\\\"flow_id\\\"]\\n\\n        # A follow-up message on an input-required task resumes the paused run with the\\n        # message as the human decision; a first message starts a fresh run. The SDK only\\n        # routes a follow-up here when the existing (owner-scoped) task is non-terminal.\\n        existing = context.current_task\\n        resuming = existing is not None and existing.status.state == pb.TaskState.TASK_STATE_INPUT_REQUIRED\\n\\n        if not resuming:\\n            # DefaultRequestHandlerV2 rejects a status/artifact event before a Task\\n            # event (\\\"Agent should enqueue Task before TaskStatusUpdateEvent\\\"), and\\n            # this SDK version has no new_task helper, so enqueue the proto Task first.\\n            # On resume the Task already exists, so don't re-submit it.\\n            await event_queue.enqueue_event(\\n                pb.Task(\\n                    id=context.task_id,\\n                    context_id=context.context_id,\\n                    status=pb.TaskStatus(state=pb.TaskState.TASK_STATE_SUBMITTED),\\n                )\\n            )\\n        updater = TaskUpdater(event_queue, context.task_id, context.context_id)\\n        await updater.start_work()\\n\\n        text = context.get_user_input()\\n        if not text and context.message is not None:\\n            # A caller can send structured input as DataPart(s) with no text. The flow input is\\n            # a text channel, so serialize the data to JSON so it reaches the flow rather than\\n            # being dropped. Plain-text input is untouched (the common case).\\n            data = get_data_parts(context.message.parts)\\n            if data:\\n                text = json.dumps(data[0] if len(data) == 1 else data)\\n        try:\\n            if resuming:\\n                response = await self._resume_flow(\\n                    UUID(flow_id),\\n                    context.task_id,\\n                    text,\\n                    context.call_context.state.get(\\\"request_host\\\"),\\n                    context.call_context.state.get(\\\"admitted_user_id\\\"),\\n                )\\n            else:\\n                response = await self._run_flow(\\n                    UUID(flow_id),\\n                    context.task_id,\\n                    text,\\n                    context.context_id,\\n                    context.call_context.state.get(\\\"request_host\\\"),\\n                    context.call_context.state.get(\\\"admitted_user_id\\\"),\\n                )\\n        except asyncio.CancelledError:\\n            # tasks/cancel preempted this live run (the SDK cancels the producer task). Emit a\\n            # terminal CANCELED on this producer's OWN queue before it closes, so the original\\n            # message/send / message/stream consumer gets a terminal event instead of hanging on the\\n            # last 'working' state, then propagate the cancellation (never swallow it, or the task\\n            # won't wind down). The durable store is set to CANCELED by the request handler.\\n            with contextlib.suppress(Exception):\\n                await updater.cancel()\\n            raise\\n        except ResumeConflictError:\\n            # A duplicate resume lost the claim: the winning worker drives this task to its terminal\\n            # state. Emit nothing here so a stray FAILED can't race and mask the winner's completion.\\n            logger.info(\\\"A2A resume for task %s ceded to the worker that won the claim\\\", context.task_id)\\n            return\\n        except Exception:\\n            # Unexpected build/timeout/system failures become a failed Task, not a 500.\\n            # The endpoint is unauthenticated, so don't hand the caller raw exception\\n            # text (graph-build internals, DB errors); log it server-side instead.\\n            logger.exception(\\\"A2A flow execution failed for task %s\\\", context.task_id)\\n            await updater.failed(updater.new_agent_message([new_text_part(\\\"Flow execution failed\\\")]))\\n            return\\n\\n        # The run paused for human input: park the task as input-required carrying the prompt,\\n        # so a follow-up message resumes it. Not terminal, so the task stays open.\\n        if response.status == JobStatus.SUSPENDED:\\n            prompt = (response.human_request or {}).get(\\\"prompt\\\") or \\\"Input required\\\"\\n            await updater.requires_input(updater.new_agent_message([new_text_part(prompt)]))\\n            return\\n\\n        # Component/runtime errors come back in-band as a FAILED status, not raised.\\n        # ponytail: this in-band branch needs a flow that builds then errors at a\\n        # component to exercise; left to the suite's raised-failure coverage this slice.\\n        if response.status == JobStatus.FAILED or response.has_errors:\\n            # The endpoint is unauthenticated, so redact like the raised-exception branch above:\\n            # log the component error text server-side, hand the caller a generic message.\\n            detail = \\\"; \\\".join(error.error for error in response.errors) or \\\"Flow execution failed\\\"\\n            logger.error(\\\"A2A flow failed in-band for task %s: %s\\\", context.task_id, detail)\\n            await updater.failed(updater.new_agent_message([new_text_part(\\\"Flow execution failed\\\")]))\\n            return\\n\\n        # Emit the answer artifact and complete. This runs OUTSIDE the try above, and _answer_parts\\n        # serializes arbitrary flow output, so guard it: an unexpected serialization failure here\\n        # would escape execute() and leave the task with no terminal event (stuck 'working'). Downgrade\\n        # any such failure to a terminal 'failed' instead.\\n        try:\\n            parts = _answer_parts(response)\\n            await updater.add_artifact(parts or [new_text_part(\\\"\\\")], name=\\\"result\\\")\\n            await updater.complete()\\n        except Exception:\\n            logger.exception(\\\"A2A artifact emission failed for task %s\\\", context.task_id)\\n            await updater.failed(updater.new_agent_message([new_text_part(\\\"Flow execution failed\\\")]))\\n\\n    async def cancel(self, context: RequestContext, event_queue: EventQueue) -> None:\\n        # The durable terminal CANCELED is written by the request handler (see a2a.py); here we only\\n        # emit the terminal cancel event so a live message/stream subscriber sees it. Must not raise:\\n        # the SDK marks the task FAILED if agent cancel raises, so suppress a failed emit (e.g. an\\n        # already-closed queue). Only invoked for a live producer; a parked (finished) task's cancel\\n        # is handled entirely in the handler.\\n        with contextlib.suppress(Exception):\\n            await TaskUpdater(event_queue, context.task_id, context.context_id).cancel()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/a2a_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5e4c2bc4e6b65539aea49e6d1eb0dec326cb37d761893e709335a279625b1ed\",\"content\":\"\\\"\\\"\\\"Helpers for building spec-valid A2A agent cards from Langflow flows.\\n\\nThe typed models come from ``a2a.compat.v0_3.types`` (pydantic). Do NOT import\\nfrom ``a2a.types`` \u2014 in a2a-sdk 1.x those are protobuf messages that serialize\\nto a non-spec shape (no top-level ``url``, oneof-wrapped ``securitySchemes``,\\n``location`` instead of ``in``).\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nfrom urllib.parse import urlparse\\n\\nimport httpx\\nfrom a2a.compat.v0_3 import types as a2a_types\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError, is_ip_blocked, resolve_hostname, validate_and_resolve_url\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.helpers.flow import json_schema_from_flow\\nfrom langflow.services.database.models import Folder\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.utils.version import get_version_info\\n\\n# Scheme key advertised on the card and the header MCP already validates\\n# (see mcp_projects.py). The A2A card reflects this; F6 enforces it.\\nA2A_APIKEY_SCHEME_NAME = \\\"apiKey\\\"  # pragma: allowlist secret\\nA2A_APIKEY_HEADER = \\\"x-api-key\\\"  # pragma: allowlist secret\\n\\n# The A2A protocol version the server actually speaks: the JSON-RPC v0.3 surface served via the\\n# a2a-sdk compat layer (JsonRpcDispatcher(enable_v0_3_compat=True) in a2a.py). Set explicitly on\\n# the card instead of relying on the sdk's default, so an sdk bump can't silently change what we\\n# advertise. The latest spec is on the 1.x line, but we serve 0.3 today, so 0.3 is the truthful\\n# value; bump this when the server actually moves onto the 1.x protocol.\\nA2A_PROTOCOL_VERSION = \\\"0.3.0\\\"\\n\\n# Served when a flow's graph can't be built; the card stays valid, the input\\n# contract is just empty rather than 500ing the public discovery endpoint.\\n_EMPTY_INPUT_SCHEMA = {\\\"type\\\": \\\"object\\\", \\\"properties\\\": {}, \\\"required\\\": []}\\n\\n# Bound free-form a2a_card_overrides so they can't bloat the public,\\n# unauthenticated card (a single over-long string or an unbounded examples/tags\\n# list). Legitimate overrides are well under these.\\n_MAX_OVERRIDE_STR_LEN = 1000\\n_MAX_OVERRIDE_LIST_ITEMS = 50\\n\\n\\ndef _override_str(overrides: dict, key: str) -> str | None:\\n    \\\"\\\"\\\"Return a non-empty, length-bounded string override, or None.\\n\\n    a2a_card_overrides is a free-form dict, so a non-string value must not reach\\n    the typed card model (it would raise pydantic ValidationError). Over-long\\n    values are dropped so the card falls back to the flow default.\\n    \\\"\\\"\\\"\\n    value = overrides.get(key)\\n    if isinstance(value, str) and value and len(value) <= _MAX_OVERRIDE_STR_LEN:\\n        return value\\n    return None\\n\\n\\ndef _override_str_list(overrides: dict, key: str) -> list[str] | None:\\n    \\\"\\\"\\\"Return a non-empty list-of-strings override (count- and length-bounded), or None.\\\"\\\"\\\"\\n    value = overrides.get(key)\\n    if (\\n        isinstance(value, list)\\n        and value\\n        and all(isinstance(item, str) and len(item) <= _MAX_OVERRIDE_STR_LEN for item in value)\\n    ):\\n        return value[:_MAX_OVERRIDE_LIST_ITEMS]\\n    return None\\n\\n\\ndef webhook_pin_host(url: str) -> str:\\n    \\\"\\\"\\\"Return the host httpx/httpcore actually connects to (the IDNA/punycode ``raw_host``).\\n\\n    httpx connects using ``raw_host`` (e.g. ``xn--exmple-cua.com``), not the unicode\\n    ``urlparse().hostname`` (``ex\u00e4mple.com``). The DNS-pin key and the host we resolve must\\n    both be this exact representation, or for an internationalized webhook the pin key won't\\n    match the connected host and the pin is silently bypassed (TOCTOU rebind for IDN hosts).\\n    Single source of truth for both the resolve/validate step and the dispatch pin.\\n    \\\"\\\"\\\"\\n    return httpx.URL(url).raw_host.decode(\\\"ascii\\\")\\n\\n\\nasync def validate_webhook_url(url: str) -> list[str]:\\n    \\\"\\\"\\\"Validate a push-notification webhook URL (SSRF guard) and return IPs for DNS pinning.\\n\\n    The A2A endpoint is public, so the webhook target is caller-controlled. Require\\n    http/https, then enforce a hard IP floor that does NOT depend on the global\\n    ``LANGFLOW_SSRF_PROTECTION_ENABLED`` toggle (ops disable it for the API Request\\n    component, which would otherwise reopen private/metadata webhooks): resolve the\\n    host and reject if any IP is blocked. On top of the floor, run the shared SSRF\\n    framework (``validate_and_resolve_url``) for the allowlist / CGNAT / ``is_global``\\n    extras and pinned IPs. The returned IPs let the dispatch client pin DNS (closing\\n    the rebind window). ``LANGFLOW_A2A_ALLOW_PRIVATE_WEBHOOKS`` skips the IP check for\\n    a trusted internal network (returns ``[]``: nothing to pin).\\n\\n    Raises ``ValueError`` when the URL is unsafe. Returns the validated IPs (framework\\n    IPs, falling back to the floor-resolved IPs when the global toggle is off), or\\n    ``[]`` when private webhooks are allowed. Used at registration (set_info) and\\n    re-run at dispatch.\\n    \\\"\\\"\\\"\\n    parsed = urlparse(url)\\n    if parsed.scheme not in (\\\"http\\\", \\\"https\\\"):\\n        msg = \\\"webhook url must be http or https\\\"\\n        raise ValueError(msg)\\n    if not parsed.hostname:\\n        msg = \\\"webhook url has no host\\\"\\n        raise ValueError(msg)\\n    if get_settings_service().settings.a2a_allow_private_webhooks:\\n        return []\\n    try:\\n        # Resolve/validate the SAME host httpx connects to (IDNA/punycode raw_host), not the\\n        # unicode urlparse hostname, so an IDN webhook is pinned/resolved by the exact ASCII host\\n        # the connection uses (else the pin silently misses: TOCTOU rebind for IDN hosts). httpx.URL\\n        # raises InvalidURL (not ValueError) for an IDNA-invalid host, so keep it inside the try.\\n        host = webhook_pin_host(url)\\n        # Hard floor: reject private/metadata IPs even when global SSRF protection is off\\n        # (validate_and_resolve_url returns [] with NO enforcement in that case).\\n        # resolve_hostname handles IP-literal hosts too; the blocking resolve runs off-loop.\\n        floor_ips = await asyncio.to_thread(resolve_hostname, host)\\n        blocked = [ip for ip in floor_ips if is_ip_blocked(ip)]\\n        if blocked:\\n            msg = f\\\"webhook url resolves to a blocked address: {', '.join(blocked)}\\\"\\n            raise ValueError(msg)\\n        # Then the framework check for allowlist / CGNAT / is_global extras + pinned IPs.\\n        _url, validated_ips = await asyncio.to_thread(validate_and_resolve_url, url)\\n    except httpx.InvalidURL as exc:\\n        # Callers only guard ValueError; without translating this an IDNA-invalid host would 500 the\\n        # caller (or escape dispatch) instead of failing closed as an unsafe webhook.\\n        msg = f\\\"webhook url has an invalid host: {exc}\\\"\\n        raise ValueError(msg) from exc\\n    except SSRFProtectionError as exc:\\n        msg = f\\\"webhook url is not allowed: {exc}\\\"\\n        raise ValueError(msg) from exc\\n    # Fall back to the floor IPs so dispatch can still DNS-pin with the global toggle off.\\n    return validated_ips or floor_ips\\n\\n\\nasync def folder_auth_type(flow: Flow, session: AsyncSession) -> str:\\n    \\\"\\\"\\\"Read the flow's folder ``auth_type`` (``\\\"none\\\"`` | ``\\\"apikey\\\"`` | ``\\\"oauth\\\"``).\\n\\n    The single source of truth for what the card advertises (resolve_card_security)\\n    and what the JSON-RPC route enforces, so the two can't drift. Plaintext read,\\n    no decrypt. No folder / missing folder -> ``\\\"none\\\"`` (public).\\n    \\\"\\\"\\\"\\n    if flow.folder_id is None:\\n        return \\\"none\\\"\\n    # Query the folder explicitly; lazy-loading flow.folder would raise in async.\\n    folder = (await session.exec(select(Folder).where(Folder.id == flow.folder_id))).first()\\n    return (folder.auth_settings or {}).get(\\\"auth_type\\\", \\\"none\\\") if folder else \\\"none\\\"\\n\\n\\nasync def resolve_card_security(\\n    flow: Flow,\\n    session: AsyncSession,\\n) -> tuple[dict[str, a2a_types.SecurityScheme] | None, list[dict[str, list[str]]] | None]:\\n    \\\"\\\"\\\"Reflect the flow's folder auth onto the A2A card (securitySchemes, security).\\n\\n    Reflects what the JSON-RPC route enforces. Returns ``(None, None)`` when there\\n    is no API-key requirement.\\n    \\\"\\\"\\\"\\n    # apikey and oauth both require an owner-scoped x-api-key at the A2A transport: oauth is\\n    # fronted by an external broker, but the transport itself still takes an api key (mirrors\\n    # mcp_projects.verify_project_auth), so both advertise the same apiKey scheme.\\n    if await folder_auth_type(flow, session) in (\\\"apikey\\\", \\\"oauth\\\"):\\n        scheme = a2a_types.SecurityScheme(\\n            a2a_types.APIKeySecurityScheme(\\n                in_=a2a_types.In.header,\\n                name=A2A_APIKEY_HEADER,\\n                description=\\\"API key passed in the x-api-key header.\\\",\\n            )\\n        )\\n        return {A2A_APIKEY_SCHEME_NAME: scheme}, [{A2A_APIKEY_SCHEME_NAME: []}]\\n\\n    # \\\"none\\\" / missing -> advertise no security (public agent).\\n    return None, None\\n\\n\\nasync def build_agent_card(flow: Flow, *, rpc_url: str, session: AsyncSession) -> dict:\\n    \\\"\\\"\\\"Build a spec-valid A2A agent card (JSON-ready dict) for an agent flow.\\n\\n    The caller owns gating (flow_type == AGENT, a2a_enabled, the server flag)\\n    and 404s when those fail. ``rpc_url`` is the per-flow JSON-RPC endpoint\\n    advertised as the card's ``url``; F3 finalizes that path.\\n    \\\"\\\"\\\"\\n    overrides = flow.a2a_card_overrides if isinstance(flow.a2a_card_overrides, dict) else {}\\n    name = _override_str(overrides, \\\"name\\\") or flow.name\\n    description = _override_str(overrides, \\\"description\\\") or flow.description or f\\\"A2A agent for flow {flow.name}\\\"\\n    # No per-flow version field exists on Flow; fall back to the langflow version.\\n    version = _override_str(overrides, \\\"version\\\") or get_version_info()[\\\"version\\\"]\\n\\n    # Builds the graph from flow.data and injects a session_id property. A flow\\n    # can be flagged for A2A with empty/unbuildable data, so degrade to an empty\\n    # input contract rather than 500ing the public discovery endpoint.\\n    try:\\n        # json_schema_from_flow does a full, synchronous graph build; offload it\\n        # so this public endpoint never blocks the event loop.\\n        input_schema = await asyncio.to_thread(json_schema_from_flow, flow, require_api_editable=False)\\n    except Exception:  # noqa: BLE001 - any graph build failure degrades, not crashes\\n        logger.warning(\\\"Could not build A2A input schema for flow %s; serving empty input contract\\\", flow.id)\\n        input_schema = dict(_EMPTY_INPUT_SCHEMA)\\n\\n    skill = a2a_types.AgentSkill(\\n        id=str(flow.id),\\n        name=name,\\n        description=description,\\n        tags=_override_str_list(overrides, \\\"tags\\\") or [\\\"langflow\\\"],\\n        examples=_override_str_list(overrides, \\\"examples\\\"),\\n        input_modes=[\\\"application/json\\\"],\\n        output_modes=[\\\"application/json\\\"],\\n    )\\n    # streaming / push_notifications must be explicit, or exclude_none drops them.\\n    # Both match the handler card's capabilities: streaming gates message/stream +\\n    # tasks/resubscribe; push_notifications gates the tasks/pushNotificationConfig methods.\\n    capabilities = a2a_types.AgentCapabilities(streaming=True, push_notifications=True)\\n    security_schemes, security = await resolve_card_security(flow, session)\\n\\n    card = a2a_types.AgentCard(\\n        name=name,\\n        description=description,\\n        url=rpc_url,\\n        version=version,\\n        protocol_version=A2A_PROTOCOL_VERSION,\\n        capabilities=capabilities,\\n        default_input_modes=[\\\"application/json\\\"],\\n        default_output_modes=[\\\"application/json\\\"],\\n        skills=[skill],\\n        security_schemes=security_schemes,\\n        security=security,\\n    )\\n\\n    card_dict = card.model_dump(mode=\\\"json\\\", by_alias=True, exclude_none=True)\\n    # AgentSkill has no inputSchema field; inject the flow schema post-dump.\\n    card_dict[\\\"skills\\\"][0][\\\"inputSchema\\\"] = input_schema\\n    return card_dict\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/agentic_mcp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"60f008264c947335eaeb6f30012d391949eaeef266fb0e67160b8f82bb34db66\",\"content\":\"\\\"\\\"\\\"Streamable-HTTP transport for the ``langflow-mcp`` (lfx) FastMCP server.\\n\\nExposes the single Langflow MCP toolkit \u2014 flow authoring, execution, and\\n``run_assistant`` \u2014 at ``/api/v1/agentic/mcp`` so external MCP clients can\\nreach the running Langflow server without spawning a local stdio process.\\n\\nThe mounted server is ``lfx.mcp.server``: the same tool definitions the local\\n``lfx-mcp`` stdio bridge ships, so there is exactly one MCP toolkit. Every tool\\ncall goes through the REST API in loopback with the caller's own credentials\\n(taken from the request headers), so authorization is enforced by the API on\\nevery operation and no tool ever touches the database directly. The ``login``\\ntool is excluded over HTTP: the caller is already authenticated, and accepting\\ncredentials/server URLs from tool arguments would be a credential-forwarding\\nsurface.\\n\\nThe mount itself is NOT gated on ``agentic_experience``. Every tool here is a\\nREST call the API already authorizes, and the ``lfx-mcp`` stdio bridge serves\\nthe same toolkit ungated -- gating the whole mount would hold 32 ungated tools\\nhostage to the one tool that needs the gate, and make HTTP arbitrarily weaker\\nthan stdio for no security gain. Instead ``run_assistant`` alone is excluded\\nwhile the gate is off, since it is the only tool that reaches the assistant's\\ncode-generating endpoints.\\n\\\"\\\"\\\"\\n\\nfrom contextvars import ContextVar\\nfrom typing import Any\\n\\nfrom fastapi import APIRouter, HTTPException, Request, Response\\nfrom lfx.log.logger import logger\\nfrom lfx.mcp.client import LangflowClient\\nfrom lfx.mcp.server import client_scope\\nfrom lfx.mcp.server import mcp as lfx_mcp\\nfrom mcp import types\\nfrom mcp.server import Server\\n\\nfrom langflow.api.utils import CurrentActiveMCPUser, DbSession\\nfrom langflow.api.v1.mcp import ResponseNoOp, StreamableHTTP\\nfrom langflow.services.deps import get_settings_service\\n\\nrouter = APIRouter(prefix=\\\"/agentic/mcp\\\", tags=[\\\"agentic-mcp\\\"], include_in_schema=False)\\n\\n# login() would accept credentials and an arbitrary server_url from tool\\n# arguments; the route already authenticates the caller, so keep it stdio-only.\\n_HTTP_EXCLUDED_TOOLS = frozenset({\\\"login\\\"})\\n\\n# run_assistant drives the assistant's codegen endpoints, which agentic_experience gates.\\n_AGENTIC_GATED_TOOLS = frozenset({\\\"run_assistant\\\"})\\n\\n\\ndef _excluded_tools() -> frozenset[str]:\\n    \\\"\\\"\\\"Tools hidden from this transport for the current request.\\\"\\\"\\\"\\n    if get_settings_service().settings.agentic_experience:\\n        return _HTTP_EXCLUDED_TOOLS\\n    return _HTTP_EXCLUDED_TOOLS | _AGENTIC_GATED_TOOLS\\n\\n\\ncurrent_loopback_client_ctx: ContextVar[LangflowClient | None] = ContextVar(\\\"current_loopback_client_ctx\\\", default=None)\\n\\nserver: Server = Server(\\\"langflow-mcp\\\")\\n\\n\\ndef _loopback_client(request: Request) -> LangflowClient:\\n    \\\"\\\"\\\"Build a REST client for this server bound to the caller's own credentials.\\n\\n    The raw auth headers are forwarded verbatim, so the loopback calls carry\\n    exactly the identity the route authenticated \u2014 no key minting, no\\n    impersonation surface.\\n    \\\"\\\"\\\"\\n    authorization = request.headers.get(\\\"Authorization\\\", \\\"\\\")\\n    access_token = authorization.removeprefix(\\\"Bearer \\\").strip() or None\\n    return LangflowClient(\\n        server_url=str(request.base_url).rstrip(\\\"/\\\"),\\n        api_key=request.headers.get(\\\"x-api-key\\\"),\\n        access_token=access_token,\\n    )\\n\\n\\n@server.list_prompts()\\nasync def handle_list_prompts() -> list[types.Prompt]:\\n    return []\\n\\n\\n@server.list_resources()\\nasync def handle_list_resources() -> list[types.Resource]:\\n    return []\\n\\n\\n@server.list_tools()\\nasync def handle_list_tools() -> list[types.Tool]:\\n    excluded = _excluded_tools()\\n    return [tool for tool in await lfx_mcp.list_tools() if tool.name not in excluded]\\n\\n\\n@server.call_tool(validate_input=False)\\nasync def handle_call_tool(name: str, arguments: dict[str, Any]) -> Any:\\n    \\\"\\\"\\\"Delegate to the lfx FastMCP server with the caller's loopback client bound.\\n\\n    ``validate_input=False`` mirrors FastMCP's own transport registration;\\n    FastMCP still validates the final arguments via pydantic. The shared\\n    lowlevel ``request_ctx`` contextvar makes FastMCP's Context (progress/log\\n    notifications) work through this delegation unchanged.\\n    \\\"\\\"\\\"\\n    if name in _HTTP_EXCLUDED_TOOLS:\\n        msg = f\\\"Tool '{name}' is not available over HTTP\\\"\\n        raise ValueError(msg)\\n    if name in _excluded_tools():\\n        msg = (\\n            f\\\"Tool '{name}' requires the Langflow Assistant, which is disabled on this server \\\"\\n            \\\"(LANGFLOW_AGENTIC_EXPERIENCE is not enabled). The other tools remain available.\\\"\\n        )\\n        raise ValueError(msg)\\n    client = current_loopback_client_ctx.get()\\n    if client is None:\\n        msg = \\\"Authenticated client is unavailable for this MCP request\\\"\\n        raise ValueError(msg)\\n    with client_scope(client):\\n        return await lfx_mcp.call_tool(name, arguments)\\n\\n\\n_streamable_http = StreamableHTTP(server)\\n\\n\\nasync def stop_agentic_streamable_http_manager() -> None:\\n    await _streamable_http.stop()\\n\\n\\nstreamable_http_route_config = {\\n    \\\"methods\\\": [\\\"GET\\\", \\\"POST\\\", \\\"DELETE\\\"],\\n    \\\"response_class\\\": ResponseNoOp,\\n}\\n\\n\\n@router.head(\\\"\\\")\\nasync def agentic_mcp_health() -> Response:\\n    return Response()\\n\\n\\n@router.api_route(\\\"\\\", **streamable_http_route_config)\\n@router.api_route(\\\"/\\\", **streamable_http_route_config)\\nasync def handle_agentic_streamable_http(\\n    request: Request, current_user: CurrentActiveMCPUser, db: DbSession\\n) -> Response:\\n    \\\"\\\"\\\"Dispatch one MCP request, with the caller's loopback client bound.\\n\\n    ``current_user`` only enforces authentication -- the loopback client carries the caller's\\n    own headers, so every tool call re-authenticates at the REST API.\\n\\n    ``db`` is the very session the auth dependency opened (same cached dependency), and FastAPI\\n    would hold it open for the whole request, tool call included. Every tool then issues a\\n    loopback REST call that needs its own connection, and on SQLite it waits on the one this\\n    request is still holding until ``busy_timeout`` (30s) kills it -- so the mount deadlocks on\\n    the default database. Authentication is finished by now and nothing below reads the session,\\n    so release it before dispatching.\\n    \\\"\\\"\\\"\\n    del current_user\\n    await db.close()\\n    # start() is idempotent; called here so the session manager only runs once the endpoint is used.\\n    await _streamable_http.start()\\n    context_token = current_loopback_client_ctx.set(_loopback_client(request))\\n    try:\\n        manager = _streamable_http.get_manager()\\n        await manager.handle_request(request.scope, request.receive, request._send)  # noqa: SLF001\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        await logger.aexception(f\\\"Error handling agentic MCP Streamable HTTP request: {exc!s}\\\")\\n        raise HTTPException(status_code=500, detail=\\\"Internal server error in agentic MCP transport\\\") from exc\\n    finally:\\n        current_loopback_client_ctx.reset(context_token)\\n    return ResponseNoOp()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/api_key.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"504b753cd6c76027d6d8457721a501575caa6d9ae1a2cfc058d85ef98b0e2179\",\"content\":\"from uuid import UUID\\n\\nfrom fastapi import APIRouter, HTTPException, Response\\nfrom lfx.services.authorization import AuthorizationMutation, AuthorizationMutationKind\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.schemas import ApiKeyCreateRequest, ApiKeysResponse\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.authorization.lifecycle import safe_identity_mutation_committed, stage_identity_mutation\\nfrom langflow.services.authorization.utils import audit_decision\\n\\n# Assuming you have these methods in your service layer\\nfrom langflow.services.database.models.api_key.crud import create_api_key, delete_api_key, get_api_keys\\nfrom langflow.services.database.models.api_key.model import ApiKeyCreate, UnmaskedApiKeyRead\\nfrom langflow.services.deps import get_authorization_service, get_settings_service\\n\\nrouter = APIRouter(tags=[\\\"APIKey\\\"], prefix=\\\"/api_key\\\")\\n\\n\\n@router.get(\\\"/\\\", include_in_schema=False)\\nasync def get_api_keys_route(\\n    db: DbSession,\\n    current_user: CurrentActiveUser,\\n) -> ApiKeysResponse:\\n    try:\\n        user_id = current_user.id\\n        api_keys = await get_api_keys(db, user_id)\\n        return ApiKeysResponse(total_count=len(api_keys), user_id=user_id, api_keys=api_keys)\\n    except Exception as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n\\n\\n@router.post(\\\"/\\\", include_in_schema=False)\\nasync def create_api_key_route(\\n    req: ApiKeyCreate,\\n    current_user: CurrentActiveUser,\\n    db: DbSession,\\n) -> UnmaskedApiKeyRead:\\n    try:\\n        user_id = current_user.id\\n        created_key = await create_api_key(db, req, user_id=user_id)\\n    except PermissionError as e:\\n        await db.rollback()\\n        raise HTTPException(status_code=403, detail=str(e)) from e\\n    except Exception as e:\\n        await db.rollback()\\n        raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.API_KEY_CREATED,\\n        entity_id=created_key.id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(current_user.id,),\\n        policy_relevant_fields=(\\\"is_active\\\", \\\"expires_at\\\"),\\n    )\\n    authorization_service = get_authorization_service()\\n    try:\\n        await db.flush()\\n        await stage_identity_mutation(authorization_service, db, mutation)\\n        await db.commit()\\n    except Exception as e:\\n        await db.rollback()\\n        raise HTTPException(status_code=500, detail=\\\"Failed to finalize API key creation.\\\") from e\\n\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"api_key:create\\\",\\n        obj=f\\\"api_key:{created_key.id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"secret_material_in_event\\\": False},\\n    )\\n    return created_key\\n\\n\\n@router.delete(\\\"/{api_key_id}\\\", include_in_schema=False)\\nasync def delete_api_key_route(\\n    api_key_id: UUID,\\n    db: DbSession,\\n    current_user: CurrentActiveUser,\\n):\\n    try:\\n        await delete_api_key(db, api_key_id, current_user.id)\\n    except ValueError as e:\\n        raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.API_KEY_DELETED,\\n        entity_id=api_key_id,\\n        actor_user_id=current_user.id,\\n        affected_user_ids=(current_user.id,),\\n        policy_relevant_fields=(\\\"revoked\\\",),\\n    )\\n    authorization_service = get_authorization_service()\\n    await db.flush()\\n    await stage_identity_mutation(authorization_service, db, mutation)\\n    await db.commit()\\n    await safe_identity_mutation_committed(authorization_service, mutation)\\n    await audit_decision(\\n        user_id=current_user.id,\\n        action=\\\"api_key:delete\\\",\\n        obj=f\\\"api_key:{api_key_id}\\\",\\n        result=\\\"allow\\\",\\n        details={\\\"revocation\\\": \\\"effective_after_commit\\\"},\\n    )\\n    return {\\\"detail\\\": \\\"API Key deleted\\\"}\\n\\n\\n@router.post(\\\"/store\\\", include_in_schema=False)\\nasync def save_store_api_key(\\n    api_key_request: ApiKeyCreateRequest,\\n    response: Response,\\n    current_user: CurrentActiveUser,\\n    db: DbSession,\\n):\\n    settings_service = get_settings_service()\\n    auth_settings = settings_service.auth_settings\\n\\n    try:\\n        api_key = api_key_request.api_key\\n\\n        # Encrypt the API key\\n        encrypted = auth_utils.encrypt_api_key(api_key)\\n        current_user.store_api_key = encrypted\\n        db.add(current_user)\\n        await db.commit()\\n\\n        response.set_cookie(\\n            \\\"apikey_tkn_lflw\\\",\\n            encrypted,\\n            httponly=auth_settings.ACCESS_HTTPONLY,\\n            samesite=auth_settings.ACCESS_SAME_SITE,\\n            secure=auth_settings.ACCESS_SECURE,\\n            expires=None,  # Set to None to make it a session cookie\\n            domain=auth_settings.COOKIE_DOMAIN,\\n        )\\n\\n    except Exception as e:\\n        raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n    return {\\\"detail\\\": \\\"API Key saved\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/auth_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e058d10a25b8793337cc5bda76ad28588cad2923d51daedafdbfabd26cda21f3\",\"content\":\"from typing import Any\\n\\nfrom pydantic import SecretStr\\n\\nfrom langflow.services.auth.mcp_encryption import decrypt_auth_settings, encrypt_auth_settings\\nfrom langflow.services.database.models.folder.model import Folder\\n\\n\\ndef handle_auth_settings_update(\\n    existing_project: Folder,\\n    new_auth_settings: dict | Any | None,\\n) -> dict[str, bool]:\\n    \\\"\\\"\\\"Handle auth settings update including encryption/decryption and MCP Composer logic.\\n\\n    Args:\\n        existing_project: The project being updated (modified in-place)\\n        new_auth_settings: New auth settings (could be dict, Pydantic model, or None)\\n\\n    Returns:\\n        Dict containing:\\n        - should_start_composer: bool\\n        - should_stop_composer: bool\\n    \\\"\\\"\\\"\\n    # Get current auth type before update\\n    current_auth_type = None\\n    decrypted_current = None\\n    if existing_project.auth_settings:\\n        current_auth_type = existing_project.auth_settings.get(\\\"auth_type\\\")\\n        # Only decrypt if we need access to sensitive fields (for preserving masked values)\\n        if current_auth_type in [\\\"oauth\\\", \\\"apikey\\\"]:\\n            decrypted_current = decrypt_auth_settings(existing_project.auth_settings)\\n\\n    if new_auth_settings is None:\\n        # Explicitly set to None - clear auth settings\\n        existing_project.auth_settings = None\\n        # If we were using OAuth, stop the composer\\n        return {\\n            \\\"should_start_composer\\\": False,\\n            \\\"should_stop_composer\\\": current_auth_type == \\\"oauth\\\",\\n            \\\"should_handle_composer\\\": current_auth_type == \\\"oauth\\\",\\n            \\\"new_auth_type\\\": None,\\n        }\\n\\n    # Handle different input types (dict vs Pydantic model)\\n    if isinstance(new_auth_settings, dict):\\n        auth_dict = new_auth_settings.copy()\\n    else:\\n        # Pydantic model - use python mode to get raw values without SecretStr masking\\n        auth_dict = new_auth_settings.model_dump(mode=\\\"python\\\", exclude_none=True)\\n\\n        # Handle SecretStr fields\\n        secret_fields = [\\\"api_key\\\", \\\"oauth_client_secret\\\"]\\n        for field in secret_fields:\\n            field_val = getattr(new_auth_settings, field, None)\\n            if isinstance(field_val, SecretStr):\\n                auth_dict[field] = field_val.get_secret_value()\\n\\n    new_auth_type = auth_dict.get(\\\"auth_type\\\")\\n\\n    # Handle masked secret fields from frontend\\n    # If frontend sends back \\\"*******\\\" for a secret field, preserve the existing value\\n    if decrypted_current:\\n        secret_fields = [\\\"oauth_client_secret\\\", \\\"api_key\\\"]\\n        for field in secret_fields:\\n            if field in auth_dict and auth_dict[field] == \\\"*******\\\" and field in decrypted_current:\\n                auth_dict[field] = decrypted_current[field]\\n\\n    # Encrypt and store the auth settings\\n    existing_project.auth_settings = encrypt_auth_settings(auth_dict)\\n\\n    # Determine MCP Composer actions\\n    should_start_composer = new_auth_type == \\\"oauth\\\"\\n    should_stop_composer = current_auth_type == \\\"oauth\\\" and new_auth_type != \\\"oauth\\\"\\n    should_handle_composer = current_auth_type == \\\"oauth\\\" or new_auth_type == \\\"oauth\\\"\\n\\n    return {\\n        \\\"should_start_composer\\\": should_start_composer,\\n        \\\"should_stop_composer\\\": should_stop_composer,\\n        \\\"should_handle_composer\\\": should_handle_composer,\\n        \\\"new_auth_type\\\": new_auth_type,\\n    }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_audit.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"00cddfc1772b5c4b04c72e9eb6bbc4c42e25d61e436d2054824456b92bb01e30\",\"content\":\"\\\"\\\"\\\"Admin-only query endpoint for the ``authz_audit_log`` table.\\n\\nThe OSS guards write a row per authorization decision (allow / deny /\\nowner_override). Without a read API operators have to query the DB by hand to\\ninvestigate \\\"why was this denied?\\\" \u2014 this router exposes the table behind a\\nsuperuser-only filter surface so support and compliance flows can use it\\nwithout direct DB access.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query\\nfrom pydantic import BaseModel\\nfrom sqlalchemy import or_\\nfrom sqlmodel import col, select\\n\\nfrom langflow.api.utils import DbSession\\nfrom langflow.services.auth.utils import get_current_active_superuser\\nfrom langflow.services.database.models.auth import AuthzAuditLog\\nfrom langflow.services.database.models.user.model import User\\n\\nrouter = APIRouter(prefix=\\\"/authz/audit\\\", tags=[\\\"Authorization\\\"], include_in_schema=False)\\n\\n_MAX_PAGE_SIZE = 200\\n\\n\\nclass AuthzAuditLogRead(BaseModel):\\n    \\\"\\\"\\\"Read-only projection of an ``AuthzAuditLog`` row.\\\"\\\"\\\"\\n\\n    id: UUID\\n    user_id: UUID | None\\n    actor_type: str | None = None\\n    actor_id: UUID | None = None\\n    action: str\\n    resource_type: str | None\\n    resource_id: UUID | None\\n    result: str\\n    details: dict | None\\n    timestamp: datetime\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\\n\\nclass AuthzAuditPage(BaseModel):\\n    \\\"\\\"\\\"Paginated audit-log response.\\\"\\\"\\\"\\n\\n    items: list[AuthzAuditLogRead]\\n    total: int\\n    page: int\\n    size: int\\n    pages: int\\n\\n\\n@router.get(\\\"\\\", response_model=AuthzAuditPage)\\n@router.get(\\\"/\\\", response_model=AuthzAuditPage)\\nasync def list_audit_log(\\n    session: DbSession,\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n    user_id: Annotated[UUID | None, Query(description=\\\"Filter by acting user id.\\\")] = None,\\n    actor_type: Annotated[\\n        str | None,\\n        Query(description=\\\"Filter by credential actor type; ``unknown`` also includes legacy rows without a type.\\\"),\\n    ] = None,\\n    actor_id: Annotated[\\n        UUID | None,\\n        Query(description=\\\"Filter by first-class credential actor UUID.\\\"),\\n    ] = None,\\n    resource_type: Annotated[\\n        str | None,\\n        Query(description=\\\"Filter by resource type slug, e.g. ``flow`` or ``deployment``.\\\"),\\n    ] = None,\\n    resource_id: Annotated[UUID | None, Query(description=\\\"Filter by resource UUID.\\\")] = None,\\n    action: Annotated[\\n        str | None,\\n        Query(description=\\\"Filter by action string, e.g. ``flow:read`` or ``share:create``.\\\"),\\n    ] = None,\\n    exclude_action: Annotated[\\n        list[str] | None,\\n        Query(description=\\\"Exclude rows whose action exactly matches any supplied value.\\\"),\\n    ] = None,\\n    result: Annotated[\\n        str | None,\\n        Query(description=\\\"Filter by audit result (``allow`` / ``deny`` / ``owner_override`` / ``skip``).\\\"),\\n    ] = None,\\n    event: Annotated[\\n        list[str] | None,\\n        Query(\\n            description=(\\n                \\\"Include only rows whose ``details.event`` class matches, e.g. ``mutation`` for \\\"\\n                \\\"things that happened and ``authorization_decision`` for permission checks.\\\"\\n            )\\n        ),\\n    ] = None,\\n    exclude_event: Annotated[\\n        list[str] | None,\\n        Query(\\n            description=(\\n                \\\"Exclude rows whose ``details.event`` class matches. Rows written before event \\\"\\n                \\\"classification existed carry no class and are always kept.\\\"\\n            )\\n        ),\\n    ] = None,\\n    since: Annotated[datetime | None, Query(description=\\\"Inclusive lower bound on ``timestamp``.\\\")] = None,\\n    until: Annotated[datetime | None, Query(description=\\\"Exclusive upper bound on ``timestamp``.\\\")] = None,\\n    page: Annotated[int, Query(ge=1)] = 1,\\n    size: Annotated[int, Query(ge=1, le=_MAX_PAGE_SIZE)] = 50,\\n) -> AuthzAuditPage:\\n    \\\"\\\"\\\"Return a paginated slice of the audit log filtered by the given query params.\\n\\n    Superuser only. The composite indexes on ``(user_id, timestamp)`` and\\n    ``(resource_type, resource_id)`` keep both \\\"show me events for user X\\\"\\n    and \\\"show me events on resource Y\\\" fast at scale.\\n    \\\"\\\"\\\"\\n    if since is not None and until is not None and since >= until:\\n        raise HTTPException(status_code=400, detail=\\\"`since` must be strictly less than `until`\\\")\\n\\n    base = select(AuthzAuditLog)\\n    if user_id is not None:\\n        base = base.where(AuthzAuditLog.user_id == user_id)\\n    if actor_type == \\\"unknown\\\":\\n        # Rows written before first-class actor identity was added retain a\\n        # NULL actor_type. The UI presents one \\\"Legacy / unknown\\\" filter, so\\n        # its backend meaning must include both historical NULLs and new\\n        # events explicitly classified as unknown.\\n        base = base.where(\\n            or_(\\n                AuthzAuditLog.actor_type == actor_type,\\n                col(AuthzAuditLog.actor_type).is_(None),\\n            )\\n        )\\n    elif actor_type is not None:\\n        base = base.where(AuthzAuditLog.actor_type == actor_type)\\n    if actor_id is not None:\\n        base = base.where(AuthzAuditLog.actor_id == actor_id)\\n    if resource_type is not None:\\n        base = base.where(AuthzAuditLog.resource_type == resource_type)\\n    if resource_id is not None:\\n        base = base.where(AuthzAuditLog.resource_id == resource_id)\\n    if action is not None:\\n        base = base.where(AuthzAuditLog.action == action)\\n    if exclude_action:\\n        base = base.where(col(AuthzAuditLog.action).not_in(exclude_action))\\n    if result is not None:\\n        base = base.where(AuthzAuditLog.result == result)\\n    # ``details`` is a JSON column; SQLAlchemy renders the index access as\\n    # ``json_extract`` on SQLite and ``->>`` on Postgres, so one expression\\n    # serves both. An untagged row (written before classification existed) has\\n    # a NULL extraction: it can never satisfy an include, and is never dropped\\n    # by an exclude, so history stays visible.\\n    event_class = col(AuthzAuditLog.details)[\\\"event\\\"].as_string()\\n    if event:\\n        base = base.where(event_class.in_(event))\\n    if exclude_event:\\n        base = base.where(or_(event_class.not_in(exclude_event), event_class.is_(None)))\\n    if since is not None:\\n        base = base.where(AuthzAuditLog.timestamp >= since)\\n    if until is not None:\\n        base = base.where(AuthzAuditLog.timestamp < until)\\n\\n    # Two queries: one COUNT(*) for pagination metadata, one for the page\\n    # window itself. SQLAlchemy's func.count is preferred over len(rows) so\\n    # we don't materialise the full result set when the user just wants\\n    # page 1 of many.\\n    from sqlalchemy import func\\n\\n    total_stmt = select(func.count()).select_from(base.subquery())\\n    total = int((await session.exec(total_stmt)).first() or 0)\\n\\n    page_stmt = (\\n        base.order_by(\\n            col(AuthzAuditLog.timestamp).desc(),\\n            col(AuthzAuditLog.id).desc(),\\n        )\\n        .offset((page - 1) * size)\\n        .limit(size)\\n    )\\n    rows = list(await session.exec(page_stmt))\\n\\n    items = [AuthzAuditLogRead.model_validate(row, from_attributes=True) for row in rows]\\n    pages = (total + size - 1) // size if total > 0 else 0\\n\\n    return AuthzAuditPage(items=items, total=total, page=page, size=size, pages=pages)\\n\\n\\n__all__ = [\\\"AuthzAuditLogRead\\\", \\\"AuthzAuditPage\\\", \\\"router\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_me.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d0f07b6ecbfcef9f40f558414c5d49522a70e990b28a8280d34ed91fd35e154\",\"content\":\"\\\"\\\"\\\"Per-user effective-permissions endpoint, used by the frontend permission gate.\\n\\nThe UI calls this once per page load with the list of resource IDs it wants to\\nrender and learns which actions to enable/disable per resource \u2014 without making\\na 403-triggering request for each one. Backed by\\n:meth:`BaseAuthorizationService.get_effective_permissions`; OSS pass-through\\nreturns every action for every ID (no policy applied) and a registered\\nauthorization plugin overrides it with a tighter implementation.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Literal\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, HTTPException, status\\nfrom pydantic import BaseModel, Field, field_validator\\nfrom sqlmodel import col, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSessionReadOnly\\nfrom langflow.services.auth.context import current_auth_context_for_authz\\nfrom langflow.services.authorization.access_ceiling import filter_actions_by_external_access_ceiling\\nfrom langflow.services.authorization.guards import should_apply_owner_override\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.file.model import File as UserFile\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.knowledge_base.model import KnowledgeBaseRecord\\nfrom langflow.services.database.models.variable.model import Variable\\nfrom langflow.services.deps import get_authorization_service\\n\\nrouter = APIRouter(prefix=\\\"/authz/me\\\", tags=[\\\"Authorization\\\"], include_in_schema=False)\\n\\n# Match the resource slugs used by ensure_*_permission helpers.\\nResourceTypeLiteral = Literal[\\n    \\\"flow\\\",\\n    \\\"deployment\\\",\\n    \\\"project\\\",\\n    \\\"knowledge_base\\\",\\n    \\\"variable\\\",\\n    \\\"file\\\",\\n    \\\"component\\\",\\n]\\n\\n# Default action vocabulary aligned with the authorization plugin's known actions.\\n_DEFAULT_ACTIONS: tuple[str, ...] = (\\\"read\\\", \\\"write\\\", \\\"execute\\\", \\\"delete\\\", \\\"create\\\")\\n_MAX_RESOURCE_IDS = 500\\n# Cap actions per request to bound the batch_enforce cartesian product\\n# (resource_ids x actions). Headroom over the 6 known actions\\n# (read/write/execute/delete/create/manage) covers future additions without\\n# letting a client request `[\\\"read\\\"] * 100000` to flood the enforcer.\\n_MAX_ACTIONS = 10\\n\\n_RESOURCE_OWNER_LOOKUPS: dict[str, tuple[type, str]] = {\\n    \\\"flow\\\": (Flow, \\\"user_id\\\"),\\n    \\\"deployment\\\": (Deployment, \\\"user_id\\\"),\\n    \\\"project\\\": (Folder, \\\"user_id\\\"),\\n    \\\"knowledge_base\\\": (KnowledgeBaseRecord, \\\"user_id\\\"),\\n    \\\"variable\\\": (Variable, \\\"user_id\\\"),\\n    \\\"file\\\": (UserFile, \\\"user_id\\\"),\\n}\\n\\n\\nclass EffectivePermissionsRequest(BaseModel):\\n    \\\"\\\"\\\"Body for :func:`get_effective_permissions`.\\\"\\\"\\\"\\n\\n    resource_type: ResourceTypeLiteral\\n    resource_ids: list[UUID] = Field(\\n        ...,\\n        description=\\\"Resource IDs to evaluate. Capped at 500 per request to keep batch_enforce bounded.\\\",\\n    )\\n    actions: list[str] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Actions to check. Each entry is lowercased and de-duplicated; the list is \\\"\\n            f\\\"capped at {_MAX_ACTIONS}. Defaults to read/write/execute/delete/create.\\\"\\n        ),\\n    )\\n    domain: str = Field(\\n        default=\\\"*\\\",\\n        description=\\\"Authorization domain \u2014 typically ``project:{folder_id}`` or ``*``.\\\",\\n    )\\n\\n    @field_validator(\\\"actions\\\")\\n    @classmethod\\n    def _normalize_actions(cls, value: list[str] | None) -> list[str] | None:\\n        \\\"\\\"\\\"Lowercase, strip, de-duplicate (order-preserving), and cap the actions list.\\n\\n        Returns ``None`` when the caller omitted the field (handler substitutes\\n        ``_DEFAULT_ACTIONS``). An empty list after normalization also returns\\n        ``None`` so the default kicks in rather than producing an empty cartesian\\n        product downstream.\\n        \\\"\\\"\\\"\\n        if value is None:\\n            return None\\n        seen: set[str] = set()\\n        normalized: list[str] = []\\n        for raw in value:\\n            if not isinstance(raw, str):\\n                # Pydantic field_validators must raise ValueError (not TypeError)\\n                # to be wrapped into a ValidationError -> HTTP 422 response.\\n                msg = \\\"actions must be strings\\\"\\n                raise ValueError(msg)  # noqa: TRY004\\n            cleaned = raw.strip().lower()\\n            if not cleaned or cleaned in seen:\\n                continue\\n            seen.add(cleaned)\\n            normalized.append(cleaned)\\n        if len(normalized) > _MAX_ACTIONS:\\n            msg = f\\\"actions capped at {_MAX_ACTIONS} unique entries\\\"\\n            raise ValueError(msg)\\n        return normalized or None\\n\\n\\nclass EffectivePermissionsResponse(BaseModel):\\n    \\\"\\\"\\\"Response: ``{resource_id: [allowed_actions]}``.\\\"\\\"\\\"\\n\\n    resource_type: ResourceTypeLiteral\\n    permissions: dict[UUID, list[str]]\\n\\n\\nasync def _owned_resource_ids(\\n    *,\\n    session: AsyncSession,\\n    resource_type: str,\\n    resource_ids: list[UUID],\\n    user_id: UUID,\\n) -> set[UUID]:\\n    \\\"\\\"\\\"Return requested resource IDs owned by ``user_id``.\\\"\\\"\\\"\\n    lookup = _RESOURCE_OWNER_LOOKUPS.get(resource_type)\\n    if lookup is None or not resource_ids:\\n        return set()\\n    model, owner_attr = lookup\\n    stmt = select(model.id).where(\\n        col(model.id).in_(resource_ids),\\n        getattr(model, owner_attr) == user_id,\\n    )\\n    return set((await session.exec(stmt)).all())\\n\\n\\nasync def _apply_owner_permissions(\\n    *,\\n    session: AsyncSession,\\n    permissions: dict[UUID, list[str]],\\n    resource_type: str,\\n    resource_ids: list[UUID],\\n    actions: tuple[str, ...],\\n    user_id: UUID,\\n) -> dict[UUID, list[str]]:\\n    \\\"\\\"\\\"Mirror route guard owner override for the UI permission endpoint.\\\"\\\"\\\"\\n    normalized = {resource_id: list(permissions.get(resource_id, [])) for resource_id in resource_ids}\\n    if not await should_apply_owner_override():\\n        return normalized\\n\\n    owned_ids = await _owned_resource_ids(\\n        session=session,\\n        resource_type=resource_type,\\n        resource_ids=resource_ids,\\n        user_id=user_id,\\n    )\\n    for resource_id in owned_ids:\\n        allowed = dict.fromkeys(normalized.get(resource_id, []))\\n        allowed.update(dict.fromkeys(actions))\\n        normalized[resource_id] = list(allowed)\\n    return normalized\\n\\n\\n@router.post(\\\"/permissions\\\", response_model=EffectivePermissionsResponse)\\nasync def get_effective_permissions(\\n    body: EffectivePermissionsRequest,\\n    current_user: CurrentActiveUser,\\n    session: DbSessionReadOnly,\\n) -> EffectivePermissionsResponse:\\n    \\\"\\\"\\\"Return per-resource allowed actions for the current user.\\n\\n    Use this to render the UI permission gate (greyed-out buttons etc.) without\\n    flooding the audit log with denied probes. Empty list for a resource_id\\n    means the user cannot perform any of the requested actions on that resource.\\n    \\\"\\\"\\\"\\n    if not body.resource_ids:\\n        return EffectivePermissionsResponse(resource_type=body.resource_type, permissions={})\\n    if len(body.resource_ids) > _MAX_RESOURCE_IDS:\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            detail=f\\\"resource_ids capped at {_MAX_RESOURCE_IDS}\\\",\\n        )\\n\\n    authz = get_authorization_service()\\n    actions = tuple(body.actions) if body.actions else _DEFAULT_ACTIONS\\n    permissions = await authz.get_effective_permissions(\\n        user_id=current_user.id,\\n        resource_type=body.resource_type,\\n        resource_ids=body.resource_ids,\\n        actions=actions,\\n        domain=body.domain,\\n        context={\\n            **current_auth_context_for_authz(),\\n            \\\"is_superuser\\\": current_user.is_superuser,\\n        },\\n    )\\n    permissions = await _apply_owner_permissions(\\n        session=session,\\n        permissions=permissions,\\n        resource_type=body.resource_type,\\n        resource_ids=body.resource_ids,\\n        actions=actions,\\n        user_id=current_user.id,\\n    )\\n    permissions = {\\n        resource_id: filter_actions_by_external_access_ceiling(allowed_actions)\\n        for resource_id, allowed_actions in permissions.items()\\n    }\\n    return EffectivePermissionsResponse(\\n        resource_type=body.resource_type,\\n        permissions=permissions,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/authz_role_assignments.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c3f757870adee61d14b1650c91f97eb7e76ed0aaf99297d9bbfcaa02aa0aac6b\",\"content\":\"\\\"\\\"\\\"CRUD API for authz_role_assignment rows.\\n\\nAssignments bind a user to a role within an optional domain. The actual policy\\ncompilation (rule rows in the policy-rule table) is performed by the\\nauthorization plugin \u2014 OSS keeps the assignment table and invalidates the\\nplugin's cache on write so the next ``enforce()`` picks up the change.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query, Request, Response, status\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization import (\\n    AuthorizationMutation,\\n    AuthorizationMutationKind,\\n    AuthorizationMutationRejected,\\n)\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.schemas.authz_role_assignments import (\\n    RoleAssignmentCreate,\\n    RoleAssignmentGrantSummary,\\n    RoleAssignmentRead,\\n)\\nfrom langflow.services.authorization.audit import AUDIT_EVENT_ACCESS, AUDIT_EVENT_MUTATION\\nfrom langflow.services.authorization.lifecycle import (\\n    acquire_identity_mutation_lock,\\n    safe_identity_mutation_committed,\\n    stage_identity_mutation,\\n    validate_identity_mutation,\\n)\\nfrom langflow.services.authorization.utils import audit_decision\\nfrom langflow.services.database.models.auth import AuthzRole, AuthzRoleAssignment, AuthzRoleAssignmentGrant\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_authorization_service\\n\\nrouter = APIRouter(prefix=\\\"/authz/role-assignments\\\", tags=[\\\"Authorization\\\"], include_in_schema=False)\\n\\n# See ``authz_roles._LIST_MAX_LIMIT`` \u2014 same bound, applied to assignments.\\n_LIST_MAX_LIMIT = 200\\n_LIST_DEFAULT_LIMIT = 100\\n\\n\\nasync def _audit_deny(*, user_id: UUID, action: str, obj: str, status_code: int, reason: str) -> None:\\n    await audit_decision(\\n        user_id=user_id,\\n        action=action,\\n        obj=obj,\\n        result=\\\"deny\\\",\\n        details={\\\"event\\\": AUDIT_EVENT_ACCESS, \\\"status_code\\\": status_code, \\\"reason\\\": reason},\\n    )\\n\\n\\nasync def _require_superuser(user, *, action: str, obj: str) -> None:\\n    if not getattr(user, \\\"is_superuser\\\", False):\\n        await _audit_deny(\\n            user_id=user.id,\\n            action=action,\\n            obj=obj,\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            reason=\\\"superuser_required\\\",\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"Superuser required to administer role assignments.\\\",\\n        )\\n\\n\\nasync def _require_superuser_dependency(request: Request, current_user: CurrentActiveUser) -> None:\\n    \\\"\\\"\\\"Run the superuser gate as a route dependency, i.e. before body validation.\\n\\n    FastAPI solves a route's ``dependencies`` before validating that route's own\\n    body, so an unauthorised caller is refused whatever they post. Gated only in\\n    the endpoint body, they first receive the same 422 field names and enum\\n    values a superuser would, which lets them map the request contract of a\\n    route they cannot invoke.\\n\\n    The in-body call is kept as well: it is the gate for anything that reaches\\n    the endpoint function without FastAPI resolving dependencies.\\n    \\\"\\\"\\\"\\n    assignment_id = request.path_params.get(\\\"assignment_id\\\", \\\"*\\\")\\n    action = \\\"role_assignment:create\\\" if request.method == \\\"POST\\\" else \\\"role_assignment:delete\\\"\\n    await _require_superuser(current_user, action=action, obj=f\\\"role_assignment:{assignment_id}\\\")\\n\\n\\nSUPERUSER_ONLY = [Depends(_require_superuser_dependency)]\\n\\n\\nasync def _assignment_reads(session, assignments: list[AuthzRoleAssignment]) -> list[RoleAssignmentRead]:\\n    \\\"\\\"\\\"Serialize effective assignments with source summaries in two queries.\\\"\\\"\\\"\\n    if not assignments:\\n        return []\\n    assignment_ids = [assignment.id for assignment in assignments]\\n    grants = (\\n        await session.exec(\\n            select(AuthzRoleAssignmentGrant)\\n            .where(AuthzRoleAssignmentGrant.assignment_id.in_(assignment_ids))\\n            .order_by(\\n                AuthzRoleAssignmentGrant.assignment_id,\\n                AuthzRoleAssignmentGrant.source_kind,\\n                AuthzRoleAssignmentGrant.provider_id,\\n                AuthzRoleAssignmentGrant.external_group,\\n            )\\n        )\\n    ).all()\\n    grants_by_assignment: dict[UUID, list[RoleAssignmentGrantSummary]] = {}\\n    for grant in grants:\\n        grants_by_assignment.setdefault(grant.assignment_id, []).append(\\n            RoleAssignmentGrantSummary.model_validate(grant)\\n        )\\n    return [\\n        RoleAssignmentRead.model_validate(assignment).model_copy(\\n            update={\\\"grant_sources\\\": grants_by_assignment.get(assignment.id, [])}\\n        )\\n        for assignment in assignments\\n    ]\\n\\n\\ndef _assignment_match(payload: RoleAssignmentCreate):\\n    domain_match = (\\n        AuthzRoleAssignment.domain_id.is_(None)\\n        if payload.domain_id is None\\n        else AuthzRoleAssignment.domain_id == payload.domain_id\\n    )\\n    return (\\n        AuthzRoleAssignment.user_id == payload.user_id,\\n        AuthzRoleAssignment.role_id == payload.role_id,\\n        AuthzRoleAssignment.domain_type == payload.domain_type,\\n        domain_match,\\n    )\\n\\n\\n@router.get(\\\"\\\", response_model=list[RoleAssignmentRead])\\n@router.get(\\\"/\\\", response_model=list[RoleAssignmentRead])\\nasync def list_assignments(\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    user_id: Annotated[UUID | None, Query(description=\\\"Filter by user\\\")] = None,\\n    role_id: Annotated[UUID | None, Query(description=\\\"Filter by role\\\")] = None,\\n    domain_type: Annotated[str | None, Query()] = None,\\n    domain_id: Annotated[UUID | None, Query()] = None,\\n    limit: Annotated[int, Query(ge=1, le=_LIST_MAX_LIMIT)] = _LIST_DEFAULT_LIMIT,\\n    offset: Annotated[int, Query(ge=0)] = 0,\\n) -> list[RoleAssignmentRead]:\\n    \\\"\\\"\\\"List role assignments scoped to one user.\\n\\n    * Omitting ``user_id`` defaults to the caller \u2014 no superuser needed.\\n    * Passing ``user_id == self.id`` is the same as omitting it.\\n    * Passing a different ``user_id`` requires superuser; otherwise 403.\\n\\n    Results are always filtered by the resolved ``user_id``. Admins who need\\n    cross-user lookups make one call per user. Paginated via ``limit`` /\\n    ``offset`` (default 100, max 200).\\n    \\\"\\\"\\\"\\n    if user_id is None:\\n        user_id = current_user.id\\n    elif user_id != current_user.id:\\n        await _require_superuser(\\n            current_user,\\n            action=\\\"role_assignment:read\\\",\\n            obj=f\\\"user:{user_id}\\\",\\n        )\\n    stmt = select(AuthzRoleAssignment).where(AuthzRoleAssignment.user_id == user_id)\\n    if role_id is not None:\\n        stmt = stmt.where(AuthzRoleAssignment.role_id == role_id)\\n    if domain_type is not None:\\n        stmt = stmt.where(AuthzRoleAssignment.domain_type == domain_type)\\n    if domain_id is not None:\\n        stmt = stmt.where(AuthzRoleAssignment.domain_id == domain_id)\\n    stmt = stmt.order_by(AuthzRoleAssignment.assigned_at.desc(), AuthzRoleAssignment.id).offset(offset).limit(limit)\\n    rows = (await session.exec(stmt)).all()\\n    return await _assignment_reads(session, list(rows))\\n\\n\\n@router.post(\\\"\\\", response_model=RoleAssignmentRead, status_code=status.HTTP_201_CREATED, dependencies=SUPERUSER_ONLY)\\n@router.post(\\\"/\\\", response_model=RoleAssignmentRead, status_code=status.HTTP_201_CREATED, dependencies=SUPERUSER_ONLY)\\nasync def create_assignment(\\n    payload: RoleAssignmentCreate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> RoleAssignmentRead:\\n    \\\"\\\"\\\"Assign a role to a user. Superuser-only.\\\"\\\"\\\"\\n    await _require_superuser(current_user, action=\\\"role_assignment:create\\\", obj=\\\"role_assignment:*\\\")\\n    authorization_service = get_authorization_service()\\n    # Let authorization plugins acquire their transaction-scoped policy-write\\n    # lock before the first canonical identity read or write. An external\\n    # compiler may need the same global lock later while staging derived policy.\\n    await acquire_identity_mutation_lock(\\n        authorization_service,\\n        session,\\n        kind=AuthorizationMutationKind.ROLE_ASSIGNMENT_CREATED,\\n        affected_user_ids=(payload.user_id,),\\n    )\\n\\n    user = await session.get(User, payload.user_id)\\n    if user is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role_assignment:create\\\",\\n            obj=\\\"role_assignment:*\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"user_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"user_id not found\\\")\\n    role = await session.get(AuthzRole, payload.role_id)\\n    if role is None:\\n        await _audit_deny(\\n            user_id=current_user.id,\\n            action=\\\"role_assignment:create\\\",\\n            obj=\\\"role_assignment:*\\\",\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            reason=\\\"role_not_found\\\",\\n        )\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"role_id not found\\\")\\n\\n    candidate = AuthzRoleAssignment(\\n        user_id=payload.user_id,\\n        role_id=payload.role_id,\\n        domain_type=payload.domain_type,\\n        domain_id=payload.domain_id,\\n        assigned_at=datetime.now(timezone.utc),\\n        assigned_by=current_user.id,\\n    )\\n    assignment = (await session.exec(select(AuthzRoleAssignment).where(*_assignment_match(payload)))).first()\\n    effective_assignment_created = assignment is None\\n    if assignment is None:\\n        assignment = candidate\\n        session.add(assignment)\\n        await session.flush()\\n    else:\\n        existing_manual = (\\n            await session.exec(\\n                select(AuthzRoleAssignmentGrant).where(\\n                    AuthzRoleAssignmentGrant.assignment_id == assignment.id,\\n                    AuthzRoleAssignmentGrant.source_kind == \\\"manual\\\",\\n                )\\n            )\\n        ).first()\\n        if existing_manual is not None:\\n            await _audit_deny(\\n                user_id=current_user.id,\\n                action=\\\"role_assignment:create\\\",\\n                obj=\\\"role_assignment:*\\\",\\n                status_code=status.HTTP_409_CONFLICT,\\n                reason=\\\"manual_assignment_already_exists\\\",\\n            )\\n            raise HTTPException(\\n                status_code=status.HTTP_409_CONFLICT,\\n                detail=\\\"Manual assignment already exists for this user/role/domain\\\"";
